import { PublishingConfig } from "../types";

const SMMBOX_BASE_URL = "https://smmbox.com/api/v1";

const fetchWithTimeout = async (url: string, options: RequestInit = {}, timeout = 35000) => {
    const controller = new AbortController();
    const id = setTimeout(() => controller.abort(), timeout);
    try {
        const response = await fetch(url, { ...options, signal: controller.signal });
        clearTimeout(id);
        return response;
    } catch (error: any) {
        clearTimeout(id);
        throw error;
    }
};

/**
 * Получает список всех групп, подключенных к SmmBox
 */
export const fetchSmmBoxGroups = async (token: string) => {
    if (!token) throw new Error("API токен SmmBox не указан");

    const response = await fetchWithTimeout(`${SMMBOX_BASE_URL}/groups`, {
        headers: {
            'Authorization': `Bearer ${token}`,
            'Accept': 'application/json'
        }
    });

    const data = await response.json();
    if (!data.success) throw new Error(data.error?.message || "Ошибка получения групп SmmBox");
    return data.response;
};

/**
 * Публикация поста через SmmBox API
 * Метод /posts/postpone позволяет планировать посты
 */
export const publishToSmmBox = async (
    config: PublishingConfig, 
    text: string, 
    imagesBase64: string[] = [], 
    publishDate?: Date
) => {
    if (!config.smmBoxToken) throw new Error("SmmBox API токен не настроен");

    // 1. Сначала найдем ID групп, которые соответствуют "Первый туристический"
    const allGroups = await fetchSmmBoxGroups(config.smmBoxToken);
    const targetGroups = allGroups.filter((g: any) => 
        g.name.toLowerCase().includes(config.targetGroupName.toLowerCase())
    );

    if (targetGroups.length === 0) {
        throw new Error(`Группа "${config.targetGroupName}" не найдена в вашем SmmBox. Подключите её или проверьте название.`);
    }

    // 2. Подготовим вложения
    const attachments: any[] = [{ type: 'text', text }];

    // Добавляем фото (SmmBox API принимает Data URI как валидный URI для фото)
    imagesBase64.forEach(img => {
        if (img && img.startsWith('data:')) {
            attachments.push({
                type: 'photo',
                original: img
            });
        }
    });

    // 3. Формируем массив постов для каждой найденной соцсети "Первого туристического"
    // Если дата не указана, ставим +5 минут от текущего времени (SmmBox требует будущее время)
    const postTime = publishDate || new Date(Date.now() + 5 * 60000);
    const unixTimestamp = Math.floor(postTime.getTime() / 1000);

    const postsData = targetGroups.map((group: any) => ({
        group: {
            id: group.id,
            social: group.social,
            type: group.type
        },
        date: unixTimestamp,
        attachments: attachments,
        options: ['from_group'] // Публиковать от имени группы
    }));

    // 4. Отправляем запрос на планирование
    const response = await fetchWithTimeout(`${SMMBOX_BASE_URL}/posts/postpone`, {
        method: 'POST',
        headers: {
            'Authorization': `Bearer ${config.smmBoxToken}`,
            'Content-Type': 'application/json',
            'Accept': 'application/json'
        },
        body: JSON.stringify({ posts: postsData })
    });

    const result = await response.json();
    if (!result.success) throw new Error(result.error?.message || "SmmBox API Error");

    return result.response;
};

