import React, { useState, useEffect } from 'react';
import { PublishingConfig } from '../types';

interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  config: PublishingConfig;
  onSave: (config: PublishingConfig) => void;
}

export const SettingsModal: React.FC<SettingsModalProps> = ({ isOpen, onClose, config, onSave }) => {
  const [formData, setFormData] = useState<PublishingConfig>(config);

  useEffect(() => {
    setFormData(config);
  }, [config]);

  if (!isOpen) return null;

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSave = () => {
    const cleanedData: PublishingConfig = {
        smmBoxToken: formData.smmBoxToken.trim(),
        targetGroupName: formData.targetGroupName.trim() || 'Первый туристический'
    };
    localStorage.setItem('tourgenius_settings', JSON.stringify(cleanedData));
    onSave(cleanedData);
    onClose();
  };

  return (
    <div className="fixed inset-0 bg-brand-dark/80 backdrop-blur-md z-[100] flex items-center justify-center p-4">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg overflow-hidden flex flex-col border-t-8 border-brand-orange">

        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
          <h2 className="text-xl font-black text-brand-dark uppercase italic tracking-tighter">Настройки SmmBox</h2>
          <button onClick={onClose} className="text-slate-300 hover:text-brand-orange text-3xl leading-none transition-colors">&times;</button>
        </div>

        <div className="p-8 space-y-8">
          <div className="bg-orange-50 p-4 rounded-2xl border border-orange-100">
            <p className="text-xs text-brand-orange font-bold leading-relaxed">
              API SmmBox позволяет публиковать посты сразу во все ваши соцсети (VK, TG, OK и др.), подключенные к аккаунту SmmBox.
            </p>
          </div>

          <div className="space-y-6">
            <div>
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">API Токен SmmBox</label>
              <input 
                type="password" 
                name="smmBoxToken" 
                value={formData.smmBoxToken} 
                onChange={handleChange} 
                className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-brand-orange outline-none transition-all font-mono text-sm" 
                placeholder="Bearer токен из настроек SmmBox"
              />
              <a 
                href="https://smmbox.com/dashboard/auth-settings/" 
                target="_blank" 
                rel="noreferrer" 
                className="text-[10px] text-blue-500 font-bold mt-2 block hover:underline"
              >
                Получить токен на сайте SmmBox →
              </a>
            </div>

            <div>
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Название группы в SmmBox</label>
              <input 
                type="text" 
                name="targetGroupName" 
                value={formData.targetGroupName} 
                onChange={handleChange} 
                className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-brand-orange outline-none transition-all font-bold" 
                placeholder="Первый туристический"
