              <p className="text-[10px] text-slate-400 mt-2">
                Мы будем искать страницы с этим названием среди ваших подключенных аккаунтов.
              </p>
            </div>
          </div>
        </div>

        <div className="p-6 bg-slate-50 border-t border-slate-100 flex gap-3">
          <button onClick={onClose} className="flex-1 px-6 py-4 bg-white border border-slate-200 text-slate-500 rounded-2xl font-black uppercase text-xs hover:bg-slate-100 transition-all">
