import React, { useState, useEffect } from 'react';
import { GeneratedContentPack, PublishingConfig, ArticleSection } from '../types';
import { publishToSmmBox } from '../services/publishingService';

interface ResultViewerProps {
  pack: GeneratedContentPack;
  pubConfig: PublishingConfig;
}

export const ResultViewer: React.FC<ResultViewerProps> = ({ pack, pubConfig }) => {
  const [activeTab, setActiveTab] = useState<'site' | 'telegram' | 'vk' | 'prompts'>('site');
  const [isEditing, setIsEditing] = useState(false);

  const [headline, setHeadline] = useState(pack.siteArticle?.headline || '');
  const [sections, setSections] = useState<ArticleSection[]>(pack.siteArticle?.sections || []);
  const [hashtags, setHashtags] = useState(pack.siteArticle?.hashtags || '');
  const [tgText, setTgText] = useState(pack.telegramPost?.content || '');
  const [vkText, setVkText] = useState(pack.vkPost?.content || '');

  const [publishing, setPublishing] = useState<boolean>(false);
  const [pubStatus, setPubStatus] = useState<{ success?: boolean; msg?: string }>({});
  const [scheduleDate, setScheduleDate] = useState<string>('');

  useEffect(() => {
    setHeadline(pack.siteArticle?.headline || '');
    setSections(pack.siteArticle?.sections || []);
    setHashtags(pack.siteArticle?.hashtags || '');
    setTgText(pack.telegramPost?.content || '');
    setVkText(pack.vkPost?.content || '');
  }, [pack]);

  const handleSmmBoxPublish = async (text: string) => {
    setPublishing(true);
    setPubStatus({});
    const dateObj = scheduleDate ? new Date(scheduleDate) : undefined;

    try {
      await publishToSmmBox(pubConfig, text, pack.generatedImages, dateObj);
      setPubStatus({ success: true, msg: 'Запланировано через SmmBox!' });
    } catch (e: any) {
      setPubStatus({ success: false, msg: e.message });
    } finally {
      setPublishing(false);
    }
  };

  const handleSectionChange = (index: number, field: 'heading' | 'body', value: string) => {
    const newSections = [...sections];
    newSections[index][field] = value;
    setSections(newSections);
  };

  if (pack.error) return <div className="p-10 text-center text-red-500 font-bold">{pack.error}</div>;

  return (
    <div className="bg-white rounded-[2rem] shadow-2xl overflow-hidden border border-slate-100 flex flex-col h-full animate-fade-in mb-10">
      <div className="bg-brand-dark border-b border-white/5 p-3 flex justify-between items-center">
        <div className="flex space-x-2">
          {['site', 'telegram', 'vk', 'prompts'].map((tab) => (
            <button key={tab} onClick={() => setActiveTab(tab as any)} className={`px-4 py-2 text-[10px] font-black rounded-lg uppercase tracking-widest transition-all ${activeTab === tab ? 'bg-brand-orange text-white shadow-lg' : 'text-slate-400 hover:text-white'}`}>
              {tab === 'site' ? 'Статья' : tab === 'telegram' ? 'Пост TG' : tab === 'vk' ? 'Пост VK' : 'Промпты'}
            </button>
          ))}
        </div>
        <button onClick={() => setIsEditing(!isEditing)} className={`px-4 py-2 text-[10px] font-black rounded-lg uppercase border transition-all ${isEditing ? 'bg-white text-brand-dark' : 'text-white border-white/20'}`}>
          {isEditing ? 'Сохранить' : 'Править'}
        </button>
      </div>

      <div className="p-8 overflow-y-auto flex-1 custom-scrollbar">
        {/* Publish Bar for Socials */}
        {(activeTab === 'telegram' || activeTab === 'vk') && (
          <div className="mb-6 bg-slate-50 p-6 rounded-3xl border border-slate-100 flex flex-wrap items-center justify-between gap-4 animate-fade-in">
             <div className="flex flex-col">
                <span className="text-[10px] font-black uppercase text-brand-orange tracking-widest">SmmBox Публикация</span>
                {pubStatus.msg && <span className={`text-[10px] font-bold ${pubStatus.success ? 'text-green-600' : 'text-red-600'}`}>{pubStatus.msg}</span>}
             </div>
             <div className="flex items-center gap-3">
                <input 
                  type="datetime-local" 
                  value={scheduleDate} 
                  onChange={(e) => setScheduleDate(e.target.value)} 
                  className="text-xs border border-slate-200 rounded-xl px-4 py-2.5 bg-white outline-none focus:ring-2 focus:ring-brand-orange font-mono" 
                />
                <button 
                  onClick={() => handleSmmBoxPublish(activeTab === 'telegram' ? tgText : vkText)} 
                  disabled={publishing} 
                  className="bg-brand-orange text-white text-[10px] px-8 py-3 rounded-xl font-black uppercase hover:bg-orange-600 shadow-xl shadow-orange-100 disabled:opacity-50 transition-all"
                >
                  {publishing ? 'Отправка...' : (scheduleDate ? 'Запланировать в SmmBox' : 'В эфир через SmmBox')}
                </button>
             </div>
          </div>
        )}

        {activeTab === 'site' && (
          <article className="article-font max-w-none">
            {isEditing ? (
              <div className="space-y-4">
                <input value={headline} onChange={e => setHeadline(e.target.value)} className="w-full p-4 border rounded-xl font-black text-2xl" />
                {sections.map((s, i) => (
                  <div key={i} className="space-y-2 p-4 bg-slate-50 rounded-xl">
                    <input value={s.heading} onChange={e => handleSectionChange(i, 'heading', e.target.value)} className="w-full p-2 border font-bold" />
                    <textarea value={s.body} onChange={e => handleSectionChange(i, 'body', e.target.value)} className="w-full h-48 p-2 border" />
                  </div>
                ))}
                <input value={hashtags} onChange={e => setHashtags(e.target.value)} className="w-full p-2 border text-sm" placeholder="Теги через запятую" />
              </div>
            ) : (
              <>
                <h1 className="text-4xl font-black text-brand-dark leading-tight mb-8">{headline}</h1>
                <div className="space-y-10 text-slate-800">
                  {sections.map((section, idx) => (
                    <div key={idx} className="space-y-4">
                      {section.heading && <h2 className="text-2xl font-black text-brand-dark uppercase border-b-2 border-orange-100 pb-2">{section.heading}</h2>}
                      <div className="space-y-4">
                        {section.body.split('\n').filter(p => p.trim()).map((para, pIdx) => (
                          <p key={pIdx} className="leading-relaxed text-justify text-lg" style={{ textIndent: '2.5rem' }}>
                            {para.trim()}
                          </p>
                        ))}
                      </div>
                    </div>
                  ))}
                </div>

                <div className="grid grid-cols-1 gap-8 my-12">
                  {pack.generatedImages.map((img, i) => img && (
                    <img key={i} src={img} className="w-full rounded-[2rem] shadow-2xl" alt="Иллюстрация" />
                  ))}
                </div>
              </>
            )}
          </article>
        )}

        {activeTab === 'telegram' && (
          <div className="max-w-md mx-auto">
             <div className="bg-[#f0f2f5] p-8 rounded-[2.5rem] text-sm whitespace-pre-wrap leading-relaxed shadow-inner border border-slate-200/50 text-slate-700">
                {tgText}
             </div>
          </div>
        )}

        {activeTab === 'vk' && (
          <div className="max-w-md mx-auto">
             <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-2xl text-sm whitespace-pre-wrap leading-relaxed text-slate-700">
                {vkText}
             </div>
          </div>
        )}

        {activeTab === 'prompts' && (
          <div className="space-y-4">
            <h3 className="font-black text-brand-dark text-xs uppercase tracking-widest border-b pb-4">Задания для генерации</h3>
            {pack.imagePrompts.map((p, i) => (
              <div key={i} className="p-4 bg-slate-50 border border-slate-200 rounded-xl text-[11px] font-mono leading-relaxed relative group">
                <span className="bg-brand-orange text-white w-5 h-5 flex items-center justify-center rounded-full text-[9px] font-black absolute -top-2 -left-2">{i+1}</span>
                {p}
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { DigestData, PublishingConfig } from '../types';
import { publishToSmmBox } from '../services/publishingService';

interface DigestPostViewerProps {
  digest: DigestData;
  pubConfig: PublishingConfig;
}

export const DigestPostViewer: React.FC<DigestPostViewerProps> = ({ digest, pubConfig }) => {
  const [activeView, setActiveView] = useState<'long' | 'short'>('long');
  const [copied, setCopied] = useState(false);
  const [publishing, setPublishing] = useState<boolean>(false);
  const [pubStatus, setPubStatus] = useState<string>('');
  const [scheduleDate, setScheduleDate] = useState<string>('');

  const getTextToUse = () => {
      const rawText = activeView === 'long' ? digest.formattedDigestText : digest.formattedShortDigest;
      return rawText.replace(/\*\*/g, '').replace(/\*/g, '').replace(/__/g, '').trim();
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(getTextToUse());
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handlePublish = async () => {
    setPublishing(true);
    setPubStatus('Отправка в SmmBox...');
    const textToSend = getTextToUse();
    const imagesToSend = (activeView === 'long' && digest.collageImage) ? [digest.collageImage] : [];
    const dateObj = scheduleDate ? new Date(scheduleDate) : undefined;

    try {
      await publishToSmmBox(pubConfig, textToSend, imagesToSend, dateObj);
      setPubStatus('Запланировано!');
      setTimeout(() => setPubStatus(''), 5000);
    } catch (e: any) {
      setPubStatus(`Ошибка: ${e.message}`);
    } finally {
      setPublishing(false);
    }
  };

  return (
    <div className="bg-white rounded-[2rem] shadow-2xl overflow-hidden border border-slate-200 h-full flex flex-col min-h-[600px] animate-fade-in">
      <div className="bg-slate-50 border-b p-4 flex justify-between items-center">
        <div className="flex gap-2">
            <button onClick={() => setActiveView('long')} className={`text-[10px] px-4 py-2 rounded-xl font-black uppercase transition-all ${activeView === 'long' ? 'bg-white shadow-lg text-brand-orange' : 'text-slate-400'}`}>Дайджест</button>
            <button onClick={() => setActiveView('short')} className={`text-[10px] px-4 py-2 rounded-xl font-black uppercase transition-all ${activeView === 'short' ? 'bg-white shadow-lg text-brand-orange' : 'text-slate-400'}`}>Строка</button>
        </div>
        <button onClick={handleCopy} className={`text-[10px] px-4 py-2 rounded-xl font-black transition-all ${copied ? 'bg-green-500 text-white' : 'bg-brand-orange/10 text-brand-orange'}`}>{copied ? 'OK' : 'КОПИРОВАТЬ'}</button>
      </div>

      <div className="p-0 overflow-y-auto custom-scrollbar flex-1 flex flex-col">
        {activeView === 'long' && (
            <div className="relative h-64 w-full bg-slate-900 shrink-0 group">
            {digest.collageImage ? (
                <img src={digest.collageImage} alt="Cover" className="w-full h-full object-cover opacity-80" />
            ) : (
                <div className="w-full h-full flex flex-col items-center justify-center bg-brand-dark">
                    <div className="w-8 h-8 border-4 border-brand-orange border-t-transparent rounded-full animate-spin mb-4"></div>
                    <div className="text-white/30 text-[9px] font-black uppercase tracking-widest">Рисуем обложку выпуска...</div>
                </div>
            )}
            <div className="absolute inset-0 bg-gradient-to-t from-brand-dark to-transparent opacity-60 pointer-events-none"></div>
            <div className="absolute bottom-6 left-8 pointer-events-none">
                <h2 className="text-white font-black text-2xl uppercase italic tracking-tighter">Главный Дайджест</h2>
            </div>
            </div>
        )}

        <div className="p-6 bg-slate-50 border-b space-y-4">
           <div className="flex flex-col gap-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Дата публикации в SmmBox</label>
              <input type="datetime-local" value={scheduleDate} onChange={(e) => setScheduleDate(e.target.value)} className="w-full text-xs p-4 rounded-2xl border border-slate-200 outline-none font-mono focus:ring-2 focus:ring-brand-orange transition-all" />
           </div>

           <button 
             onClick={handlePublish} 
             disabled={publishing} 
             className="w-full bg-brand-orange text-white text-[11px] font-black py-4 rounded-2xl uppercase tracking-widest shadow-xl shadow-orange-100 hover:scale-[1.02] active:scale-95 transition-all disabled:opacity-50"
           >
             {publishing ? 'Отправляем...' : 'Опубликовать через SmmBox'}
           </button>

           {pubStatus && (
               <p className={`text-[10px] text-center font-bold uppercase ${pubStatus.includes('Ошибка') ? 'text-red-500' : 'text-brand-orange'} animate-pulse`}>
                 {pubStatus}
               </p>
           )}
        </div>

        <div className="p-8 flex-1 bg-white">
          {activeView === 'short' ? (
              <div className="bg-brand-dark p-8 rounded-3xl border-l-8 border-brand-orange shadow-2xl">
                  <div className="text-brand-orange font-mono text-sm leading-relaxed whitespace-pre-wrap">{getTextToUse()}</div>
              </div>
          ) : (
              <div className="whitespace-pre-wrap font-sans text-sm text-slate-600 leading-relaxed font-medium">{getTextToUse()}</div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { fetchRealNews, generateArticleZhvanetsky, generateImage, generateImagesForArticle } from './services/geminiService';
import { AppState, DigestData, GeneratedContentPack, PublishingConfig, NewsItem } from './types';
import { ResultViewer } from './components/ResultViewer';
import { DigestPostViewer } from './components/DigestPostViewer';
import { SettingsModal } from './components/SettingsModal';
import { MAX_SELECTION } from './constants';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [digest, setDigest] = useState<DigestData | null>(null);
  const [selectedNewsIds, setSelectedNewsIds] = useState<string[]>([]);
  const [generatedResults, setGeneratedResults] = useState<GeneratedContentPack[]>([]);
  const [statusMessage, setStatusMessage] = useState<string>('');
  const [errorMsg, setErrorMsg] = useState<string>('');

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [pubConfig, setPubConfig] = useState<PublishingConfig>({
    smmBoxToken: '', 
    targetGroupName: 'Первый туристический'
  });

  useEffect(() => {
    const saved = localStorage.getItem('tourgenius_settings');
    if (saved) {
      try { setPubConfig(prev => ({ ...prev, ...JSON.parse(saved) })); } catch (e) {}
    }
  }, []);

