const SMMBOX_BASE_URL = "https://smmbox.com/api/v1";

const fetchWithTimeout = async (url: string, options: RequestInit = {}, timeout = 35000) => {
    const controller = new AbortController();
    const id = setTimeout(() => controller.abort(), timeout);
    try {
        const response = await fetch(url, { ...options, signal: controller.signal });
        clearTimeout(id);
        return response;
    } catch (error: any) {
        clearTimeout(id);
        throw error;
    }
};

/**
 * SmmBox API Helpers
 */
export const fetchSmmBoxGroups = async (token: string) => {
    if (!token) throw new Error("API токен SmmBox не указан");

    const response = await fetchWithTimeout(`${SMMBOX_BASE_URL}/groups`, {
        headers: {
            'Authorization': `Bearer ${token}`,
            'Accept': 'application/json'
        }
    });

    const data = await response.json();
    if (!data.success) throw new Error(data.error?.message || "Ошибка получения групп SmmBox");
    return data.response;
};

export const publishToSmmBox = async (
    config: PublishingConfig, 
    text: string, 
    imagesBase64: string[] = [], 
    publishDate?: Date
) => {
    if (!config.smmBoxToken) throw new Error("SmmBox API токен не настроен");

    const allGroups = await fetchSmmBoxGroups(config.smmBoxToken);
    const targetGroups = allGroups.filter((g: any) => 
        g.name.toLowerCase().includes(config.targetGroupName.toLowerCase())
    );

    if (targetGroups.length === 0) {
        throw new Error(`Группа "${config.targetGroupName}" не найдена в SmmBox.`);
    }

    const attachments: any[] = [{ type: 'text', text }];
    imagesBase64.forEach(img => {
        if (img && img.startsWith('data:')) {
            attachments.push({ type: 'photo', original: img });
        }
    });

    const postTime = publishDate || new Date(Date.now() + 5 * 60000);
    const unixTimestamp = Math.floor(postTime.getTime() / 1000);

    const postsData = targetGroups.map((group: any) => ({
        group: { id: group.id, social: group.social, type: group.type },
        date: unixTimestamp,
        attachments: attachments,
        options: ['from_group']
    }));

    const response = await fetchWithTimeout(`${SMMBOX_BASE_URL}/posts/postpone`, {
        method: 'POST',
        headers: {
            'Authorization': `Bearer ${config.smmBoxToken}`,
            'Content-Type': 'application/json',
            'Accept': 'application/json'
        },
        body: JSON.stringify({ posts: postsData })
    });

    const result = await response.json();
    if (!result.success) throw new Error(result.error?.message || "SmmBox API Error");
    return result.response;
};

/**
 * WordPress API Helpers
 */
const uploadMediaToWP = async (wpConfig: WordPressConfig, base64: string, filename: string) => {
    const res = await fetch(base64);
    const blob = await res.blob();
    const formData = new FormData();
    formData.append('file', blob, filename);

    const auth = btoa(`${wpConfig.username}:${wpConfig.applicationPassword}`);
    const response = await fetch(`${wpConfig.url.replace(/\/$/, '')}/wp-json/wp/v2/media`, {
        method: 'POST',
        headers: { 'Authorization': `Basic ${auth}` },
        body: formData
    });

    if (!response.ok) throw new Error(`Media upload failed: ${response.statusText}`);
    return await response.json();
};

export const publishToWordPress = async (
    config: WordPressConfig, 
    title: string, 
    sections: {heading: string, body: string}[], 
    imagesBase64: string[], 
    tags: string,
    metaDescription: string
) => {
    if (!config.url || !config.applicationPassword) throw new Error("Настройки WordPress не заполнены");

    // 1. Upload images
    const uploadedMediaUrls: string[] = [];
    for (let i = 0; i < imagesBase64.length; i++) {
        if (!imagesBase64[i]) continue;
        try {
            const media = await uploadMediaToWP(config, imagesBase64[i], `tourgenius-${Date.now()}-${i}.png`);
            uploadedMediaUrls.push(media.source_url);
        } catch (e) {
            console.error("WP Media upload error", e);
        }
    }

    // 2. Format HTML content
    let htmlContent = '';
    sections.forEach((s, idx) => {
        if (s.heading) htmlContent += `<h2 class="wp-block-heading">${s.heading}</h2>`;
        const paragraphs = s.body.split('\n').filter(p => p.trim());
        paragraphs.forEach(p => {
            htmlContent += `<p>${p.trim()}</p>`;
        });
        // Insert an image after every couple of sections if available
        if (uploadedMediaUrls[idx]) {
            htmlContent += `<figure class="wp-block-image size-large"><img src="${uploadedMediaUrls[idx]}" alt="${title}" /></figure>`;
        }
    });

    if (tags) {
        htmlContent += `<p><em>Теги: ${tags}</em></p>`;
    }

    // 3. Create Post
    const auth = btoa(`${config.username}:${config.applicationPassword}`);
    const response = await fetch(`${config.url.replace(/\/$/, '')}/wp-json/wp/v2/posts`, {
        method: 'POST',
        headers: {
            'Authorization': `Basic ${auth}`,
            'Content-Type': 'application/json'
        },
        body: JSON.stringify({
            title: title,
            content: htmlContent,
            status: 'publish',
            excerpt: metaDescription
        })
    });

    if (!response.ok) {
        const errData = await response.json();
        throw new Error(errData.message || "WordPress API Error");
    }

    return await response.json();
};

