export const ResultViewer: React.FC<ResultViewerProps> = ({ pack, pubConfig }) => {
  const [activeTab, setActiveTab] = useState<'site' | 'telegram' | 'vk' | 'prompts'>('site');
  const [isEditing, setIsEditing] = useState(false);

  const [headline, setHeadline] = useState(pack.siteArticle?.headline || '');
  const [sections, setSections] = useState<ArticleSection[]>(pack.siteArticle?.sections || []);
  const [hashtags, setHashtags] = useState(pack.siteArticle?.hashtags || '');
  const [tgText, setTgText] = useState(pack.telegramPost?.content || '');
  const [vkText, setVkText] = useState(pack.vkPost?.content || '');

  const [publishing, setPublishing] = useState<boolean>(false);
  const [pubStatus, setPubStatus] = useState<{ success?: boolean; msg?: string }>({});
  const [scheduleDate, setScheduleDate] = useState<string>('');

  useEffect(() => {
    setHeadline(pack.siteArticle?.headline || '');
    setSections(pack.siteArticle?.sections || []);
    setHashtags(pack.siteArticle?.hashtags || '');
    setTgText(pack.telegramPost?.content || '');
    setVkText(pack.vkPost?.content || '');
  }, [pack]);

  const handleSmmBoxPublish = async (text: string) => {
    setPublishing(true);
    setPubStatus({});
    const dateObj = scheduleDate ? new Date(scheduleDate) : undefined;
    try {
      await publishToSmmBox(pubConfig, text, pack.generatedImages, dateObj);
      setPubStatus({ success: true, msg: 'Успех SmmBox!' });
    } catch (e: any) {
      setPubStatus({ success: false, msg: e.message });
    } finally {
      setPublishing(false);
    }
  };

  const handleWordPressPublish = async () => {
    setPublishing(true);
    setPubStatus({});
    try {
      await publishToWordPress(pubConfig.wordPress, headline, sections, pack.generatedImages, hashtags, pack.metaDescription);
      setPubStatus({ success: true, msg: 'Статья опубликована в WordPress!' });
    } catch (e: any) {
      setPubStatus({ success: false, msg: e.message });
    } finally {
      setPublishing(false);
    }
  };

  const handleSectionChange = (index: number, field: 'heading' | 'body', value: string) => {
    const newSections = [...sections];
    newSections[index][field] = value;
    setSections(newSections);
  };

  if (pack.error) return <div className="p-10 text-center text-red-500 font-bold">{pack.error}</div>;

  return (
    <div className="bg-white rounded-[2rem] shadow-2xl overflow-hidden border border-slate-100 flex flex-col h-full animate-fade-in mb-10">
      <div className="bg-brand-dark border-b border-white/5 p-3 flex justify-between items-center">
        <div className="flex space-x-2">
          {['site', 'telegram', 'vk', 'prompts'].map((tab) => (
            <button key={tab} onClick={() => setActiveTab(tab as any)} className={`px-4 py-2 text-[10px] font-black rounded-lg uppercase tracking-widest transition-all ${activeTab === tab ? 'bg-brand-orange text-white shadow-lg' : 'text-slate-400 hover:text-white'}`}>
              {tab === 'site' ? 'Статья (WP)' : tab === 'telegram' ? 'TG (SmmBox)' : tab === 'vk' ? 'VK (SmmBox)' : 'Промпты'}
            </button>
          ))}
        </div>
        <button onClick={() => setIsEditing(!isEditing)} className={`px-4 py-2 text-[10px] font-black rounded-lg uppercase border transition-all ${isEditing ? 'bg-white text-brand-dark' : 'text-white border-white/20'}`}>
          {isEditing ? 'Сохранить' : 'Редактировать'}
        </button>
      </div>

      <div className="p-8 overflow-y-auto flex-1 custom-scrollbar">
        {/* Status Bar */}
        {pubStatus.msg && (
            <div className={`mb-6 p-4 rounded-2xl text-[10px] font-black uppercase text-center border ${pubStatus.success ? 'bg-green-50 border-green-100 text-green-600' : 'bg-red-50 border-red-100 text-red-600'}`}>
                {pubStatus.msg}
            </div>
        )}

        {/* Publish Tools for SmmBox (Socials) */}
        {(activeTab === 'telegram' || activeTab === 'vk') && (
          <div className="mb-6 bg-slate-50 p-6 rounded-3xl border border-slate-100 flex flex-wrap items-center justify-between gap-4">
             <div className="flex flex-col">
                <span className="text-[10px] font-black uppercase text-brand-orange tracking-widest">SmmBox</span>
             </div>
             <div className="flex items-center gap-3">
                <input type="datetime-local" value={scheduleDate} onChange={(e) => setScheduleDate(e.target.value)} className="text-xs border border-slate-200 rounded-xl px-4 py-2.5 bg-white outline-none focus:ring-2 focus:ring-brand-orange font-mono" />
                <button onClick={() => handleSmmBoxPublish(activeTab === 'telegram' ? tgText : vkText)} disabled={publishing} className="bg-brand-orange text-white text-[10px] px-8 py-3 rounded-xl font-black uppercase hover:bg-orange-600 disabled:opacity-50 transition-all">
                  {publishing ? 'Ждите...' : 'Опубликовать SmmBox'}
                </button>
             </div>
          </div>
        )}

        {/* Publish Tools for WordPress (Site Article) */}
        {activeTab === 'site' && (
          <div className="mb-10 bg-blue-50 p-6 rounded-3xl border border-blue-100 flex items-center justify-between gap-4">
             <div className="flex flex-col">
                <span className="text-[10px] font-black uppercase text-blue-600 tracking-widest">WordPress (Лонгрид)</span>
                <span className="text-[9px] font-bold text-blue-400 mt-1 uppercase italic">С 3-мя фото и аналитикой Жванецкого</span>
             </div>
             <button onClick={handleWordPressPublish} disabled={publishing} className="bg-blue-600 text-white text-[10px] px-10 py-4 rounded-xl font-black uppercase hover:bg-blue-700 shadow-xl shadow-blue-100 disabled:opacity-50 transition-all">
                {publishing ? 'Публикация...' : 'Отправить на сайт (WordPress)'}
             </button>
          </div>
        )}

        {activeTab === 'site' && (
          <article className="article-font max-w-none">
            {isEditing ? (
              <div className="space-y-4">
                <input value={headline} onChange={e => setHeadline(e.target.value)} className="w-full p-4 border rounded-xl font-black text-2xl" />
                {sections.map((s, i) => (
                  <div key={i} className="space-y-2 p-4 bg-slate-50 rounded-xl">
                    <input value={s.heading} onChange={e => handleSectionChange(i, 'heading', e.target.value)} className="w-full p-2 border font-bold" />
                    <textarea value={s.body} onChange={e => handleSectionChange(i, 'body', e.target.value)} className="w-full h-48 p-2 border" />
                  </div>
                ))}
                <input value={hashtags} onChange={e => setHashtags(e.target.value)} className="w-full p-2 border text-sm" placeholder="Теги" />
              </div>
            ) : (
              <>
                <h1 className="text-4xl font-black text-brand-dark leading-tight mb-8">{headline}</h1>
                <div className="space-y-10 text-slate-800">
                  {sections.map((section, idx) => (
                    <div key={idx} className="space-y-4">
                      {section.heading && <h2 className="text-2xl font-black text-brand-dark uppercase border-b-2 border-orange-100 pb-2">{section.heading}</h2>}
                      <div className="space-y-4">
                        {section.body.split('\n').filter(p => p.trim()).map((para, pIdx) => (
                          <p key={pIdx} className="leading-relaxed text-justify text-lg" style={{ textIndent: '2.5rem' }}>{para.trim()}</p>
                        ))}
                      </div>
                    </div>
                  ))}
                </div>
                <div className="grid grid-cols-1 gap-8 my-12">
                  {pack.generatedImages.map((img, i) => img && (
                    <img key={i} src={img} className="w-full rounded-[2rem] shadow-2xl border-4 border-white" alt="Иллюстрация" />
                  ))}
                </div>
              </>
            )}
          </article>
        )}

        {activeTab === 'telegram' && (
          <div className="max-w-md mx-auto">
             <div className="bg-[#f0f2f5] p-8 rounded-[2.5rem] text-sm whitespace-pre-wrap leading-relaxed shadow-inner border border-slate-200/50 text-slate-700">{tgText}</div>
          </div>
        )}

        {activeTab === 'vk' && (
          <div className="max-w-md mx-auto">
             <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-2xl text-sm whitespace-pre-wrap leading-relaxed text-slate-700">{vkText}</div>
          </div>
        )}

        {activeTab === 'prompts' && (
          <div className="space-y-4">
            <h3 className="font-black text-brand-dark text-[10px] uppercase tracking-widest border-b pb-4">Задания для фото-нейросети</h3>
            {pack.imagePrompts.map((p, i) => (
              <div key={i} className="p-4 bg-slate-50 border border-slate-200 rounded-xl text-[10px] font-mono leading-relaxed relative">
                <span className="bg-brand-orange text-white w-5 h-5 flex items-center justify-center rounded-full text-[9px] font-black absolute -top-2 -left-2">{i+1}</span>
                {p}
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { fetchRealNews, generateArticleZhvanetsky, generateImage, generateImagesForArticle } from './services/geminiService';
import { AppState, DigestData, GeneratedContentPack, PublishingConfig, NewsItem } from './types';
import { ResultViewer } from './components/ResultViewer';
import { DigestPostViewer } from './components/DigestPostViewer';
import { SettingsModal } from './components/SettingsModal';
import { MAX_SELECTION } from './constants';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [digest, setDigest] = useState<DigestData | null>(null);
  const [selectedNewsIds, setSelectedNewsIds] = useState<string[]>([]);
  const [generatedResults, setGeneratedResults] = useState<GeneratedContentPack[]>([]);
  const [statusMessage, setStatusMessage] = useState<string>('');
  const [errorMsg, setErrorMsg] = useState<string>('');

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [pubConfig, setPubConfig] = useState<PublishingConfig>({
    smmBoxToken: '', 
    targetGroupName: 'Первый туристический',
    wordPress: {
        url: '',
        username: '',
        applicationPassword: ''
    }
  });

  useEffect(() => {
    const saved = localStorage.getItem('tourgenius_settings');
    if (saved) {
      try { 
        const parsed = JSON.parse(saved);
        setPubConfig(prev => ({ 
            ...prev, 
            ...parsed,
            wordPress: { ...prev.wordPress, ...parsed.wordPress }
        })); 
      } catch (e) {}
    }
  }, []);

  const handleFetchNews = async () => {
    setAppState(AppState.SEARCHING);
    setStatusMessage("Сканируем мировые ленты...");
    setErrorMsg('');

    try {
      const data = await fetchRealNews();
      setDigest(data);
      setAppState(AppState.SELECTING);

      if (data.collagePrompt) {
          generateImage(data.collagePrompt).then(img => {
              if (img) setDigest(prev => prev ? ({ ...prev, collageImage: img }) : null);
          });
      }
    } catch (e: any) {
      setErrorMsg(e.message || "Ошибка соединения.");
      setAppState(AppState.ERROR);
    }
  };

  const toggleSelection = (id: string) => {
    setSelectedNewsIds(prev => {
      if (prev.includes(id)) return prev.filter(i => i !== id);
      if (prev.length >= MAX_SELECTION) return prev;
      return [...prev, id];
    });
  };

  const handleGenerateLongreads = async () => {
    if (selectedNewsIds.length === 0) return;
    setAppState(AppState.GENERATING_CONTENT);
    setGeneratedResults([]);

    const selectedItems = digest?.news.filter(n => selectedNewsIds.includes(n.id)) || [];

    for (let i = 0; i < selectedItems.length; i++) {
      const item = selectedItems[i];
      setStatusMessage(`[${i+1}/${selectedItems.length}] Пишем лонгрид...`);

      try {
        const articlePack = await generateArticleZhvanetsky(item);
        setStatusMessage(`[${i+1}/${selectedItems.length}] Фото-шедевры...`);
        const images = await generateImagesForArticle(articlePack.imagePrompts);
        setGeneratedResults(prev => [...prev, { ...articlePack, generatedImages: images }]);
      } catch (err: any) {
        console.error(err);
      }
    }
    setAppState(AppState.COMPLETED);
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20">
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} config={pubConfig} onSave={setPubConfig} />

      {digest && (
        <div className="bg-brand-dark overflow-hidden h-10 flex items-center border-b border-brand-orange/30">
          <div className="whitespace-nowrap animate-[marquee_60s_linear_infinite] flex items-center">
             <span className="text-brand-orange font-black text-[10px] uppercase tracking-widest px-10">БЕГУЩАЯ СТРОКА:</span>
             <span className="text-white font-medium text-xs">{digest.formattedShortDigest}</span>
             <span className="text-white font-medium text-xs ml-10">{digest.formattedShortDigest}</span>
          </div>
        </div>
      )}

      <nav className="bg-white h-20 flex items-center px-8 border-b border-slate-100 sticky top-0 z-50 backdrop-blur-md bg-white/80">
        <div className="flex flex-col">
          <h1 className="text-brand-dark font-black tracking-tighter text-3xl italic leading-none">
            TOUR<span className="text-brand-orange">GENIUS</span>
          </h1>
          <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest italic">WP + SmmBox Edition</span>
        </div>

        <div className="ml-auto flex items-center gap-4">
           {!pubConfig.smmBoxToken && (
             <span className="text-[10px] font-black text-red-500 uppercase bg-red-50 px-3 py-1.5 rounded-xl border border-red-100 hidden md:block">SmmBox: Offline</span>
           )}
           {!pubConfig.wordPress.url && (
             <span className="text-[10px] font-black text-blue-500 uppercase bg-blue-50 px-3 py-1.5 rounded-xl border border-blue-100 hidden md:block">WP: Offline</span>
           )}
           <button 
             onClick={() => setIsSettingsOpen(true)} 
             className="w-12 h-12 bg-slate-50 hover:bg-slate-100 flex items-center justify-center rounded-2xl transition-all shadow-sm border border-slate-100 text-xl"
           >
             ⚙️
           </button>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto p-6 mt-4">
        {appState === AppState.IDLE && (
          <div className="bg-white rounded-[4rem] p-24 shadow-2xl border border-slate-100 text-center animate-fade-in mt-10 relative overflow-hidden">
            <div className="text-8xl mb-12 drop-shadow-2xl">🎩</div>
            <h2 className="text-6xl font-black text-brand-dark mb-8 uppercase tracking-tighter italic leading-none">
               Голос <span className="text-brand-orange">Жванецкого</span>
            </h2>
            <p className="text-slate-400 text-xl max-w-2xl mx-auto mb-16 font-medium leading-relaxed">
              Лонгриды на ваш сайт (WordPress) и оперативные дайджесты в соцсети (SmmBox). 
              Всё в один клик.
            </p>
            <button 
              onClick={handleFetchNews} 
              className="bg-brand-dark text-white px-20 py-8 rounded-[2.5rem] font-black uppercase tracking-[0.3em] hover:bg-brand-orange hover:scale-105 transition-all shadow-2xl shadow-orange-100 active:scale-95"
            >
              Начать эфир
            </button>
          </div>
        )}

        {appState === AppState.SEARCHING && (
          <div className="flex flex-col items-center py-40 animate-fade-in">
             <div className="w-24 h-24 border-[8px] border-brand-orange border-t-transparent rounded-full animate-spin mb-12 shadow-2xl shadow-orange-100"></div>
             <h3 className="text-3xl font-black text-brand-dark uppercase italic tracking-tighter text-center animate-pulse">{statusMessage}</h3>
          </div>
        )}

        {appState === AppState.SELECTING && digest && (
          <div className="animate-fade-in space-y-10">
            <div className="flex justify-between items-center bg-white p-10 rounded-[2.5rem] border border-slate-100 shadow-2xl sticky top-24 z-40 backdrop-blur-md bg-white/95">
               <div>
                  <h2 className="text-3xl font-black text-brand-dark uppercase italic tracking-tighter">Свежая почта</h2>
                  <p className="text-xs font-black text-brand-orange uppercase tracking-[0.2em]">Выберите 2 темы для больших статей на сайт</p>
               </div>
               <button 
                 onClick={handleGenerateLongreads}
                 disabled={selectedNewsIds.length === 0}
                 className={`px-16 py-6 rounded-3xl font-black text-xs uppercase tracking-[0.2em] transition-all shadow-2xl ${selectedNewsIds.length > 0 ? 'bg-brand-orange text-white shadow-orange-200 scale-105' : 'bg-slate-100 text-slate-300 cursor-not-allowed'}`}
               >
                 Создать выпуск ({selectedNewsIds.length}/{MAX_SELECTION})
               </button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
                <div className="lg:col-span-4">
                  <DigestPostViewer digest={digest} pubConfig={pubConfig} />
                </div>
                <div className="lg:col-span-8 grid grid-cols-1 md:grid-cols-2 gap-8 pb-20">
                   {digest.news.map(n => (
                      <div 
                        key={n.id} 
                        onClick={() => toggleSelection(n.id)}
                        className={`p-8 rounded-[2rem] border-2 transition-all cursor-pointer bg-white flex flex-col h-full group relative overflow-hidden ${selectedNewsIds.includes(n.id) ? 'border-brand-orange shadow-2xl ring-8 ring-brand-orange/5 scale-[1.02]' : 'border-slate-100 hover:border-brand-orange/30'}`}
                      >
                         <div className="flex justify-between items-center mb-6">
                            <span className="text-[10px] font-black uppercase bg-slate-50 px-3 py-1.5 rounded-lg text-slate-400 tracking-widest">{n.location || 'АКТУАЛЬНО'}</span>
                            <div className={`w-6 h-6 rounded-full border-2 transition-all ${selectedNewsIds.includes(n.id) ? 'bg-brand-orange border-brand-orange scale-110 shadow-lg' : 'border-slate-200'}`}></div>
                         </div>
                         <h4 className="font-black text-xl mb-4 leading-tight text-brand-dark group-hover:text-brand-orange transition-colors">{n.title}</h4>
                         <p className="text-slate-500 text-sm leading-relaxed mb-6 flex-grow font-medium">{n.summary}</p>
                         <div className="text-[10px] font-mono text-slate-300 italic border-t pt-6 uppercase tracking-widest">{n.ticker}</div>
                      </div>
                   ))}
                </div>
            </div>
          </div>
        )}

        {(appState === AppState.GENERATING_CONTENT || appState === AppState.COMPLETED) && (
          <div className="space-y-12 animate-fade-in">
             <div className="bg-brand-dark p-10 rounded-[3rem] flex justify-between items-center shadow-2xl border-b-[12px] border-brand-orange">
                <h2 className="text-4xl font-black text-white uppercase italic tracking-tighter">
                   {appState === AppState.GENERATING_CONTENT ? statusMessage : 'Материалы готовы'}
                </h2>
                <button onClick={() => window.location.reload()} className="bg-white/10 hover:bg-white/20 text-white px-8 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all">Новый поиск</button>
             </div>

             <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
                <div className="lg:col-span-4 h-full sticky top-36">
                  {digest && <DigestPostViewer digest={digest} pubConfig={pubConfig} />}
                </div>
                <div className="lg:col-span-8 space-y-12">
                   {generatedResults.map(res => (
                     <ResultViewer key={res.newsId} pack={res} pubConfig={pubConfig} />
                   ))}
                   {appState === AppState.GENERATING_CONTENT && (
                     <div className="p-32 flex flex-col items-center justify-center bg-white rounded-[4rem] border-4 border-dashed border-slate-100 animate-pulse">
                        <div className="w-16 h-16 border-4 border-brand-orange border-t-transparent rounded-full animate-spin mb-8"></div>
                        <p className="text-slate-400 font-black uppercase text-xs tracking-[0.2em]">Финальная корректура...</p>
                     </div>
                   )}
                </div>
             </div>
          </div>
        )}
      </main>

      <style>{`
        @keyframes marquee {
          0% { transform: translateX(0); }
          100% { transform: translateX(-50%); }
        }
      `}</style>
    </div>
  );
};

export default App;

import { PublishingConfig, WordPressConfig } from "../types";

const SMMBOX_BASE_URL = "https://smmbox.com/api/v1";

const fetchWithTimeout = async (url: string, options: RequestInit = {}, timeout = 45000) => {
    const controller = new AbortController();
    const id = setTimeout(() => controller.abort(), timeout);
    try {
        const response = await fetch(url, { ...options, signal: controller.signal });
        clearTimeout(id);
        return response;
    } catch (error: any) {
        clearTimeout(id);
        if (error.name === 'AbortError') throw new Error("Превышено время ожидания ответа от сервера.");
        if (error.message === 'Failed to fetch') {
            throw new Error("Ошибка сети (CORS). Сервер SmmBox или WordPress блокирует запрос из браузера. Проверьте протокол (https://) и настройки доступа.");
        }
        throw error;
    }
};

/**
 * SmmBox API Helpers
 * Используем api_token в query-параметрах, так как это часто помогает обойти некоторые ограничения CORS
 */
export const fetchSmmBoxGroups = async (token: string) => {
    if (!token) throw new Error("API токен SmmBox не указан");

    const response = await fetchWithTimeout(`${SMMBOX_BASE_URL}/groups?api_token=${token}`, {
        method: 'GET',
        headers: {
            'Accept': 'application/json'
        }
    });

    const data = await response.json();
    if (!data.success) throw new Error(data.error?.message || "Ошибка получения групп SmmBox");
    return data.response;
};

export const publishToSmmBox = async (
    config: PublishingConfig, 
    text: string, 
    imagesBase64: string[] = [], 
    publishDate?: Date
) => {
    if (!config.smmBoxToken) throw new Error("SmmBox API токен не настроен");

    // Получаем список групп для поиска ID
    const allGroups = await fetchSmmBoxGroups(config.smmBoxToken);
    const targetGroups = allGroups.filter((g: any) => 
        g.name.toLowerCase().includes(config.targetGroupName.toLowerCase())
    );

    if (targetGroups.length === 0) {
        throw new Error(`Группа "${config.targetGroupName}" не найдена в вашем SmmBox. Подключите её или проверьте название в настройках.`);
    }

    const attachments: any[] = [{ type: 'text', text }];

    // Добавляем только существующие изображения
    imagesBase64.filter(img => img && img.startsWith('data:')).forEach(img => {
        attachments.push({
            type: 'photo',
            original: img
        });
    });

    // Время публикации (SmmBox требует будущее время)
    const postTime = publishDate || new Date(Date.now() + 5 * 60000);
    const unixTimestamp = Math.floor(postTime.getTime() / 1000);

    const postsData = targetGroups.map((group: any) => ({
        group: {
            id: group.id,
            social: group.social,
            type: group.type
        },
        date: unixTimestamp,
        attachments: attachments,
        options: ['from_group']
    }));

    const response = await fetchWithTimeout(`${SMMBOX_BASE_URL}/posts/postpone?api_token=${config.smmBoxToken}`, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Accept': 'application/json'
        },
        body: JSON.stringify({ posts: postsData })
    });

    const result = await response.json();
    if (!result.success) throw new Error(result.error?.message || "SmmBox API Error");

    return result.response;
};

/**
 * WordPress API Helpers
 */
const uploadMediaToWP = async (wpConfig: WordPressConfig, base64: string, filename: string) => {
    try {
        const res = await fetch(base64);
        const blob = await res.blob();
        const formData = new FormData();
        formData.append('file', blob, filename);

        const auth = btoa(`${wpConfig.username}:${wpConfig.applicationPassword}`);
        const response = await fetch(`${wpConfig.url.replace(/\/$/, '')}/wp-json/wp/v2/media`, {
            method: 'POST',
            headers: { 
                'Authorization': `Basic ${auth}`
                // Content-Type не ставим, браузер сам выставит multipart/form-data с boundary
            },
            body: formData
        });

        if (!response.ok) {
            const err = await response.json();
            throw new Error(err.message || `Media upload failed: ${response.statusText}`);
        }
        return await response.json();
    } catch (e: any) {
        console.error("WP Media Upload Error:", e);
        throw new Error(`Не удалось загрузить фото в WP: ${e.message}`);
    }
};

export const publishToWordPress = async (
    config: WordPressConfig, 
    title: string, 
    sections: {heading: string, body: string}[], 
    imagesBase64: string[], 
    tags: string,
    metaDescription: string
) => {
    if (!config.url || !config.applicationPassword) throw new Error("Настройки WordPress не заполнены. Укажите URL, логин и Пароль Приложения.");

    // 1. Загружаем изображения (до 3 штук)
    const uploadedMediaUrls: string[] = [];
    const validImages = imagesBase64.filter(img => img && img.length > 100);

    for (let i = 0; i < validImages.length; i++) {
        try {
            const media = await uploadMediaToWP(config, validImages[i], `tourgenius-${Date.now()}-${i}.png`);
            uploadedMediaUrls.push(media.source_url);
        } catch (e) {
            console.warn(`Пропуск изображения ${i} из-за ошибки загрузки:`, e);
        }
    }

    // 2. Формируем HTML контент статьи в стиле Жванецкого
    let htmlContent = '';
    sections.forEach((s, idx) => {
        if (s.heading) {
            htmlContent += `<h2 class="wp-block-heading">${s.heading}</h2>`;
        }

        const paragraphs = s.body.split('\n').filter(p => p.trim());
        paragraphs.forEach(p => {
            htmlContent += `<p>${p.trim()}</p>`;
        });

        // Вставляем изображение после 1-й, 2-й и 3-й секции (если они загружены)
        if (uploadedMediaUrls[idx]) {
            htmlContent += `
                <figure class="wp-block-image size-large">
                    <img src="${uploadedMediaUrls[idx]}" alt="${title}" class="wp-image-generated" />
                </figure>
            `;
        }
    });

    if (tags) {
        const tagList = tags.split(',').map(t => `#${t.trim()}`).join(' ');
        htmlContent += `<hr /><p><em>Теги: ${tagList}</em></p>`;
    }

    // 3. Создаем запись в WordPress
    const auth = btoa(`${config.username}:${config.applicationPassword}`);
    const response = await fetch(`${config.url.replace(/\/$/, '')}/wp-json/wp/v2/posts`, {
        method: 'POST',
        headers: {
            'Authorization': `Basic ${auth}`,
            'Content-Type': 'application/json'
        },
        body: JSON.stringify({
            title: title,
            content: htmlContent,
            status: 'publish',
            excerpt: metaDescription,
            format: 'standard'
        })
    });

    if (!response.ok) {
        const errData = await response.json();
        throw new Error(errData.message || `WordPress Error: ${response.statusText}`);
    }

    return await response.json();
};

