                    <div className="text-white/30 text-[9px] font-black uppercase tracking-widest">Создание обложки...</div>
                </div>
            )}
            <div className="absolute inset-0 bg-gradient-to-t from-brand-dark via-transparent to-transparent opacity-70"></div>
            <div className="absolute bottom-6 left-8">
                <h2 className="text-white font-black text-2xl uppercase italic tracking-tighter leading-none">TourGenius<br/><span className="text-brand-orange">Digest</span></h2>
            </div>
            </div>
        )}

        <div className="p-6 bg-slate-50 border-b space-y-4">
           <div className="flex flex-col gap-2">
              <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Запланировать в SmmBox</label>
