import { PublishingConfig, WordPressConfig } from "../types";

const SMMBOX_BASE_URL = "https://smmbox.com/api/v1";

/**
 * Оборачивает URL в CORS прокси. 
 * Используем corsproxy.io, так как он более стабилен для POST-запросов с большими телами (base64).
 */
const wrapUrl = (url: string, useProxy: boolean) => {
    if (!useProxy) return url;
    // corsproxy.io обычно лучше справляется с передачей больших POST данных
    return `https://corsproxy.io/?${encodeURIComponent(url)}`;
};

const fetchWithTimeout = async (url: string, options: RequestInit = {}, useProxy: boolean = false, timeout = 60000) => {
    const finalUrl = wrapUrl(url, useProxy);
    const controller = new AbortController();
    const id = setTimeout(() => controller.abort(), timeout);

    try {
        const response = await fetch(finalUrl, { ...options, signal: controller.signal });
        clearTimeout(id);

        const contentType = response.headers.get("content-type");

        // Если сервер вернул HTML (ошибка 404/500/408 от прокси или сервера)
        if (contentType && contentType.includes("text/html")) {
            const htmlText = await response.text();
            console.error("Received HTML instead of JSON:", htmlText.slice(0, 500));

            if (response.status === 408) {
                throw new Error(`Ошибка 408: Время ожидания истекло. SmmBox не успел обработать тяжелые изображения. Попробуйте уменьшить количество фото или повторите без них.`);
            }

            throw new Error(`Сервер вернул ошибку ${response.status} (HTML). Возможно, прокси-сервер перегружен. Попробуйте подождать пару минут или временно отключить прокси.`);
        }

        if (!response.ok) {
            let errorMsg = `Ошибка сервера: ${response.status}`;
            try {
                const errData = await response.json();
                errorMsg = errData.error?.message || errData.message || errorMsg;
            } catch (e) {
                // Ошибка не в формате JSON
            }
            throw new Error(errorMsg);
        }

        return response;
    } catch (error: any) {
        clearTimeout(id);
        if (error.name === 'AbortError') throw new Error("Время ожидания (60 сек) истекло. Попробуйте опубликовать текст без картинок или проверьте интернет-соединение.");
        if (error.message === 'Failed to fetch') {
            throw new Error("Ошибка сети: Соединение прервано. Это часто случается при отправке больших фото через прокси. Попробуйте включить/выключить прокси в настройках.");
        }
        throw error;
    }
};

export const fetchSmmBoxGroups = async (config: PublishingConfig) => {
    const token = config.smmBoxToken;
    if (!token) throw new Error("API токен SmmBox не указан");

    const url = `${SMMBOX_BASE_URL}/groups?api_token=${token}`;
    const response = await fetchWithTimeout(url, {
        method: 'GET',
        headers: { 'Accept': 'application/json' }
    }, config.useProxy, 30000); // 30 сек для простого GET

    return await response.json();
};

export const publishToSmmBox = async (
    config: PublishingConfig, 
    text: string, 
    imagesBase64: string[] = [], 
    publishDate?: Date
) => {
    if (!config.smmBoxToken) throw new Error("SmmBox API токен не настроен");

    // 1. Получаем группы
    const groupsData = await fetchSmmBoxGroups(config);
    if (!groupsData.success) throw new Error(groupsData.error?.message || "Ошибка получения групп");

    const allGroups = groupsData.response || [];
    const targetGroups = allGroups.filter((g: any) => 
        g.name.toLowerCase().includes(config.targetGroupName.toLowerCase())
    );

    if (targetGroups.length === 0) {
        throw new Error(`Группа "${config.targetGroupName}" не найдена. Проверьте название в настройках SmmBox.`);
    }

    const attachments: any[] = [{ type: 'text', text }];

    // Берем максимум 3 изображения, чтобы снизить риск таймаута
    imagesBase64.filter(img => img && img.startsWith('data:')).slice(0, 3).forEach(img => {
        attachments.push({ type: 'photo', original: img });
    });

    const postTime = publishDate || new Date(Date.now() + 5 * 60000);
    const unixTimestamp = Math.floor(postTime.getTime() / 1000);

    const postsData = targetGroups.map((group: any) => ({
        group: { id: group.id, social: group.social, type: group.type },
        date: unixTimestamp,
        attachments: attachments,
        options: ['from_group']
    }));

    const url = `${SMMBOX_BASE_URL}/posts/postpone?api_token=${config.smmBoxToken}`;
    const response = await fetchWithTimeout(url, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Accept': 'application/json'
        },
        body: JSON.stringify({ posts: postsData })
    }, config.useProxy, 80000); // Увеличиваем до 80 сек для тяжелых POST

    const result = await response.json();
    if (!result.success) throw new Error(result.error?.message || "SmmBox API Error");
    return result.response;
};

/**
 * WordPress API
 */
const uploadMediaToWP = async (wpConfig: WordPressConfig, useProxy: boolean, base64: string, filename: string) => {
    const res = await fetch(base64);
    const blob = await res.blob();
    const formData = new FormData();
    formData.append('file', blob, filename);

    const auth = btoa(`${wpConfig.username}:${wpConfig.applicationPassword}`);
    const url = `${wpConfig.url.replace(/\/$/, '')}/wp-json/wp/v2/media`;

    const response = await fetchWithTimeout(url, {
        method: 'POST',
        headers: { 'Authorization': `Basic ${auth}` },
        body: formData
    }, useProxy, 60000);

    return await response.json();
};

export const publishToWordPress = async (
    config: WordPressConfig, 
    useProxy: boolean,
    title: string, 
    sections: {heading: string, body: string}[], 
    imagesBase64: string[], 
    tags: string,
    metaDescription: string
) => {
    if (!config.url || !config.applicationPassword) throw new Error("Настройки WordPress не заполнены");

    const uploadedMediaUrls: string[] = [];
    const validImages = imagesBase64.filter(img => img && img.length > 100);

    for (let i = 0; i < validImages.length; i++) {
        try {
            const media = await uploadMediaToWP(config, useProxy, validImages[i], `tg-${Date.now()}-${i}.png`);
            uploadedMediaUrls.push(media.source_url);
        } catch (e) {
            console.warn("WP Media Upload failed", e);
        }
    }

    let htmlContent = '';
    sections.forEach((s, idx) => {
        if (s.heading) htmlContent += `<h2 class="wp-block-heading">${s.heading}</h2>`;
        s.body.split('\n').filter(p => p.trim()).forEach(p => {
            htmlContent += `<p>${p.trim()}</p>`;
        });
        if (uploadedMediaUrls[idx]) {
            htmlContent += `<figure class="wp-block-image size-large"><img src="${uploadedMediaUrls[idx]}" alt="${title}" /></figure>`;
        }
    });

    if (tags) {
        htmlContent += `<hr /><p><em>Теги: ${tags}</em></p>`;
    }

    const auth = btoa(`${config.username}:${config.applicationPassword}`);
    const url = `${config.url.replace(/\/$/, '')}/wp-json/wp/v2/posts`;

    const response = await fetchWithTimeout(url, {
        method: 'POST',
        headers: {
            'Authorization': `Basic ${auth}`,
            'Content-Type': 'application/json'
        },
        body: JSON.stringify({
            title: title,
            content: htmlContent,
            status: 'publish',
            excerpt: metaDescription
        })
    }, useProxy);

    return await response.json();
};

