                    }} className="w-full font-bold border-b p-1 text-lg" />
                    <textarea value={s.body} onChange={e => {
                      const n = [...sections]; n[i].body = e.target.value; setSections(n);
                    }} className="w-full h-40 p-2 border rounded-lg" />
                  </div>
                ))}
              </div>
            ) : (
              <>
                <h1 className="text-4xl font-black text-brand-dark mb-8">{headline}</h1>
                {sections.map((s, i) => (
                  <div key={i} className="mb-8">
                    <h2 className="text-xl font-bold mb-4"><strong>{s.heading}</strong></h2>
                    <p className="text-lg leading-relaxed text-slate-700">{s.body}</p>
                    {pack.generatedImages[i] && <img src={pack.generatedImages[i]} className="w-full my-6 rounded-3xl shadow-xl" />}
                  </div>
                ))}
                <div className="mt-8 pt-8 border-t text-sm text-slate-400 font-bold uppercase">
