import React, { useState, useEffect } from 'react';
import { fetchRealNews, generateArticleLongread, generateImage, generateImagesForArticle } from './services/geminiService';
import { AppState, DigestData, GeneratedContentPack, PublishingConfig, NewsItem } from './types';
import { ResultViewer } from './components/ResultViewer';
import { DigestPostViewer } from './components/DigestPostViewer';
import { SettingsModal } from './components/SettingsModal';
import { AddNewsModal } from './components/AddNewsModal';
import { MAX_SELECTION } from './constants';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [digest, setDigest] = useState<DigestData | null>(null);
  const [selectedNewsIds, setSelectedNewsIds] = useState<string[]>([]);
  const [generatedResults, setGeneratedResults] = useState<GeneratedContentPack[]>([]);
  const [statusMessage, setStatusMessage] = useState<string>('');

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isAddNewsOpen, setIsAddNewsOpen] = useState(false);
  const [pubConfig, setPubConfig] = useState<PublishingConfig>({
    smmBoxToken: '', 
    targetGroupName: 'Первый туристический',
    useProxy: false,
    wordPress: { url: '', username: '', applicationPassword: '' }
  });

  useEffect(() => {
    const saved = localStorage.getItem('tourgenius_settings');
    if (saved) { try { setPubConfig(JSON.parse(saved)); } catch(e) {} }
  }, []);

  const handleFetchNews = async () => {
    setAppState(AppState.SEARCHING);
    setStatusMessage("Сканируем региональные ленты...");
    try {
      const data = await fetchRealNews();
      setDigest(data);
      setAppState(AppState.SELECTING);
      if (data.collagePrompt) {
        generateImage(data.collagePrompt).then(img => {
          if (img) setDigest(prev => prev ? ({ ...prev, collageImage: img }) : null);
        });
      }
    } catch (e: any) { setAppState(AppState.IDLE); alert(e.message); }
  };

  const handleAddManualNews = (news: { title: string; summary: string; location: string }) => {
    if (!digest) return;
    const newItem: NewsItem = {
        id: `manual-${Date.now()}`,
        title: news.title,
        summary: news.summary,
        location: news.location,
        ticker: `${news.title}: ${news.summary.slice(0, 30)}...`
    };
    setDigest({ ...digest, news: [newItem, ...digest.news] });
  };

  const handleGenerate = async () => {
    setAppState(AppState.GENERATING_CONTENT);
    setGeneratedResults([]);
    const items = digest?.news.filter(n => selectedNewsIds.includes(n.id)) || [];

    for (let i = 0; i < items.length; i++) {
      setStatusMessage(`[${i+1}/${items.length}] Пишем лонгрид...`);
      try {
        const pack = await generateArticleLongread(items[i]);
        setStatusMessage(`[${i+1}/${items.length}] Рисуем иллюстрации...`);
        const imgs = await generateImagesForArticle(pack.imagePrompts);
        setGeneratedResults(prev => [...prev, { ...pack, generatedImages: imgs }]);
      } catch (e) { console.error(e); }
    }
    setAppState(AppState.COMPLETED);
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20">
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} config={pubConfig} onSave={setPubConfig} />
      <AddNewsModal isOpen={isAddNewsOpen} onClose={() => setIsAddNewsOpen(false)} onAdd={handleAddManualNews} />

      <nav className="bg-white h-20 flex items-center px-8 border-b sticky top-0 z-50 shadow-sm">
        <div className="flex flex-col">
          <h1 className="text-brand-dark font-black tracking-tighter text-3xl italic leading-none">TOUR<span className="text-brand-orange">GENIUS</span></h1>
          <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest italic">Editor AI Edition</span>
        </div>
        <div className="ml-auto flex items-center gap-4">
           {appState === AppState.SELECTING && (
               <button onClick={() => setIsAddNewsOpen(true)} className="bg-slate-100 hover:bg-slate-200 px-4 py-2 rounded-xl text-[10px] font-black uppercase">➕ Своя тема</button>
           )}
           <button onClick={() => setIsSettingsOpen(true)} className="w-10 h-10 bg-slate-50 flex items-center justify-center rounded-xl border text-lg">⚙️</button>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto p-6">
        {appState === AppState.IDLE && (
          <div className="bg-white rounded-[3rem] p-20 shadow-2xl border text-center mt-10">
            <h2 className="text-5xl font-black text-brand-dark mb-6 uppercase italic">Голос <span className="text-brand-orange">Жванецкого</span></h2>
            <p className="text-slate-400 text-lg mb-10">Реальные новости туризма за 48 часов. Сарказм, ирония и лонгриды.</p>
            <button onClick={handleFetchNews} className="bg-brand-dark text-white px-16 py-6 rounded-2xl font-black uppercase tracking-widest hover:bg-brand-orange transition-all">Начать поиск</button>
          </div>
        )}

        {appState === AppState.SEARCHING && (
          <div className="flex flex-col items-center py-40">
             <div className="w-16 h-16 border-4 border-brand-orange border-t-transparent rounded-full animate-spin mb-8"></div>
             <h3 className="text-2xl font-black text-brand-dark uppercase italic animate-pulse">{statusMessage}</h3>
          </div>
        )}

        {appState === AppState.SELECTING && digest && (
          <div className="space-y-10 animate-fade-in">
            <div className="flex justify-between items-center bg-white p-8 rounded-3xl border shadow-xl sticky top-24 z-40">
               <div>
                  <h2 className="text-2xl font-black text-brand-dark uppercase italic">Выпуск за 48 часов</h2>
                  <p className="text-[10px] font-black text-brand-orange uppercase">Выберите до {MAX_SELECTION} тем для лонгридов</p>
               </div>
               <button onClick={handleGenerate} disabled={selectedNewsIds.length === 0} className={`px-12 py-4 rounded-xl font-black uppercase text-xs shadow-lg transition-all ${selectedNewsIds.length > 0 ? 'bg-brand-orange text-white' : 'bg-slate-100 text-slate-300 cursor-not-allowed'}`}>Создать выпуск ({selectedNewsIds.length}/{MAX_SELECTION})</button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                <div className="lg:col-span-4"><DigestPostViewer digest={digest} pubConfig={pubConfig} /></div>
                <div className="lg:col-span-8 grid grid-cols-1 md:grid-cols-2 gap-6">
                   {digest.news.map(n => (
                      <div key={n.id} onClick={() => {
                        setSelectedNewsIds(prev => prev.includes(n.id) ? prev.filter(i => i !== n.id) : prev.length < MAX_SELECTION ? [...prev, n.id] : prev);
                      }} className={`p-6 rounded-3xl border-2 cursor-pointer transition-all bg-white relative ${selectedNewsIds.includes(n.id) ? 'border-brand-orange shadow-xl scale-[1.02]' : 'border-slate-100 hover:border-brand-orange/30'}`}>
                         <div className="flex justify-between mb-4">
                            <span className="text-[9px] font-black uppercase bg-slate-50 px-2 py-1 rounded text-slate-400">{n.location || 'АКТУАЛЬНО'}</span>
                            <div className={`w-5 h-5 rounded-full border-2 ${selectedNewsIds.includes(n.id) ? 'bg-brand-orange border-brand-orange' : 'border-slate-200'}`}></div>
                         </div>
                         <h4 className="font-black text-lg mb-2 leading-tight">{n.title}</h4>
                         <p className="text-slate-500 text-xs leading-relaxed">{n.summary}</p>
                      </div>
                   ))}
                </div>
            </div>
          </div>
        )}

        {(appState === AppState.GENERATING_CONTENT || appState === AppState.COMPLETED) && (
          <div className="space-y-10 animate-fade-in">
             {appState === AppState.GENERATING_CONTENT && (
                <div className="bg-brand-orange text-white p-6 rounded-3xl font-black text-center animate-pulse uppercase tracking-widest">{statusMessage}</div>
             )}
             <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                <div className="lg:col-span-4 sticky top-24 h-fit"><DigestPostViewer digest={digest!} pubConfig={pubConfig} /></div>
                <div className="lg:col-span-8 space-y-10">
                   {generatedResults.map(res => <ResultViewer key={res.newsId} pack={res} pubConfig={pubConfig} />)}
                </div>
             </div>
          </div>
        )}
      </main>
    </div>
  );
};

