import { PublishingConfig, WordPressConfig } from "../types";

const SMMBOX_BASE_URL = "https://smmbox.com/api/v1";

/**
 * Вспомогательная функция для форматирования даты под WordPress
 */
const formatDateForWP = (dateStr: string) => {
    if (!dateStr) return null;
    // WordPress ожидает ISO8601: YYYY-MM-DDTHH:MM:SS
    const date = new Date(dateStr);
    return date.toISOString().split('.')[0]; 
};

/**
 * Оборачивает URL в CORS прокси. 
 * corsproxy.io — один из немногих, кто надежно пробрасывает Authorization Header
 */
const wrapUrl = (url: string, useProxy: boolean) => {
    if (!useProxy) return url;
    return `https://corsproxy.io/?${encodeURIComponent(url)}`;
};

const fetchWithTimeout = async (url: string, options: RequestInit = {}, useProxy: boolean = false, timeout = 90000) => {
    const finalUrl = wrapUrl(url, useProxy);
    const controller = new AbortController();
    const id = setTimeout(() => controller.abort(), timeout);

    try {
        const response = await fetch(finalUrl, { 
            ...options, 
            signal: controller.signal
        });
        clearTimeout(id);

        if (response.status === 401) {
            throw new Error("401 Unauthorized: Проверьте API Токен в настройках.");
        }

        if (!response.ok) {
            const errText = await response.text();
            let errorMessage = `Ошибка ${response.status}`;
            try {
                const errData = JSON.parse(errText);
                errorMessage = errData.message || errData.error?.message || errorMessage;
            } catch (e) {
                if (errText.includes("<!DOCTYPE")) errorMessage += " (Сервер вернул HTML вместо JSON)";
                else errorMessage += `: ${errText.slice(0, 100)}`;
            }
            throw new Error(errorMessage);
        }

        return response;
    } catch (error: any) {
        clearTimeout(id);
        if (error.name === 'AbortError') throw new Error("Превышено время ожидания (таймаут).");
        if (error.message === 'Failed to fetch') {
            throw new Error("Ошибка сети (CORS). Попробуйте переключить 'Использовать Прокси' в настройках.");
        }
        throw error;
    }
};

/**
 * Получение групп SmmBox
 */
export const fetchSmmBoxGroups = async (config: PublishingConfig) => {
    const url = `${SMMBOX_BASE_URL}/groups`;
    const response = await fetchWithTimeout(url, {
        method: 'GET',
        headers: { 
            'Accept': 'application/json',
            'Authorization': `Bearer ${config.smmBoxToken}`
        }
    }, config.useProxy);

    const data = await response.json();
    return data.response || [];
};

/**
 * Публикация в SmmBox
 */
export const publishToSmmBox = async (
    config: PublishingConfig, 
    text: string, 
    imagesBase64: string[] = [], 
    publishDate?: Date
) => {
    if (!config.smmBoxToken) throw new Error("SmmBox Token не настроен");

    const allGroups = await fetchSmmBoxGroups(config);
    const targetGroups = allGroups.filter((g: any) => 
        g.name.toLowerCase().includes(config.targetGroupName.toLowerCase())
    );

    if (targetGroups.length === 0) {
        throw new Error(`Проект/Группа "${config.targetGroupName}" не найдена. Проверьте название точно как в SmmBox.`);
    }

    // Собираем вложения
    const attachments: any[] = [{ type: 'text', text }];

    // SmmBox принимает ссылки или base64 (но через API лучше слать ссылки или маленькие base64)
    // Мы шлем base64 как есть, но ограничиваем количество для стабильности
    imagesBase64.filter(img => img && img.startsWith('data:')).slice(0, 3).forEach(img => {
        attachments.push({ type: 'photo', original: img });
    });

    const postTime = publishDate || new Date(Date.now() + 10 * 60000);
    const unixTimestamp = Math.floor(postTime.getTime() / 1000);

    const postsData = targetGroups.map((group: any) => ({
        group: { id: group.id, social: group.social, type: group.type },
        date: unixTimestamp,
        attachments: attachments,
        options: ['from_group']
    }));

    const url = `${SMMBOX_BASE_URL}/posts/postpone`;
    const response = await fetchWithTimeout(url, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${config.smmBoxToken}`
        },
        body: JSON.stringify({ posts: postsData })
    }, config.useProxy);

    const result = await response.json();
    return result;
};

/**
 * Загрузка медиа в WordPress
 */
const uploadMediaToWP = async (wpConfig: WordPressConfig, useProxy: boolean, base64: string, filename: string) => {
    // Конвертируем base64 в Blob
    const res = await fetch(base64);
    const blob = await res.blob();
    const formData = new FormData();
    formData.append('file', blob, filename);

    const auth = btoa(`${wpConfig.username}:${wpConfig.applicationPassword}`);
    const url = `${wpConfig.url.replace(/\/$/, '')}/wp-json/wp/v2/media`;

    const response = await fetchWithTimeout(url, {
        method: 'POST',
        headers: { 'Authorization': `Basic ${auth}` },
        body: formData
    }, useProxy);

    return await response.json();
};

/**
 * WordPress Публикация
 */
export const publishToWordPress = async (
    config: WordPressConfig, 
    useProxy: boolean,
    title: string, 
    sections: {heading: string, body: string}[], 
    imagesBase64: string[], 
    tags: string,
    metaDescription: string,
    publishDateStr?: string,
    onProgress?: (msg: string) => void
) => {
    if (!config.url || !config.applicationPassword) throw new Error("Настройки WordPress не заполнены");

    const uploadedMediaUrls: string[] = [];
    const validImages = imagesBase64.filter(img => img && img.length > 100);

    // 1. Сначала грузим картинки
    for (let i = 0; i < validImages.length; i++) {
        try {
            if (onProgress) onProgress(`Загрузка фото ${i + 1} из ${validImages.length}...`);
            const media = await uploadMediaToWP(config, useProxy, validImages[i], `tourgenius-${Date.now()}-${i}.png`);
            uploadedMediaUrls.push(media.source_url);
        } catch (e) {
            console.warn("Ошибка загрузки фото в WP", e);
        }
    }

    // 2. Сборка HTML контента
    let htmlContent = '';
    sections.forEach((s, idx) => {
        if (s.heading) htmlContent += `<h2 class="wp-block-heading"><strong>${s.heading}</strong></h2>`;

        // Разделяем на параграфы
        const paragraphs = s.body.split('\n').filter(p => p.trim());
        paragraphs.forEach(p => {
            htmlContent += `<p>${p.trim()}</p>`;
        });

        // Вставляем картинку после секции, если есть
        if (uploadedMediaUrls[idx]) {
            htmlContent += `<figure class="wp-block-image size-large"><img src="${uploadedMediaUrls[idx]}" alt="${title}" /></figure>`;
        }
    });

    // Добавляем теги в конец контента (так надежнее чем через API тегов без ID)
    if (tags) {
        htmlContent += `<hr /><p><strong>Теги:</strong> ${tags}</p>`;
    }

    if (onProgress) onProgress(`Создание записи...`);

    const auth = btoa(`${config.username}:${config.applicationPassword}`);
    const url = `${config.url.replace(/\/$/, '')}/wp-json/wp/v2/posts`;

    const wpDate = formatDateForWP(publishDateStr || "");

    const body: any = {
        title: title,
        content: htmlContent,
        status: wpDate ? 'future' : 'publish',
        excerpt: metaDescription
    };

    if (wpDate) {
        body.date = wpDate;
    }

    const response = await fetchWithTimeout(url, {
        method: 'POST',
        headers: {
            'Authorization': `Basic ${auth}`,
            'Content-Type': 'application/json'
        },
        body: JSON.stringify(body)
    }, useProxy);

    return await response.json();
};

import React, { useState, useEffect } from 'react';
import { GeneratedContentPack, PublishingConfig, ArticleSection } from '../types';
import { publishToSmmBox, publishToWordPress } from '../services/publishingService';

interface ResultViewerProps {
  pack: GeneratedContentPack;
  pubConfig: PublishingConfig;
}

export const ResultViewer: React.FC<ResultViewerProps> = ({ pack, pubConfig }) => {
  const [activeTab, setActiveTab] = useState<'site' | 'tg' | 'vk_ok' | 'prompts'>('site');
  const [isEditing, setIsEditing] = useState(false);

  const [headline, setHeadline] = useState(pack.siteArticle?.headline || '');
  const [sections, setSections] = useState<ArticleSection[]>(pack.siteArticle?.sections || []);
  const [hashtags, setHashtags] = useState(pack.siteArticle?.hashtags || '');
  const [tgText, setTgText] = useState(pack.socials?.tg || '');
  const [vkOkText, setVkOkText] = useState(pack.socials?.vk_ok || '');

  const [publishing, setPublishing] = useState<boolean>(false);
  const [pubStatus, setPubStatus] = useState<{ success?: boolean; msg?: string }>({});
  const [scheduleDate, setScheduleDate] = useState<string>('');

  useEffect(() => {
    setHeadline(pack.siteArticle?.headline || '');
    setSections(pack.siteArticle?.sections || []);
    setHashtags(pack.siteArticle?.hashtags || '');
    setTgText(pack.socials?.tg || '');
    setVkOkText(pack.socials?.vk_ok || '');
  }, [pack]);

  const handleSmmPublish = async (text: string) => {
    setPublishing(true);
    setPubStatus({ msg: 'Подключение к SmmBox...' });
    try {
      const dateObj = scheduleDate ? new Date(scheduleDate) : undefined;
      const res = await publishToSmmBox(pubConfig, text, pack.generatedImages, dateObj);
      if (res.success) {
        setPubStatus({ success: true, msg: 'Успешно отправлено в SmmBox!' });
      } else {
        throw new Error(res.error?.message || "Ошибка SmmBox");
      }
    } catch (e: any) {
      setPubStatus({ success: false, msg: e.message });
    } finally { setPublishing(false); }
  };

  const handleWPPublish = async () => {
    setPublishing(true);
    setPubStatus({ msg: 'Начинаем публикацию...' });
    try {
      await publishToWordPress(
        pubConfig.wordPress, 
        pubConfig.useProxy, 
        headline, 
        sections, 
        pack.generatedImages, 
        hashtags, 
        pack.metaDescription, 
        scheduleDate,
        (msg) => setPubStatus({ msg }) // Обновляем текст статуса в процессе
      );
      setPubStatus({ success: true, msg: 'Статья успешно опубликована на сайте!' });
    } catch (e: any) {
      setPubStatus({ success: false, msg: e.message });
    } finally { setPublishing(false); }
  };

  return (
    <div className="bg-white rounded-[2rem] shadow-2xl overflow-hidden border border-slate-100 flex flex-col h-full animate-fade-in mb-10">
      <div className="bg-brand-dark border-b border-white/5 p-3 flex justify-between items-center">
        <div className="flex space-x-1">
          {['site', 'tg', 'vk_ok', 'prompts'].map((t) => (
            <button key={t} onClick={() => setActiveTab(t as any)} className={`px-4 py-2 text-[10px] font-black rounded-lg uppercase transition-all ${activeTab === t ? 'bg-brand-orange text-white' : 'text-slate-400'}`}>
              {t === 'site' ? 'Статья (WP)' : t === 'tg' ? 'Telegram' : t === 'vk_ok' ? 'VK/OK' : 'Промпты'}
            </button>
          ))}
        </div>
        <button onClick={() => setIsEditing(!isEditing)} className="px-4 py-2 text-[10px] font-black rounded-lg uppercase border border-white/20 text-white">
          {isEditing ? 'Сохранить' : 'Править'}
        </button>
      </div>

      <div className="p-8 overflow-y-auto flex-1 custom-scrollbar">
        {pubStatus.msg && (
            <div className={`mb-6 p-4 rounded-xl text-xs font-bold text-center border animate-pulse ${pubStatus.success === true ? 'bg-green-50 text-green-700 border-green-100' : pubStatus.success === false ? 'bg-red-50 text-red-700 border-red-100' : 'bg-blue-50 text-blue-700 border-blue-100'}`}>
                {pubStatus.msg}
            </div>
        )}

        <div className="mb-6 flex flex-wrap items-center gap-4 bg-slate-50 p-4 rounded-2xl border">
            <div className="flex-1 min-w-[200px]">
                <label className="block text-[9px] font-black text-slate-400 uppercase mb-1">Дата публикации (необязательно)</label>
                <input type="datetime-local" value={scheduleDate} onChange={e => setScheduleDate(e.target.value)} className="w-full text-xs p-2 rounded-lg border focus:ring-2 focus:ring-brand-orange outline-none" />
            </div>
            <button 
                onClick={() => activeTab === 'site' ? handleWPPublish() : handleSmmPublish(activeTab === 'tg' ? tgText : vkOkText)} 
                disabled={publishing}
                className="bg-brand-orange text-white px-8 py-3 rounded-xl font-black uppercase text-[10px] shadow-lg hover:scale-105 transition-all disabled:opacity-50"
            >
                {publishing ? 'В ПРОЦЕССЕ...' : 'ОПУБЛИКОВАТЬ'}
            </button>
        </div>

        {activeTab === 'site' && (
          <div className="article-font max-w-none">
            {isEditing ? (
              <div className="space-y-4">
                <input value={headline} onChange={e => setHeadline(e.target.value)} className="w-full text-2xl font-black border-b p-2" />
                {sections.map((s, i) => (
                  <div key={i} className="space-y-2 p-4 bg-slate-50 rounded-xl">
                    <input value={s.heading} onChange={e => {
                      const n = [...sections]; n[i].heading = e.target.value; setSections(n);
