import { GoogleGenAI } from "@google/genai";
import { DigestData, GeneratedContentPack, NewsItem } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

const getCurrentDate = () => {
  return new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' });
};

const cleanJsonResponse = (text: string) => {
  return text.replace(/```json/g, "").replace(/```/g, "").replace(/\\n/g, " ").trim();
};

/**
 * Глубокий поиск новостей за 48 часов
 */
export const fetchRealNews = async (count: number = 10): Promise<DigestData> => {
  const model = "gemini-3-flash-preview"; 
  const today = getCurrentDate();

  const systemInstruction = `
    ТЫ — ГЛАВНЫЙ РЕДАКТОР "ПЕРВОГО ТУРИСТИЧЕСКОГО". 
    ТЕКУЩАЯ ДАТА: ${today}.
    ЗАДАЧА: Собрать ${count} самых свежих новостей туризма.

    ЖЕСТКИЕ ПРАВИЛА:
    1. ТОЛЬКО ПОСЛЕДНИЕ 48 ЧАСОВ. Если новость старше — игнорируй. Проверяй даты публикации через Google Search.
    2. ИСТОЧНИКИ: ТАСС, РИА, Интерфакс, региональные порталы РФ (Екатеринбург, Сочи, Приморье и др.), международные ленты.
    3. БЕГУЩАЯ СТРОКА: Это должен быть формат "Заголовок: Краткое пояснение (расшифровка) новости".
    4. ФОРМАТ ДАЙДЖЕСТА: Каждая новость строго с новой строки, начинаясь с эмодзи.

    ВЕРНИ JSON:
    {
      "news": [
        { "title": "Заголовок", "summary": "Пояснение сути (фактура).", "location": "Регион", "ticker": "Заголовок: Краткая расшифровка" }
      ],
      "formattedDigestText": "Текст дайджеста (каждая новость с новой строки с эмодзи-номером).",
      "formattedShortDigest": "Заголовок: Расшифровка • Заголовок 2: Расшифровка 2",
      "collagePrompt": "Photorealistic cinematic 8k collage about tourism news, high quality photography. MUST include visible 3D bold text in Russian language: 'НОВОСТИ ТУРИЗМА'"
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Найди ${count} актуальных новостей туризма за последние 48 часов на ${today}. Игнорируй старое. Сделай акцент на регионы России.`,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction,
        responseMimeType: "application/json"
      }
    });

    const data = JSON.parse(cleanJsonResponse(response.text || ""));
    data.news = data.news.map((n: any, i: number) => ({...n, id: `news-${Date.now()}-${i}`}));
    return data;
  } catch (error) {
    console.error("News Fetch Error:", error);
    throw new Error("Не удалось собрать свежие новости.");
  }
};

/**
 * Генерация лонгрида в стиле Жванецкого и Хмелевской
 */
export const generateArticleLongread = async (newsItem: NewsItem): Promise<Omit<GeneratedContentPack, 'generatedImages'>> => {
  const model = "gemini-3-pro-preview";

  const systemInstruction = `
    ТЫ — АВТОР В СТИЛЕ ЖВАНЕЦКОГО И ХМЕЛЕВСКОЙ.
    ТЕМА: ${newsItem.title}. ФАКТЫ: ${newsItem.summary}.

    ТРЕБОВАНИЯ:
    1. ОБЪЕМ: Около 3000 знаков. 
    2. СТИЛЬ: Тонкий юмор, сарказм, метафоры. 
    3. ОФОРМЛЕНИЕ: Заголовок, подзаголовки (heading). 
    4. МЕТА: Обязательно напиши SEO meta-description (160 знаков) и теги (через запятую, без #).

    ВЕРНИ JSON:
    {
      "siteArticle": { 
        "headline": "Заголовок", 
        "sections": [
           { "heading": "Подзаголовок", "body": "Текст..." }
        ],
        "hashtags": "тег1, тег2" 
      },
      "socials": { 
        "tg": "Текст для ТГ с юмором и #хештегами", 
        "vk_ok": "Текст для ВК/ОК с юмором и #хештегами" 
      },
      "imagePrompts": ["Photorealistic 8k travel image, cinematic..."],
      "metaDescription": "SEO описание статьи для Google/Yandex"
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Напиши статью на 3000 знаков: ${newsItem.title}. Стиль: ирония и авантюризм. Обязательно добавь мета-описание.`,
      config: { 
        systemInstruction, 
        responseMimeType: "application/json" 
      }
    });

    const parsed = JSON.parse(cleanJsonResponse(response.text || ""));
    return { newsId: newsItem.id, ...parsed };
  } catch (error) {
    console.error("Longread error", error);
    throw new Error("Ошибка генерации лонгрида.");
  }
};

export const generateImage = async (prompt: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: `Photorealistic professional photography, 8k, cinematic: ${prompt}` }] },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    return part ? `data:image/png;base64,${part.inlineData.data}` : "";
  } catch { return ""; }
};

export const generateImagesForArticle = async (prompts: string[]): Promise<string[]> => {
  const images: string[] = [];
  for (const p of prompts.slice(0, 3)) {
    const img = await generateImage(p);
    if (img) images.push(img);
    await new Promise(r => setTimeout(r, 500)); 
  }
  return images;
};

import React, { useState, useEffect } from 'react';
import { DigestData, PublishingConfig } from '../types';
import { publishToSmmBox } from '../services/publishingService';

interface DigestPostViewerProps {
  digest: DigestData;
  pubConfig: PublishingConfig;
}

export const DigestPostViewer: React.FC<DigestPostViewerProps> = ({ digest, pubConfig }) => {
  const [activeView, setActiveView] = useState<'long' | 'short'>('long');
  const [editableText, setEditableText] = useState('');
  const [publishing, setPublishing] = useState<boolean>(false);
  const [pubStatus, setPubStatus] = useState<{success?: boolean, msg: string}>({msg: ''});
  const [scheduleDate, setScheduleDate] = useState<string>('');

  useEffect(() => {
    setEditableText(activeView === 'long' ? digest.formattedDigestText : digest.formattedShortDigest);
  }, [digest, activeView]);

  const getFinalText = () => {
      let text = editableText.replace(/\*\*/g, '').replace(/\*/g, '').trim();

      if (activeView === 'long') {
        text += `\n\n🟠 Информационный вечер Первого туристического\n📆 Каждый день с 17:00 до 20:00 — факты, новости и истории о путешествиях.\n\n➡️ Далее в 19:00 - \nЗатем в 20:00 - `;
      }
      return text;
  };

  const handlePublish = async () => {
    if (!pubConfig.smmBoxToken) {
        setPubStatus({success: false, msg: 'Настройте SmmBox Token!'});
        return;
    }

    setPublishing(true);
    setPubStatus({msg: 'Связь с SmmBox...'});

    const textToSend = getFinalText();
    const imagesToSend = (activeView === 'long' && digest.collageImage) ? [digest.collageImage] : [];
    const dateObj = scheduleDate ? new Date(scheduleDate) : undefined;

    try {
      const res = await publishToSmmBox(pubConfig, textToSend, imagesToSend, dateObj);
      if (res.success) {
        setPubStatus({success: true, msg: 'Дайджест запланирован!'});
      } else {
        throw new Error(res.error?.message || 'Ошибка API');
      }
    } catch (e: any) {
      setPubStatus({success: false, msg: e.message});
    } finally {
      setPublishing(false);
    }
  };

  return (
    <div className="bg-white rounded-[2rem] shadow-2xl overflow-hidden border border-slate-200 h-full flex flex-col min-h-[700px] animate-fade-in">
      <div className="bg-slate-50 border-b p-4 flex justify-between items-center">
        <div className="flex gap-1">
            <button onClick={() => setActiveView('long')} className={`text-[9px] px-4 py-2 rounded-xl font-black uppercase transition-all ${activeView === 'long' ? 'bg-brand-orange text-white shadow-md' : 'text-slate-400'}`}>Дайджест</button>
            <button onClick={() => setActiveView('short')} className={`text-[9px] px-4 py-2 rounded-xl font-black uppercase transition-all ${activeView === 'short' ? 'bg-brand-orange text-white shadow-md' : 'text-slate-400'}`}>Бег. строка</button>
        </div>
        <div className="text-[10px] font-black text-slate-300">РЕДАКТОР</div>
      </div>

      <div className="p-0 overflow-y-auto custom-scrollbar flex-1 flex flex-col">
        {activeView === 'long' && digest.collageImage && (
            <div className="h-48 w-full bg-slate-900 shrink-0">
                <img src={digest.collageImage} className="w-full h-full object-cover opacity-60" />
            </div>
        )}

        <div className="p-4 bg-slate-50 border-b space-y-4">
           <div className="flex flex-col gap-1">
              <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Запланировать в SmmBox</label>
              <input type="datetime-local" value={scheduleDate} onChange={(e) => setScheduleDate(e.target.value)} className="w-full text-[11px] p-2 rounded-lg border focus:ring-2 focus:ring-brand-orange outline-none bg-white" />
           </div>

           <button 
             onClick={handlePublish} 
             disabled={publishing} 
             className="w-full bg-brand-dark text-white text-[10px] font-black py-3 rounded-lg uppercase tracking-widest hover:bg-brand-orange transition-all disabled:opacity-50"
           >
             {publishing ? 'Публикация...' : 'ОПУБЛИКОВАТЬ'}
           </button>

           {pubStatus.msg && (
               <p className={`text-[9px] text-center font-bold uppercase ${pubStatus.success === false ? 'text-red-500' : 'text-brand-orange'}`}>
                 {pubStatus.msg}
               </p>
           )}
        </div>

        <div className="p-6 flex-1 bg-white">
            <textarea 
                value={editableText}
                onChange={(e) => setEditableText(e.target.value)}
                className="w-full h-full min-h-[300px] text-sm text-slate-700 leading-relaxed font-medium outline-none border-none resize-none custom-scrollbar"
                placeholder="Текст дайджеста..."
            />
            {activeView === 'long' && (
                <div className="mt-4 p-4 bg-slate-50 rounded-xl border border-dashed border-slate-200 opacity-60 italic text-[10px] text-slate-500">
                    [К посту будет добавлена подпись «Информационный вечер»]
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

