                  <p className="text-[10px] font-black text-brand-orange uppercase">Выберите 2 новости для превращения в лонгриды</p>
               </div>
               <button onClick={handleGenerate} disabled={selectedNewsIds.length === 0} className={`px-12 py-4 rounded-xl font-black uppercase text-xs shadow-lg transition-all ${selectedNewsIds.length > 0 ? 'bg-brand-orange text-white' : 'bg-slate-100 text-slate-300 cursor-not-allowed'}`}>Написать статьи ({selectedNewsIds.length}/{MAX_SELECTION})</button>
