import React, { useState, useEffect } from 'react';
import { DigestData, PublishingConfig } from '../types';
import { publishToSmmBox } from '../services/publishingService';

interface DigestPostViewerProps {
  digest: DigestData;
  pubConfig: PublishingConfig;
}

export const DigestPostViewer: React.FC<DigestPostViewerProps> = ({ digest, pubConfig }) => {
  const [activeView, setActiveView] = useState<'long' | 'short'>('long');
  const [editableText, setEditableText] = useState('');
  const [publishing, setPublishing] = useState<boolean>(false);
  const [pubStatus, setPubStatus] = useState<{success?: boolean, msg: string}>({msg: ''});
  const [scheduleDate, setScheduleDate] = useState<string>('');

  useEffect(() => {
    // При переключении вкладок или обновлении данных сбрасываем текст
    setEditableText(activeView === 'long' ? digest.formattedDigestText : digest.formattedShortDigest);
  }, [digest, activeView]);

  const getFinalText = () => {
      let text = editableText.trim();

      if (activeView === 'long') {
        text += `\n\n🟠 Информационный вечер Первого туристического\n📆 Каждый день с 17:00 до 20:00 — факты, новости и истории о путешествиях.\n\n➡️ Далее в 19:00 -\n➡️ Затем в 20:00 -`;
      }
      return text;
  };

  const handlePublish = async () => {
    if (!pubConfig.smmBoxToken) {
        setPubStatus({success: false, msg: 'Настройте API Токен в настройках!'});
        return;
    }

    setPublishing(true);
    setPubStatus({msg: 'Отправка в SmmBox...'});

    const textToSend = getFinalText();
    const imagesToSend = (activeView === 'long' && digest.collageImage) ? [digest.collageImage] : [];
    const dateObj = scheduleDate ? new Date(scheduleDate) : undefined;

    try {
      const res = await publishToSmmBox(pubConfig, textToSend, imagesToSend, dateObj);
      if (res.success) {
        setPubStatus({success: true, msg: 'Дайджест запланирован успешно!'});
      } else {
        throw new Error(res.error?.message || 'Ошибка API SmmBox');
      }
    } catch (e: any) {
      setPubStatus({success: false, msg: e.message});
    } finally {
      setPublishing(false);
    }
  };

  return (
    <div className="bg-white rounded-[2rem] shadow-2xl overflow-hidden border border-slate-200 h-full flex flex-col min-h-[700px] animate-fade-in">
      <div className="bg-slate-100 border-b p-4 flex justify-between items-center">
        <div className="flex gap-2">
            <button 
              onClick={() => setActiveView('long')} 
              className={`text-[10px] px-5 py-2 rounded-xl font-black uppercase transition-all ${activeView === 'long' ? 'bg-brand-orange text-white shadow-md' : 'bg-white text-slate-400 border border-slate-200'}`}
            >
              Дайджест
            </button>
            <button 
              onClick={() => setActiveView('short')} 
              className={`text-[10px] px-5 py-2 rounded-xl font-black uppercase transition-all ${activeView === 'short' ? 'bg-brand-orange text-white shadow-md' : 'bg-white text-slate-400 border border-slate-200'}`}
            >
              Бег. строка
            </button>
        </div>
        <div className="text-[10px] font-black text-slate-400 italic">РЕДАКТОР</div>
      </div>

      <div className="p-0 overflow-y-auto custom-scrollbar flex-1 flex flex-col bg-white">
        {activeView === 'long' && digest.collageImage && (
            <div className="h-40 w-full bg-slate-900 shrink-0">
                <img src={digest.collageImage} className="w-full h-full object-cover opacity-80" alt="Collage" />
            </div>
        )}

        <div className="p-4 bg-slate-50 border-b space-y-4">
           <div className="flex flex-col gap-1">
              <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Дата и время публикации</label>
              <input 
                type="datetime-local" 
                value={scheduleDate} 
                onChange={(e) => setScheduleDate(e.target.value)} 
                className="w-full text-xs p-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-brand-orange outline-none bg-white font-bold" 
              />
           </div>

           <button 
             onClick={handlePublish} 
             disabled={publishing} 
             className="w-full bg-brand-dark text-white text-[10px] font-black py-4 rounded-xl uppercase tracking-widest hover:bg-brand-orange transition-all disabled:opacity-50 shadow-lg"
           >
             {publishing ? 'ВЫПОЛНЯЕТСЯ...' : 'ЗАПЛАНИРОВАТЬ В SMMBOX'}
           </button>

           {pubStatus.msg && (
               <div className={`p-3 rounded-lg text-[10px] text-center font-black uppercase border ${pubStatus.success === false ? 'bg-red-50 text-red-500 border-red-100' : 'bg-orange-50 text-brand-orange border-orange-100'}`}>
                 {pubStatus.msg}
               </div>
           )}
        </div>

        <div className="p-6 flex-1 bg-white">
            <textarea 
                value={editableText}
                onChange={(e) => setEditableText(e.target.value)}
                className="w-full h-full min-h-[400px] text-sm text-black leading-relaxed font-medium outline-none border-none resize-none custom-scrollbar placeholder-slate-300"
                placeholder="Текст будет здесь..."
            />
            {activeView === 'long' && (
                <div className="mt-4 p-4 bg-slate-50 rounded-2xl border border-dashed border-slate-200 italic text-[10px] text-slate-400 leading-tight">
                    Подпись "Информационный вечер" будет добавлена автоматически при отправке.
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { fetchRealNews, generateArticleLongread, generateImage, generateImagesForArticle } from './services/geminiService';
