  const [pubConfig, setPubConfig] = useState<PublishingConfig>({
    smmBoxToken: '', 
    targetGroupName: 'Первый туристический',
    useProxy: false,
    wordPress: { url: '', username: '', applicationPassword: '' }
  });

  useEffect(() => {
    const saved = localStorage.getItem('tourgenius_settings');
    if (saved) { try { setPubConfig(JSON.parse(saved)); } catch(e) {} }
  }, []);

  const handleFetchNews = async () => {
    setAppState(AppState.SEARCHING);
    setStatusMessage("Сканируем ленты за 48 часов...");
    try {
      const data = await fetchRealNews(12);
      setDigest(data);
      setAppState(AppState.SELECTING);
      if (data.collagePrompt) {
        generateImage(data.collagePrompt).then(img => {
          if (img) setDigest(prev => prev ? ({ ...prev, collageImage: img }) : null);
        });
      }
    } catch (e: any) { setAppState(AppState.IDLE); alert(e.message); }
  };

  const handleToggleSelection = (id: string) => {
    setSelectedNewsIds(prev => {
      if (prev.includes(id)) {
        return prev.filter(i => i !== id);
      } else if (prev.length < MAX_SELECTION) {
        return [...prev, id];
      }
      return prev;
    });
  };

  const handleReplaceNews = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation(); // Не переключать выбор при нажатии на замену
    try {
      const replacement = await fetchRealNews(1);
      const newNews = replacement.news[0];
      if (digest) {
        setDigest({
          ...digest,
          news: digest.news.map(n => n.id === id ? newNews : n)
        });
        setSelectedNewsIds(prev => prev.filter(i => i !== id));
      }
