    };
    setDigest({ ...digest, news: [newItem, ...digest.news] });
  };

  const handleGenerate = async () => {
    setAppState(AppState.GENERATING_CONTENT);
    setGeneratedResults([]);
    const items = digest?.news.filter(n => selectedNewsIds.includes(n.id)) || [];

    for (let i = 0; i < items.length; i++) {
