           )}
           <button onClick={() => setIsSettingsOpen(true)} className="w-10 h-10 bg-slate-50 flex items-center justify-center rounded-xl border text-lg">⚙️</button>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto p-6">
        {appState === AppState.IDLE && (
          <div className="bg-white rounded-[3rem] p-20 shadow-2xl border text-center mt-10">
            <h2 className="text-5xl font-black text-brand-dark mb-6 uppercase italic">Голос <span className="text-brand-orange">Жванецкого</span></h2>
            <p className="text-slate-400 text-lg mb-10">Свежайшие новости туризма за 48 часов с авторской иронией.</p>
