             <h3 className="text-2xl font-black text-brand-dark uppercase italic animate-pulse">{statusMessage}</h3>
          </div>
        )}

        {appState === AppState.SELECTING && digest && (
          <div className="space-y-10 animate-fade-in">
            <div className="flex justify-between items-center bg-white p-8 rounded-3xl border shadow-xl sticky top-24 z-40">
               <div>
                  <h2 className="text-2xl font-black text-brand-dark uppercase italic">Выбор тем на сегодня</h2>
