import { GoogleGenAI } from "@google/genai";
import { DigestData, GeneratedContentPack, NewsItem } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

const getCurrentDate = () => {
  return new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' });
};

const cleanJsonResponse = (text: string) => {
  return text.replace(/```json/g, "").replace(/```/g, "").replace(/\\n/g, " ").trim();
};

/**
 * Глубокий поиск новостей за 48 часов
 */
export const fetchRealNews = async (count: number = 10): Promise<DigestData> => {
  const model = "gemini-3-flash-preview"; 
  const today = getCurrentDate();

  const systemInstruction = `
    ТЫ — ГЛАВНЫЙ РЕДАКТОР "ПЕРВОГО ТУРИСТИЧЕСКОГО". 
    ТЕКУЩАЯ ДАТА: ${today}.
    ЗАДАЧА: Собрать ${count} самых свежих новостей туризма за ПОСЛЕДНИЕ 48 ЧАСОВ.

    ЖЕСТКИЕ ПРАВИЛА:
    1. ИГНОРИРУЙ ВСЁ, что старше 2 дней.
    2. ИСТОЧНИКИ: Ведущие ленты (ТАСС, РИА) + региональные порталы.
    3. БЕГУЩАЯ СТРОКА: Это должен быть список коротких фактов. Формат: "Заголовок: Развернутая расшифровка сути новости в одном предложении".
    4. ДАЙДЖЕСТ: Каждая новость строго с новой строки с эмодзи.

    ВЕРНИ JSON:
    {
      "news": [
        { "title": "Заголовок", "summary": "Пояснение сути для AI.", "location": "Регион", "ticker": "Заголовок: Расшифровка" }
      ],
      "formattedDigestText": "Текст дайджеста (строго с новой строки каждая новость).",
      "formattedShortDigest": "Новость 1: Расшифровка • Новость 2: Расшифровка • Новость 3: Расшифровка",
      "collagePrompt": "Photorealistic cinematic 8k collage about tourism news, high quality photography. Visible text: 'НОВОСТИ ТУРИЗМА'"
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Собери ${count} новостей туризма на ${today}. Игнорируй новости старше 48 часов. Сделай акцент на Россию.`,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction,
        responseMimeType: "application/json"
      }
    });

    const data = JSON.parse(cleanJsonResponse(response.text || ""));
    // Генерируем уникальные ID на основе заголовка и времени
    data.news = data.news.map((n: any, i: number) => ({
      ...n, 
      id: `news-${Date.now()}-${n.title.slice(0, 10).replace(/\s/g, '')}-${i}`
    }));
    return data;
  } catch (error) {
    console.error("News Fetch Error:", error);
    throw new Error("Не удалось собрать новости. Попробуйте еще раз через 5 секунд.");
  }
};

/**
 * Генерация лонгрида
 */
export const generateArticleLongread = async (newsItem: NewsItem): Promise<Omit<GeneratedContentPack, 'generatedImages'>> => {
  const model = "gemini-3-pro-preview";

  const systemInstruction = `
    ТЫ — АВТОР В СТИЛЕ ЖВАНЕЦКОГО И ХМЕЛЕВСКОЙ.
    ТЕМА: ${newsItem.title}. ФАКТЫ: ${newsItem.summary}.

    ТРЕБОВАНИЯ:
    1. ТЕКСТ: Ирония, авантюризм, тонкий юмор. 3000 знаков.
    2. ОФОРМЛЕНИЕ: Заголовок, подзаголовки.
    3. МЕТА-ОПИСАНИЕ: Обязательно (160 знаков).

    ВЕРНИ JSON:
    {
      "siteArticle": { 
        "headline": "...", 
        "sections": [{ "heading": "...", "body": "..." }],
        "hashtags": "тег1, тег2" 
      },
      "socials": { 
        "tg": "Текст для Telegram", 
        "vk_ok": "Текст для соцсетей" 
      },
      "imagePrompts": ["Photorealistic 8k travel photo..."],
      "metaDescription": "SEO описание статьи"
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Напиши статью по новости: ${newsItem.title}. Добавь мета-описание для сайта.`,
      config: { 
        systemInstruction, 
        responseMimeType: "application/json" 
      }
    });

    return JSON.parse(cleanJsonResponse(response.text || ""));
  } catch (error) {
    console.error("Longread error", error);
    throw new Error("Не удалось написать статью.");
  }
};

export const generateImage = async (prompt: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: prompt }] },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    return part ? `data:image/png;base64,${part.inlineData.data}` : "";
  } catch { return ""; }
};

export const generateImagesForArticle = async (prompts: string[]): Promise<string[]> => {
  const images: string[] = [];
  for (const p of prompts.slice(0, 3)) {
    const img = await generateImage(p);
    if (img) images.push(img);
    await new Promise(r => setTimeout(r, 600)); 
  }
  return images;
};

