import React, { useState, useEffect } from 'react';
import { GeneratedContentPack, PublishingConfig, ArticleSection } from '../types';
import { publishToSmmBox, publishToWordPress } from '../services/publishingService';

interface ResultViewerProps {
  pack: GeneratedContentPack;
  pubConfig: PublishingConfig;
}

export const ResultViewer: React.FC<ResultViewerProps> = ({ pack, pubConfig }) => {
  const [activeTab, setActiveTab] = useState<'site' | 'tg' | 'vk_ok' | 'prompts'>('site');
  const [isEditing, setIsEditing] = useState(false);

  const [headline, setHeadline] = useState(pack.siteArticle?.headline || '');
  const [sections, setSections] = useState<ArticleSection[]>(pack.siteArticle?.sections || []);
  const [hashtags, setHashtags] = useState(pack.siteArticle?.hashtags || '');
  const [tgText, setTgText] = useState(pack.socials?.tg || '');
  const [vkOkText, setVkOkText] = useState(pack.socials?.vk_ok || '');
  const [metaDesc, setMetaDesc] = useState(pack.metaDescription || '');

  const [publishing, setPublishing] = useState<boolean>(false);
  const [pubStatus, setPubStatus] = useState<{ success?: boolean; msg?: string }>({});
  const [scheduleDate, setScheduleDate] = useState<string>('');

  useEffect(() => {
    setHeadline(pack.siteArticle?.headline || '');
    setSections(pack.siteArticle?.sections || []);
    setHashtags(pack.siteArticle?.hashtags || '');
    setTgText(pack.socials?.tg || '');
    setVkOkText(pack.socials?.vk_ok || '');
    setMetaDesc(pack.metaDescription || '');
  }, [pack]);

  const getFinalSocialText = (baseText: string) => {
    // Подпись для статей в соцсетях
    return baseText + `\n\n🟠 Информационный вечер Первого туристического\n📆 Каждый день с 17:00 до 20:00 — факты, новости и истории о путешествиях.\n\n➡️ Далее в 20:00 - `;
  };

  const handleSmmPublish = async (text: string) => {
    setPublishing(true);
    setPubStatus({ msg: 'Подготовка поста для SmmBox...' });
    try {
      const dateObj = scheduleDate ? new Date(scheduleDate) : undefined;
      const finalMsg = getFinalSocialText(text);
      const res = await publishToSmmBox(pubConfig, finalMsg, pack.generatedImages, dateObj);
      if (res.success) {
        setPubStatus({ success: true, msg: 'Статья успешно запланирована в SmmBox!' });
      } else {
        throw new Error(res.error?.message || "Ошибка API");
      }
    } catch (e: any) {
      setPubStatus({ success: false, msg: e.message });
    } finally { setPublishing(false); }
  };

  const handleWPPublish = async () => {
    setPublishing(true);
    setPubStatus({ msg: 'Загрузка статьи в WordPress...' });
    try {
      await publishToWordPress(
        pubConfig.wordPress, 
        pubConfig.useProxy, 
        headline, 
        sections, 
        pack.generatedImages, 
        hashtags, 
        metaDesc, 
        scheduleDate,
        (msg) => setPubStatus({ msg })
      );
      setPubStatus({ success: true, msg: 'Статья опубликована на сайте!' });
    } catch (e: any) {
      setPubStatus({ success: false, msg: e.message });
    } finally { setPublishing(false); }
  };

  return (
    <div className="bg-white rounded-[2rem] shadow-2xl overflow-hidden border border-slate-100 flex flex-col h-full animate-fade-in mb-10">
      <div className="bg-brand-dark border-b border-white/5 p-4 flex justify-between items-center">
        <div className="flex gap-2">
          {['site', 'tg', 'vk_ok', 'prompts'].map((t) => (
            <button key={t} onClick={() => setActiveTab(t as any)} className={`px-4 py-2 text-[10px] font-black rounded-xl uppercase transition-all ${activeTab === t ? 'bg-brand-orange text-white' : 'bg-slate-800 text-slate-400'}`}>
              {t === 'site' ? 'Сайт (WP)' : t === 'tg' ? 'Telegram' : t === 'vk_ok' ? 'VK/OK' : 'Промпты'}
            </button>
          ))}
        </div>
        <button onClick={() => setIsEditing(!isEditing)} className="px-5 py-2 text-[10px] font-black rounded-xl uppercase border border-white/20 text-white hover:bg-white/10">
          {isEditing ? 'СОХРАНИТЬ' : 'РЕДАКТИРОВАТЬ'}
        </button>
      </div>

      <div className="p-8 overflow-y-auto flex-1 custom-scrollbar">
        {pubStatus.msg && (
            <div className={`mb-6 p-4 rounded-xl text-xs font-bold text-center border animate-pulse ${pubStatus.success === true ? 'bg-green-50 text-green-700 border-green-100' : pubStatus.success === false ? 'bg-red-50 text-red-700 border-red-100' : 'bg-blue-50 text-blue-700 border-blue-100'}`}>
                {pubStatus.msg}
            </div>
        )}

        <div className="mb-8 flex flex-wrap items-center gap-4 bg-slate-50 p-5 rounded-3xl border border-slate-200">
            <div className="flex-1 min-w-[200px]">
                <label className="block text-[9px] font-black text-slate-400 uppercase mb-2 ml-1">Запланировать публикацию</label>
                <input type="datetime-local" value={scheduleDate} onChange={e => setScheduleDate(e.target.value)} className="w-full text-xs p-3 rounded-xl border border-slate-200 outline-none bg-white font-bold" />
            </div>
            <button 
                onClick={() => activeTab === 'site' ? handleWPPublish() : handleSmmPublish(activeTab === 'tg' ? tgText : vkOkText)} 
                disabled={publishing}
                className="bg-brand-orange text-white px-10 py-4 rounded-xl font-black uppercase text-[10px] shadow-lg hover:scale-105 transition-all disabled:opacity-50"
            >
                {publishing ? 'В ПРОЦЕССЕ...' : 'ОПУБЛИКОВАТЬ'}
            </button>
        </div>

        {activeTab === 'site' && (
          <div className="article-font max-w-none">
            {isEditing ? (
              <div className="space-y-6">
                <div>
                  <label className="text-[9px] font-black text-slate-400 uppercase mb-1 block">Заголовок (от Первого Туристического)</label>
                  <input value={headline} onChange={e => setHeadline(e.target.value)} className="w-full text-2xl font-black border-b border-slate-300 p-2 outline-none focus:border-brand-orange" />
                </div>
                <div className="bg-orange-50 p-5 rounded-2xl border border-orange-100">
                    <label className="text-[9px] font-black text-brand-orange uppercase block mb-1">SEO Мета-описание (WP Excerpt)</label>
                    <textarea value={metaDesc} onChange={e => setMetaDesc(e.target.value)} className="w-full h-20 p-3 text-sm border rounded-xl mt-1 focus:ring-2 focus:ring-brand-orange outline-none" />
                </div>
                {sections.map((s, i) => (
                  <div key={i} className="space-y-3 p-5 bg-slate-50 rounded-2xl border border-slate-200">
                    <input value={s.heading} onChange={e => {
                      const n = [...sections]; n[i].heading = e.target.value; setSections(n);
                    }} className="w-full font-bold border-b border-slate-300 p-1 text-lg bg-transparent" placeholder="Заголовок блока" />
                    <textarea value={s.body} onChange={e => {
                      const n = [...sections]; n[i].body = e.target.value; setSections(n);
                    }} className="w-full h-48 p-3 border rounded-xl bg-white text-sm" placeholder="Текст статьи..." />
                  </div>
                ))}
                <div className="p-4 bg-slate-50 border rounded-xl">
                  <label className="text-[9px] font-black text-slate-400 uppercase block mb-1">Хэштеги (через запятую, без #)</label>
                  <input value={hashtags} onChange={e => setHashtags(e.target.value)} className="w-full p-2 border rounded" placeholder="туризм, отдых, сочи" />
                </div>
              </div>
            ) : (
              <div className="bg-white">
                <h1 className="text-4xl font-black text-brand-dark mb-10 italic leading-tight">{headline}</h1>
                {sections.map((s, i) => (
                  <div key={i} className="mb-12">
                    {s.heading && <h2 className="text-2xl font-bold mb-6 uppercase text-brand-orange italic"><strong>{s.heading}</strong></h2>}
                    <div className="text-lg leading-relaxed text-slate-800 space-y-6">
                        {s.body.split('\n').filter(p => p.trim()).map((para, pIdx) => (
                            <p key={pIdx} style={{ textIndent: '1.5rem' }}>{para.trim()}</p>
                        ))}
                    </div>
                    {pack.generatedImages[i] && <img src={pack.generatedImages[i]} className="w-full my-10 rounded-[2.5rem] shadow-2xl border-8 border-white bg-slate-100" alt={`Image ${i+1}`} />}
                  </div>
                ))}
                <div className="mt-12 pt-8 border-t text-[11px] text-slate-400 font-bold uppercase italic">
                    Тэги: {hashtags}
                </div>
              </div>
            )}
          </div>
        )}

        {(activeTab === 'tg' || activeTab === 'vk_ok') && (
            <div className="max-w-2xl mx-auto">
                <textarea 
                    value={activeTab === 'tg' ? tgText : vkOkText} 
                    onChange={e => activeTab === 'tg' ? setTgText(e.target.value) : setVkOkText(e.target.value)}
                    className="w-full h-[600px] p-10 bg-white text-black border border-slate-200 rounded-[3rem] font-sans leading-relaxed text-lg shadow-inner outline-none focus:ring-4 focus:ring-brand-orange/10 transition-all custom-scrollbar"
                />
                <p className="mt-4 text-[10px] text-slate-400 font-bold italic text-center">К этому тексту при публикации будет добавлена подпись "Информационный вечер".</p>
            </div>
        )}
      </div>
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";
import { DigestData, GeneratedContentPack, NewsItem } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

const getCurrentDate = () => {
  return new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' });
};

const cleanJsonResponse = (text: string) => {
  return text.replace(/```json/g, "").replace(/```/g, "").replace(/\\n/g, " ").trim();
};

/**
 * Глубокий поиск новостей за 48 часов
 */
export const fetchRealNews = async (count: number = 10): Promise<DigestData> => {
  const model = "gemini-3-flash-preview"; 
  const today = getCurrentDate();

  const systemInstruction = `
    ТЫ — ГЛАВНЫЙ РЕДАКТОР "ПЕРВОГО ТУРИСТИЧЕСКОГО ТЕЛЕКАНАЛА". 
    ТЕКУЩАЯ ДАТА: ${today}.
    ЗАДАЧА: Собрать ${count} самых свежих новостей туризма за ПОСЛЕДНИЕ 48 ЧАСОВ.

    ЖЕСТКИЕ ПРАВИЛА:
    1. ИГНОРИРУЙ ВСЁ, что старше 2 суток.
    2. ИСТОЧНИКИ: ТАСС, РИА, официальные региональные каналы.
    3. БЕГУЩАЯ СТРОКА: Формат: "Заголовок: Развернутая расшифровка сути новости в одном предложении (что случилось, почему важно)". Каждая новость — это польза.
    4. ДАЙДЖЕСТ: Каждая новость строго с новой строки с тематическим эмодзи.

    ВЕРНИ JSON:
    {
      "news": [
        { "title": "Заголовок", "summary": "Пояснение сути.", "location": "Регион", "ticker": "Заголовок: Расшифровка смысла" }
      ],
      "formattedDigestText": "Текст дайджеста (каждая новость с новой строки).",
      "formattedShortDigest": "Новость 1: Расшифровка • Новость 2: Расшифровка",
      "collagePrompt": "Photorealistic cinematic 8k collage about tourism news, high quality photography. Text: 'НОВОСТИ ТУРИЗМА'"
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Найди ${count} самых горячих новостей туризма на ${today}. Исключи старье. Акцент на Россию и доступные направления.`,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction,
        responseMimeType: "application/json"
      }
    });

    const data = JSON.parse(cleanJsonResponse(response.text || ""));
    data.news = data.news.map((n: any, i: number) => ({
      ...n, 
      id: `news-${Date.now()}-${i}`
    }));
    return data;
  } catch (error) {
    console.error("News Fetch Error:", error);
    throw new Error("Не удалось загрузить новости. Повторите попытку.");
  }
};

/**
 * Генерация лонгрида от имени Первого Туристического
 */
export const generateArticleLongread = async (newsItem: NewsItem): Promise<Omit<GeneratedContentPack, 'generatedImages'>> => {
  const model = "gemini-3-pro-preview";

  const systemInstruction = `
    ТЫ — ВЕДУЩИЙ АВТОР "ПЕРВОГО ТУРИСТИЧЕСКОГО ТЕЛЕКАНАЛА".
    СТИЛЬ: Ироничный, как у Жванецкого, но профессиональный, как у опытного путешественника.
