    1. ТЕКСТ: Глубокий лонгрид на 3000 знаков. Никаких "Я", только "Мы" или "Первый туристический". 
    2. ОФОРМЛЕНИЕ: Заголовок, 3-4 смысловых раздела с подзаголовками.
    3. МЕТА-ОПИСАНИЕ: Лаконичное SEO описание (excerpt).
    4. ХЕШТЕГИ: Строго БЕЗ символа # и ЧЕРЕЗ ЗАПЯТУЮ (например: туризм, отдых, новости).

    ВЕРНИ JSON:
    {
      "siteArticle": { 
        "headline": "...", 
        "sections": [{ "heading": "...", "body": "..." }],
        "hashtags": "слово1, слово2, фраза3" 
      },
      "socials": { 
        "tg": "Ироничный пост для Телеграм", 
        "vk_ok": "Пост для ВК/ОК" 
      },
      "imagePrompts": ["Cinematic photorealistic 8k travel photo..."],
      "metaDescription": "Описание статьи для поиска"
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Напиши статью на тему: ${newsItem.title}. Стиль: Первый Туристический + Жванецкий. Хештеги без # через запятую.`,
      config: { 
        systemInstruction, 
        responseMimeType: "application/json" 
      }
    });

    return JSON.parse(cleanJsonResponse(response.text || ""));
  } catch (error) {
    console.error("Longread error", error);
    throw new Error("Ошибка генерации статьи.");
  }
};

export const generateImage = async (prompt: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: prompt }] },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    return part ? `data:image/png;base64,${part.inlineData.data}` : "";
  } catch { return ""; }
};

export const generateImagesForArticle = async (prompts: string[]): Promise<string[]> => {
  const images: string[] = [];
  for (const p of prompts.slice(0, 3)) {
    const img = await generateImage(p);
    if (img) images.push(img);
    await new Promise(r => setTimeout(r, 600)); 
  }
  return images;
};

