    3. ХЕШТЕГИ: Строго БЕЗ символа #, через запятую (например: отдых, туризм, сочи).
    4. СОЦСЕТИ: Сделай ироничный пост.

    ВЕРНИ JSON:
    {
      "siteArticle": { 
        "headline": "Заголовок", 
        "sections": [{ "heading": "Подзаголовок", "body": "Текст..." }],
        "hashtags": "тег1, тег2, тег3" 
      },
      "socials": { 
        "tg": "Пост для ТГ", 
        "vk_ok": "Пост для ВК/ОК" 
      },
      "imagePrompts": ["High quality travel photo..."],
      "metaDescription": "SEO описание"
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Напиши статью: ${newsItem.title}. Стиль: Первый Туристический + Жванецкий. Хештеги через запятую без #.`,
      config: { 
        systemInstruction, 
        responseMimeType: "application/json" 
      }
    });
    return JSON.parse(cleanJsonResponse(response.text || ""));
  } catch (error) {
    throw new Error("Ошибка генерации статьи.");
  }
};

export const generateImage = async (prompt: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: prompt }] },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    return part ? `data:image/png;base64,${part.inlineData.data}` : "";
  } catch { return ""; }
};

export const generateImagesForArticle = async (prompts: string[]): Promise<string[]> => {
  const images: string[] = [];
  for (const p of prompts.slice(0, 3)) {
    const img = await generateImage(p);
    if (img) images.push(img);
    await new Promise(r => setTimeout(r, 600)); 
  }
  return images;
};

import React, { useState, useEffect } from 'react';
import { DigestData, PublishingConfig } from '../types';
import { publishToSmmBox } from '../services/publishingService';

interface DigestPostViewerProps {
  digest: DigestData;
  pubConfig: PublishingConfig;
}

export const DigestPostViewer: React.FC<DigestPostViewerProps> = ({ digest, pubConfig }) => {
  const [activeView, setActiveView] = useState<'long' | 'short'>('long');
  const [editableText, setEditableText] = useState('');
  const [publishing, setPublishing] = useState<boolean>(false);
  const [pubStatus, setPubStatus] = useState<{success?: boolean, msg: string}>({msg: ''});
  const [scheduleDate, setScheduleDate] = useState<string>('');

  // Формируем начальный текст с подписью, чтобы ее можно было редактировать
  const getInitialText = (view: 'long' | 'short') => {
    let text = view === 'long' ? digest.formattedDigestText : digest.formattedShortDigest;
    if (view === 'long') {
      text += `\n\n🟠 Информационный вечер Первого туристического\n📆 Каждый день с 17:00 до 20:00 — факты, новости и истории о путешествиях.\n\n➡️ Далее в 19:00 -\n➡️ Затем в 20:00 -`;
    }
    return text;
  };

  useEffect(() => {
    setEditableText(getInitialText(activeView));
  }, [digest, activeView]);

  const handlePublish = async () => {
    if (!pubConfig.smmBoxToken) {
        setPubStatus({success: false, msg: 'Токен SmmBox не найден в настройках!'});
        return;
    }

    setPublishing(true);
    setPubStatus({msg: 'Отправка в SmmBox...'});

    const textToSend = editableText.trim();
    const imagesToSend = (activeView === 'long' && digest.collageImage) ? [digest.collageImage] : [];
    const dateObj = scheduleDate ? new Date(scheduleDate) : undefined;

    try {
      const res = await publishToSmmBox(pubConfig, textToSend, imagesToSend, dateObj);
      if (res.success) {
        setPubStatus({success: true, msg: 'Успешно запланировано!'});
      } else {
        throw new Error(res.error?.message || 'Ошибка API');
      }
    } catch (e: any) {
      setPubStatus({success: false, msg: e.message});
    } finally {
      setPublishing(false);
    }
  };

  return (
    <div className="bg-white rounded-[2.5rem] shadow-2xl overflow-hidden border border-slate-200 h-full flex flex-col min-h-[750px] animate-fade-in">
      <div className="bg-slate-50 border-b p-5 flex justify-between items-center">
        <div className="flex gap-2">
            <button 
              onClick={() => setActiveView('long')} 
              className={`text-[10px] px-6 py-2.5 rounded-xl font-black uppercase transition-all ${activeView === 'long' ? 'bg-brand-orange text-white' : 'bg-white text-slate-400 border border-slate-100 hover:bg-slate-50'}`}
            >
              Дайджест
            </button>
            <button 
              onClick={() => setActiveView('short')} 
              className={`text-[10px] px-6 py-2.5 rounded-xl font-black uppercase transition-all ${activeView === 'short' ? 'bg-brand-orange text-white' : 'bg-white text-slate-400 border border-slate-100 hover:bg-slate-50'}`}
            >
              Бег. строка
            </button>
        </div>
      </div>

      <div className="p-0 overflow-y-auto custom-scrollbar flex-1 flex flex-col bg-white">
        {activeView === 'long' && digest.collageImage && (
            <div className="h-40 w-full bg-slate-900 shrink-0">
                <img src={digest.collageImage} className="w-full h-full object-cover opacity-90 shadow-inner" alt="Digest Collage" />
            </div>
        )}

        <div className="p-6 bg-slate-50/80 border-b space-y-4">
           <div className="flex flex-col gap-1.5">
              <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Запланировать в SmmBox</label>
              <input 
                type="datetime-local" 
                value={scheduleDate} 
                onChange={(e) => setScheduleDate(e.target.value)} 
                className="w-full text-xs p-3.5 rounded-xl border border-slate-200 outline-none bg-white font-bold" 
              />
           </div>

           <button 
             onClick={handlePublish} 
             disabled={publishing} 
             className="w-full bg-brand-dark text-white text-[11px] font-black py-4.5 rounded-2xl uppercase tracking-widest hover:bg-brand-orange transition-all disabled:opacity-50 shadow-xl active:scale-95"
           >
             {publishing ? 'В ПРОЦЕССЕ...' : 'ОПУБЛИКОВАТЬ ВЫПУСК'}
           </button>

           {pubStatus.msg && (
               <div className={`p-4 rounded-xl text-[10px] text-center font-black uppercase border-2 ${pubStatus.success === false ? 'bg-red-50 text-red-500 border-red-100' : 'bg-green-50 text-green-600 border-green-100'}`}>
                 {pubStatus.msg}
               </div>
           )}
        </div>

        {/* СТРОГО БЕЛЫЙ ФОН И ЧЕРНЫЙ ТЕКСТ. ВСЁ МОЖНО РЕДАКТИРОВАТЬ */}
        <div className="p-8 flex-1 bg-white flex flex-col">
            <label className="text-[9px] font-black text-slate-300 uppercase tracking-widest mb-3">Текст выпуска (редактируемый)</label>
            <textarea 
                value={editableText}
                onChange={(e) => setEditableText(e.target.value)}
                className="w-full flex-1 min-h-[450px] text-lg text-black leading-relaxed font-bold outline-none border-none resize-none custom-scrollbar bg-white"
                placeholder="Текст будет здесь..."
            />
            <div className="mt-4 text-[10px] text-slate-400 font-bold italic">
                * Вы можете редактировать всё, включая ссылки, даты и подпись канала.
            </div>
        </div>
      </div>
    </div>
  );
};

