      const data = await fetchRealNews(12);
      setDigest(data);
      setAppState(AppState.SELECTING);
      if (data.collagePrompt) {
        generateImage(data.collagePrompt).then(img => {
          if (img) setDigest(prev => prev ? ({ ...prev, collageImage: img }) : null);
        });
      }
    } catch (e: any) { setAppState(AppState.IDLE); alert(e.message); }
  };

  const handleToggleSelection = (id: string) => {
    setSelectedNewsIds(prev => {
      if (prev.includes(id)) {
        return prev.filter(i => i !== id);
      } else if (prev.length < MAX_SELECTION) {
        return [...prev, id];
      }
      return prev;
    });
  };

  const handleReplaceNews = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    try {
      const replacement = await fetchRealNews(1);
      const newNews = replacement.news[0];
      if (digest) {
        const updatedNewsList = digest.news.map(n => n.id === id ? newNews : n);
        setDigest({ ...digest, news: updatedNewsList });
        setSelectedNewsIds(prev => prev.filter(i => i !== id));
      }
    } catch (e) { alert("Ошибка замены новости."); }
  };

  // Fixed: Updated signature to include sourceUrl
  const handleAddManualNews = (news: { title: string; summary: string; location: string; sourceUrl: string }) => {
    if (!digest) return;
    const newItem: NewsItem = {
        id: `manual-${Date.now()}`,
        title: news.title,
        summary: news.summary,
        location: news.location,
        ticker: `${news.title}: ${news.summary.slice(0, 50)}...`,
        date: new Date().toLocaleDateString('ru-RU'),
        sourceUrl: news.sourceUrl || 'Вручную'
    };
    setDigest({ ...digest, news: [newItem, ...digest.news] });
  };

  const handleGenerate = async () => {
    if (selectedNewsIds.length === 0) return;

    setAppState(AppState.GENERATING_CONTENT);
    setGeneratedResults([]);

    const itemsToGenerate = digest?.news.filter(n => selectedNewsIds.includes(n.id)) || [];

    for (let i = 0; i < itemsToGenerate.length; i++) {
      const currentNews = itemsToGenerate[i];
      setStatusMessage(`[${i+1}/${itemsToGenerate.length}] Создаем статью: ${currentNews.title}...`);

      try {
        const pack = await generateArticleLongread(currentNews);
        setStatusMessage(`[${i+1}/${itemsToGenerate.length}] Рисуем иллюстрации...`);
        const imgs = await generateImagesForArticle(pack.imagePrompts);
        setGeneratedResults(prev => [...prev, { ...pack, newsId: currentNews.id, generatedImages: imgs }]);
      } catch (e) { 
        console.error(e);
      }
    }
    setAppState(AppState.COMPLETED);
  };

  return (
    <div className="min-h-screen bg-[#f1f3f5] pb-20">
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} config={pubConfig} onSave={setPubConfig} />
      <AddNewsModal isOpen={isAddNewsOpen} onClose={() => setIsAddNewsOpen(false)} onAdd={handleAddManualNews} />

      <nav className="bg-white h-20 flex items-center px-8 border-b sticky top-0 z-50 shadow-md">
        <div className="flex flex-col">
          <h1 className="text-brand-dark font-black tracking-tighter text-3xl italic leading-none">TOUR<span className="text-brand-orange">GENIUS</span></h1>
          <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest italic">Первый Туристический Телеканал</span>
        </div>
        <div className="ml-auto flex items-center gap-4">
           {appState === AppState.SELECTING && (
               <button onClick={() => setIsAddNewsOpen(true)} className="bg-slate-100 hover:bg-slate-200 px-5 py-2.5 rounded-xl text-[10px] font-black uppercase">➕ Своя тема</button>
           )}
           <button onClick={() => setIsSettingsOpen(true)} className="w-12 h-12 bg-slate-50 flex items-center justify-center rounded-xl border transition-all text-lg hover:shadow-md">⚙️</button>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto p-6">
        {appState === AppState.IDLE && (
          <div className="bg-white rounded-[4rem] p-24 shadow-2xl border border-slate-100 text-center mt-12 animate-fade-in">
            <h2 className="text-6xl font-black text-brand-dark mb-8 uppercase italic leading-tight">Контент-центр <br/><span className="text-brand-orange">Телеканала</span></h2>
            <p className="text-slate-400 text-xl mb-12 max-w-2xl mx-auto font-medium italic">Автоматизация сбора свежих новостей и создание уникальных лонгридов в фирменном стиле Первого Туристического.</p>
            <button onClick={handleFetchNews} className="bg-brand-dark text-white px-20 py-7 rounded-3xl font-black uppercase tracking-widest hover:bg-brand-orange transition-all shadow-2xl shadow-orange-100 transform hover:scale-105 active:scale-95">Начать работу</button>
          </div>
        )}

        {appState === AppState.SEARCHING && (
          <div className="flex flex-col items-center py-48">
             <div className="w-20 h-20 border-8 border-brand-orange border-t-transparent rounded-full animate-spin mb-10"></div>
             <h3 className="text-3xl font-black text-brand-dark uppercase italic animate-pulse">{statusMessage}</h3>
          </div>
        )}

        {appState === AppState.SELECTING && digest && (
          <div className="space-y-12 animate-fade-in">
            <div className="flex justify-between items-center bg-white p-10 rounded-[2.5rem] border shadow-2xl sticky top-24 z-40">
               <div>
                  <h2 className="text-3xl font-black text-brand-dark uppercase italic">Выбор тем на сегодня</h2>
                  <p className="text-[11px] font-black text-brand-orange uppercase tracking-widest mt-2">Отметьте {MAX_SELECTION} новости для написания лонгридов</p>
               </div>
               <button 
                 onClick={handleGenerate} 
                 disabled={selectedNewsIds.length === 0} 
                 className={`px-14 py-5 rounded-2xl font-black uppercase text-sm shadow-2xl transition-all ${selectedNewsIds.length > 0 ? 'bg-brand-orange text-white' : 'bg-slate-100 text-slate-300 cursor-not-allowed shadow-none'}`}
               >
                 Создать статьи ({selectedNewsIds.length})
               </button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
                <div className="lg:col-span-4 h-fit"><DigestPostViewer digest={digest} pubConfig={pubConfig} /></div>
                <div className="lg:col-span-8 grid grid-cols-1 md:grid-cols-2 gap-8 h-fit pb-20">
                   {digest.news.map(n => (
                      <div 
                        key={n.id} 
                        onClick={() => handleToggleSelection(n.id)}
                        className={`group p-8 rounded-[2.5rem] border-4 transition-all bg-white flex flex-col cursor-pointer h-full relative ${selectedNewsIds.includes(n.id) ? 'border-brand-orange shadow-2xl scale-[1.02]' : 'border-white hover:border-brand-orange/20 shadow-xl'}`}
                      >
                         <div className="flex justify-between mb-5 items-center">
                            <div className="flex gap-2">
                                <span className="text-[10px] font-black uppercase bg-slate-50 px-3 py-1.5 rounded-lg text-slate-500 border">{n.location || 'АКТУАЛЬНО'}</span>
                                <span className="text-[10px] font-black uppercase bg-blue-50 px-3 py-1.5 rounded-lg text-blue-500 border">{n.date || '48ч'}</span>
                            </div>
                            <button 
                                onClick={(e) => handleReplaceNews(e, n.id)} 
                                className="text-[10px] font-black text-brand-orange hover:bg-orange-50 px-3 py-1.5 rounded-lg border border-brand-orange/20 uppercase transition-all opacity-0 group-hover:opacity-100"
                            >
                                Заменить 🔄
                            </button>
                         </div>
                         <div className="flex-1">
                            <h4 className={`font-black text-xl mb-3 leading-tight transition-colors ${selectedNewsIds.includes(n.id) ? 'text-brand-orange' : 'text-brand-dark'}`}>
                                {n.title}
                            </h4>
                            <p className="text-slate-500 text-sm leading-relaxed line-clamp-6">{n.summary}</p>
                            {n.sourceUrl && n.sourceUrl !== 'Вручную' && (
                                <p className="text-[9px] text-slate-300 mt-2 truncate max-w-full italic">{n.sourceUrl}</p>
                            )}
                         </div>
                         <div className="mt-8 flex items-center justify-between pt-6 border-t border-slate-50">
                             <div className="flex items-center gap-3">
                                <div className={`w-7 h-7 rounded-xl border-4 flex items-center justify-center transition-all ${selectedNewsIds.includes(n.id) ? 'bg-brand-orange border-brand-orange' : 'border-slate-100'}`}>
                                    {selectedNewsIds.includes(n.id) && <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>}
                                </div>
                                <span className={`text-[11px] font-black uppercase tracking-widest ${selectedNewsIds.includes(n.id) ? 'text-brand-orange' : 'text-slate-300'}`}>
                                    {selectedNewsIds.includes(n.id) ? 'Выбрано' : 'Выбрать'}
                                </span>
                             </div>
                         </div>
                      </div>
                   ))}
                </div>
            </div>
          </div>
        )}

        {(appState === AppState.GENERATING_CONTENT || appState === AppState.COMPLETED) && (
          <div className="space-y-12 animate-fade-in">
             <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
                <div className="lg:col-span-4 sticky top-24 h-fit"><DigestPostViewer digest={digest!} pubConfig={pubConfig} /></div>
                <div className="lg:col-span-8 space-y-12">
                   {appState === AppState.GENERATING_CONTENT && (
                       <div className="bg-white p-10 rounded-[2.5rem] shadow-xl border-2 border-brand-orange border-dashed text-center">
                           <div className="w-12 h-12 border-4 border-brand-orange border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
                           <p className="font-black uppercase text-brand-dark text-lg italic">{statusMessage}</p>
                       </div>
                   )}
                   {generatedResults.map(res => <ResultViewer key={res.newsId} pack={res} pubConfig={pubConfig} />)}
                </div>
             </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { DigestData, GeneratedContentPack, NewsItem } from "../types";

// Always use process.env.API_KEY directly as a named parameter
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getCurrentDate = () => {
  return new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' });
};

/**
 * Поиск новостей с ссылками и датами
 */
export const fetchRealNews = async (count: number = 10): Promise<DigestData> => {
  const model = "gemini-3-flash-preview"; 
  const today = getCurrentDate();

  const systemInstruction = `
    ТЫ — ВЕДУЩИЙ РЕДАКТОР "ПЕРВОГО ТУРИСТИЧЕСКОГО ТЕЛЕКАНАЛА". 
    ТЕКУЩАЯ ДАТА: ${today}.
    ЗАДАЧА: Собрать ${count} самых свежих новостей туризма за ПОСЛЕДНИЕ 48 ЧАСОВ.

    ЖЕСТКИЕ ПРАВИЛА:
    1. ИСТОЧНИКИ: Только реальные СМИ (ТАСС, РИА, Интерфакс, региональные порталы).
    2. ДАТА И ССЫЛКА: Для каждой новости ОБЯЗАТЕЛЬНО найди дату публикации и URL-ссылку на первоисточник.
    3. ФОРМАТ ДАЙДЖЕСТА: Каждая новость с новой строки. Формат:
       [Эмодзи] Заголовок новости.
       (Дата: [Дата] | Источник: [Ссылка])
    4. БЕГУЩАЯ СТРОКА: "Заголовок: Развернутая расшифровка сути новости".
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Собери новости туризма на ${today}. Укажи реальные ссылки и даты публикации.`,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            news: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  summary: { type: Type.STRING },
                  location: { type: Type.STRING },
                  ticker: { type: Type.STRING },
                  date: { type: Type.STRING },
                  sourceUrl: { type: Type.STRING }
                },
                required: ["title", "summary", "ticker", "sourceUrl"]
              }
            },
            formattedDigestText: { type: Type.STRING },
            formattedShortDigest: { type: Type.STRING },
            collagePrompt: { type: Type.STRING }
          },
          required: ["news", "formattedDigestText", "formattedShortDigest", "collagePrompt"]
        }
      }
    });

    // Directly access .text property
    const data = JSON.parse(response.text || "{}");
    data.news = data.news.map((n: any, i: number) => ({
      ...n, 
      id: `news-${Date.now()}-${i}`
    }));
    return data;
  } catch (error) {
    console.error("News Fetch Error:", error);
    throw new Error("Ошибка при поиске новостей. Попробуйте еще раз.");
  }
};

/**
 * Генерация лонгрида от Первого Туристического
 */
export const generateArticleLongread = async (newsItem: NewsItem): Promise<Omit<GeneratedContentPack, 'generatedImages'>> => {
  const model = "gemini-3-pro-preview";

  const systemInstruction = `
    ТЫ — ГЛАВНЫЙ АВТОР "ПЕРВОГО ТУРИСТИЧЕСКОГО ТЕЛЕКАНАЛА".
    СТИЛЬ: Михаил Жванецкий (ирония, парадокс, глубокий смысл).
    ТЕМА: ${newsItem.title}.

    ТРЕБОВАНИЯ:
    1. ПЕРСОНА: Мы — телеканал. Никакого "я", только "мы" или официальный тон канала с юмором.
    2. ОБЪЕМ: 3000 знаков.
    3. ХЕШТЕГИ: Строго БЕЗ символа #, через запятую (например: отдых, туризм, сочи).
    4. СОЦСЕТИ: Сделай ироничный пост.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Напиши статью: ${newsItem.title}. Стиль: Первый Туристический + Жванецкий. Хештеги через запятую без #.`,
      config: { 
        systemInstruction, 
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            siteArticle: {
              type: Type.OBJECT,
              properties: {
                headline: { type: Type.STRING },
                sections: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: {
                      heading: { type: Type.STRING },
                      body: { type: Type.STRING }
                    },
                    required: ["heading", "body"]
                  }
                },
                hashtags: { type: Type.STRING }
              },
              required: ["headline", "sections", "hashtags"]
            },
            socials: {
              type: Type.OBJECT,
              properties: {
                tg: { type: Type.STRING },
                vk_ok: { type: Type.STRING }
              },
              required: ["tg", "vk_ok"]
            },
            imagePrompts: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            },
            metaDescription: { type: Type.STRING }
          },
          required: ["siteArticle", "socials", "imagePrompts", "metaDescription"]
        }
      }
    });
    // Directly access .text property
    return JSON.parse(response.text || "{}");
  } catch (error) {
    throw new Error("Ошибка генерации статьи.");
  }
};

export const generateImage = async (prompt: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: prompt }] },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    // Iterate through parts to find the image part as per guidelines
    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    return part ? `data:image/png;base64,${part.inlineData.data}` : "";
  } catch { return ""; }
};

export const generateImagesForArticle = async (prompts: string[]): Promise<string[]> => {
  const images: string[] = [];
  for (const p of prompts.slice(0, 3)) {
    const img = await generateImage(p);
    if (img) images.push(img);
    await new Promise(r => setTimeout(r, 600)); 
  }
  return images;
};

import React, { useState, useEffect } from 'react';
import { GeneratedContentPack, PublishingConfig, ArticleSection } from '../types';
import { publishToSmmBox, publishToWordPress } from '../services/publishingService';

interface ResultViewerProps {
  pack: GeneratedContentPack;
  pubConfig: PublishingConfig;
}

export const ResultViewer: React.FC<ResultViewerProps> = ({ pack, pubConfig }) => {
  const [activeTab, setActiveTab] = useState<'site' | 'tg' | 'vk_ok' | 'prompts'>('site');
  const [isEditing, setIsEditing] = useState(false);

  const [headline, setHeadline] = useState(pack.siteArticle?.headline || '');
  const [sections, setSections] = useState<ArticleSection[]>(pack.siteArticle?.sections || []);
  const [hashtags, setHashtags] = useState(pack.siteArticle?.hashtags || '');
  const [tgText, setTgText] = useState(pack.socials?.tg || '');
  const [vkOkText, setVkOkText] = useState(pack.socials?.vk_ok || '');
  const [metaDesc, setMetaDesc] = useState(pack.metaDescription || '');

  // Новое состояние для редактируемой подписи
  const [socialSignature, setSocialSignature] = useState(
    `\n\n🟠 Информационный вечер Первого туристического\n📆 Каждый день с 17:00 до 20:00 — факты, новости и истории о путешествиях.\n\n➡️ Далее в 20:00 - `
  );

  const [publishing, setPublishing] = useState<boolean>(false);
  const [pubStatus, setPubStatus] = useState<{ success?: boolean; msg?: string }>({});
  const [scheduleDate, setScheduleDate] = useState<string>('');

  useEffect(() => {
    setHeadline(pack.siteArticle?.headline || '');
    setSections(pack.siteArticle?.sections || []);
    setHashtags(pack.siteArticle?.hashtags || '');
    setTgText(pack.socials?.tg || '');
    setVkOkText(pack.socials?.vk_ok || '');
    setMetaDesc(pack.metaDescription || '');
  }, [pack]);

  const handleSmmPublish = async (baseText: string) => {
    setPublishing(true);
    setPubStatus({ msg: 'Подготовка поста для SmmBox...' });
    try {
      const dateObj = scheduleDate ? new Date(scheduleDate) : undefined;
      // Используем РЕДАКТИРУЕМУЮ подпись
      const finalMsg = baseText.trim() + socialSignature;
      const res = await publishToSmmBox(pubConfig, finalMsg, pack.generatedImages, dateObj);
      if (res.success) {
        setPubStatus({ success: true, msg: 'Статья запланирована в SmmBox!' });
      } else {
        throw new Error(res.error?.message || "Ошибка API");
      }
    } catch (e: any) {
      setPubStatus({ success: false, msg: e.message });
    } finally { setPublishing(false); }
  };

  const handleWPPublish = async () => {
    setPublishing(true);
    setPubStatus({ msg: 'Загрузка статьи в WordPress...' });
    try {
      await publishToWordPress(
        pubConfig.wordPress, 
        pubConfig.useProxy, 
        headline, 
        sections, 
        pack.generatedImages, 
        hashtags, 
        metaDesc, 
        scheduleDate,
        (msg) => setPubStatus({ msg })
      );
      setPubStatus({ success: true, msg: 'Статья опубликована на сайте!' });
    } catch (e: any) {
      setPubStatus({ success: false, msg: e.message });
    } finally { setPublishing(false); }
  };

  return (
    <div className="bg-white rounded-[2rem] shadow-2xl overflow-hidden border border-slate-100 flex flex-col h-full animate-fade-in mb-10">
      <div className="bg-brand-dark border-b border-white/5 p-4 flex justify-between items-center">
        <div className="flex gap-2">
          {['site', 'tg', 'vk_ok', 'prompts'].map((t) => (
            <button key={t} onClick={() => setActiveTab(t as any)} className={`px-4 py-2 text-[10px] font-black rounded-xl uppercase transition-all ${activeTab === t ? 'bg-brand-orange text-white' : 'bg-slate-800 text-slate-400'}`}>
              {t === 'site' ? 'Сайт (WP)' : t === 'tg' ? 'Telegram' : t === 'vk_ok' ? 'VK/OK' : 'Промпты'}
            </button>
          ))}
        </div>
        <button onClick={() => setIsEditing(!isEditing)} className="px-5 py-2 text-[10px] font-black rounded-xl uppercase border border-white/20 text-white hover:bg-white/10">
          {isEditing ? 'СОХРАНИТЬ' : 'РЕДАКТИРОВАТЬ'}
        </button>
      </div>

      <div className="p-8 overflow-y-auto flex-1 custom-scrollbar">
        {pubStatus.msg && (
            <div className={`mb-6 p-4 rounded-xl text-xs font-bold text-center border animate-pulse ${pubStatus.success === true ? 'bg-green-50 text-green-700 border-green-100' : pubStatus.success === false ? 'bg-red-50 text-red-700 border-red-100' : 'bg-blue-50 text-blue-700 border-blue-100'}`}>
                {pubStatus.msg}
            </div>
        )}

        <div className="mb-8 flex flex-wrap items-center gap-4 bg-slate-50 p-5 rounded-3xl border border-slate-200">
            <div className="flex-1 min-w-[200px]">
                <label className="block text-[9px] font-black text-slate-400 uppercase mb-2 ml-1">Дата и время публикации</label>
                <input type="datetime-local" value={scheduleDate} onChange={e => setScheduleDate(e.target.value)} className="w-full text-xs p-3 rounded-xl border border-slate-200 outline-none bg-white font-bold" />
            </div>
            <button 
                onClick={() => activeTab === 'site' ? handleWPPublish() : handleSmmPublish(activeTab === 'tg' ? tgText : vkOkText)} 
                disabled={publishing}
                className="bg-brand-orange text-white px-10 py-4 rounded-xl font-black uppercase text-[10px] shadow-lg hover:scale-105 transition-all disabled:opacity-50"
            >
                {publishing ? 'В ПРОЦЕССЕ...' : 'ОПУБЛИКОВАТЬ'}
            </button>
        </div>

        {activeTab === 'site' && (
          <div className="article-font max-w-none">
            {isEditing ? (
              <div className="space-y-6">
                <div>
                  <label className="text-[9px] font-black text-slate-400 uppercase mb-1 block">Заголовок</label>
                  <input value={headline} onChange={e => setHeadline(e.target.value)} className="w-full text-2xl font-black border-b border-slate-300 p-2 outline-none focus:border-brand-orange bg-white text-black" />
                </div>
                <div className="bg-orange-50 p-5 rounded-2xl border border-orange-100">
                    <label className="text-[9px] font-black text-brand-orange uppercase block mb-1">SEO Мета-описание (Excerpt)</label>
                    <textarea value={metaDesc} onChange={e => setMetaDesc(e.target.value)} className="w-full h-20 p-3 text-sm border rounded-xl mt-1 focus:ring-2 focus:ring-brand-orange outline-none bg-white text-black" />
                </div>
                {sections.map((s, i) => (
                  <div key={i} className="space-y-3 p-5 bg-slate-50 rounded-2xl border border-slate-200">
                    <input value={s.heading} onChange={e => {
                      const n = [...sections]; n[i].heading = e.target.value; setSections(n);
