// Always use process.env.API_KEY directly as a named parameter
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getCurrentDate = () => {
  return new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' });
};

/**
 * Поиск новостей с ссылками и датами
 */
export const fetchRealNews = async (count: number = 10): Promise<DigestData> => {
  const model = "gemini-3-flash-preview"; 
  const today = getCurrentDate();

  const systemInstruction = `
    ТЫ — ВЕДУЩИЙ РЕДАКТОР "ПЕРВОГО ТУРИСТИЧЕСКОГО ТЕЛЕКАНАЛА". 
    ТЕКУЩАЯ ДАТА: ${today}.
    ЗАДАЧА: Собрать ${count} самых свежих новостей туризма за ПОСЛЕДНИЕ 48 ЧАСОВ.

    ЖЕСТКИЕ ПРАВИЛА ОФОРМЛЕНИЯ:
    1. ДАЙДЖЕСТ: Каждая новость должна начинаться с ЭМОДЗИ-ЦИФРЫ (1️⃣, 2️⃣, 3️⃣...).
    2. ПОЯСНЕНИЕ: После заголовка новости — строго ОДНО-ДВА предложения пояснения сути.
    3. ССЫЛКА И ДАТА: Под пояснением в скобках (Дата: [Дата] | Источник: [Ссылка]).
    4. БЕГУЩАЯ СТРОКА: Каждая новость начинается с тематического ЭМОДЗИ-КАРТИНКИ. Формат: "[Эмодзи] Заголовок: Краткое пояснение (5-7 слов)".
    5. КОЛЛАЖ: Промпт для картинки должен содержать текст "НОВОСТИ ТУРИЗМА ${today}" и быть в стиле профессиональной фотореалистичной фотографии 8k.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Собери новости туризма на ${today}. Сделай дайджест с нумерацией эмодзи-цифрами. Напиши промпт для фотореалистичного коллажа с надписью "НОВОСТИ ТУРИЗМА ${today}".`,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            news: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  summary: { type: Type.STRING },
                  location: { type: Type.STRING },
                  ticker: { type: Type.STRING },
                  date: { type: Type.STRING },
                  sourceUrl: { type: Type.STRING }
                },
                required: ["title", "summary", "ticker", "sourceUrl"]
              }
            },
            formattedDigestText: { type: Type.STRING },
            formattedShortDigest: { type: Type.STRING },
            collagePrompt: { type: Type.STRING }
          },
          required: ["news", "formattedDigestText", "formattedShortDigest", "collagePrompt"]
        }
      }
    });

    const data = JSON.parse(response.text || "{}");
    data.news = data.news.map((n: any, i: number) => ({
      ...n, 
      id: `news-${Date.now()}-${i}`
    }));
    return data;
  } catch (error) {
    console.error("News Fetch Error:", error);
    throw new Error("Ошибка при поиске новостей. Попробуйте еще раз.");
  }
};

