import React, { useState, useEffect } from 'react';
import { DigestData, PublishingConfig } from '../types';
import { publishToSmmBox } from '../services/publishingService';

interface DigestPostViewerProps {
  digest: DigestData;
  pubConfig: PublishingConfig;
  isGeneratingImage?: boolean;
}

export const DigestPostViewer: React.FC<DigestPostViewerProps> = ({ digest, pubConfig, isGeneratingImage }) => {
  const [activeView, setActiveView] = useState<'long' | 'short'>('long');
  const [editableText, setEditableText] = useState('');
  const [publishing, setPublishing] = useState<boolean>(false);
  const [pubStatus, setPubStatus] = useState<{success?: boolean, msg: string}>({msg: ''});
  const [scheduleDate, setScheduleDate] = useState<string>('');

  const getInitialText = (view: 'long' | 'short') => {
    let text = view === 'long' ? digest.formattedDigestText : digest.formattedShortDigest;
    if (view === 'long') {
      text += `\n\n🟠 Информационный вечер Первого туристического\n📆 Каждый день с 17:00 до 20:00 — факты, новости и истории о путешествиях.\n\n➡️ Далее в 19:00 -\n➡️ Затем в 20:00 -`;
    }
    return text;
  };

  useEffect(() => {
    setEditableText(getInitialText(activeView));
  }, [digest, activeView]);

  const handlePublish = async () => {
    if (!pubConfig.smmBoxToken) {
        setPubStatus({success: false, msg: 'Токен SmmBox не найден!'});
        return;
    }
    setPublishing(true);
    setPubStatus({msg: 'Отправка...'});
    try {
      const res = await publishToSmmBox(pubConfig, editableText.trim(), digest.collageImage ? [digest.collageImage] : [], scheduleDate ? new Date(scheduleDate) : undefined);
      setPubStatus({success: true, msg: 'Успешно!'});
    } catch (e: any) {
      setPubStatus({success: false, msg: e.message});
    } finally { setPublishing(false); }
  };

  return (
    <div className="bg-white rounded-[2.5rem] shadow-2xl overflow-hidden border border-slate-200 flex flex-col min-h-[750px] animate-fade-in">
      <div className="bg-slate-50 border-b p-5 flex justify-between items-center">
        <div className="flex gap-2">
            <button onClick={() => setActiveView('long')} className={`text-[10px] px-6 py-2.5 rounded-xl font-black uppercase ${activeView === 'long' ? 'bg-brand-orange text-white shadow-md' : 'bg-white text-slate-400'}`}>Дайджест</button>
            <button onClick={() => setActiveView('short')} className={`text-[10px] px-6 py-2.5 rounded-xl font-black uppercase ${activeView === 'short' ? 'bg-brand-orange text-white shadow-md' : 'bg-white text-slate-400'}`}>Бег. строка</button>
        </div>
      </div>

      <div className="flex-1 flex flex-col bg-white">
        <div className="h-48 w-full bg-slate-100 shrink-0 relative overflow-hidden">
            {isGeneratingImage ? (
                <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-900 text-white gap-3">
                    <div className="w-8 h-8 border-4 border-brand-orange border-t-transparent rounded-full animate-spin"></div>
                    <span className="text-[10px] font-black uppercase tracking-widest animate-pulse">Рисуем фото-обложку...</span>
                </div>
            ) : digest.collageImage ? (
                <img src={digest.collageImage} className="w-full h-full object-cover" alt="Collage" />
            ) : (
                <div className="absolute inset-0 flex items-center justify-center text-slate-300 font-black uppercase text-[10px]">Фото не готово</div>
            )}
        </div>

        <div className="p-6 bg-slate-50 border-b space-y-4">
           <input type="datetime-local" value={scheduleDate} onChange={e => setScheduleDate(e.target.value)} className="w-full text-xs p-3.5 rounded-xl border border-slate-200 outline-none bg-white font-black" />
           <button onClick={handlePublish} disabled={publishing} className="w-full bg-brand-dark text-white text-[11px] font-black py-4.5 rounded-2xl uppercase tracking-widest hover:bg-brand-orange transition-all disabled:opacity-50">{publishing ? 'ЖДИТЕ...' : 'ОПУБЛИКОВАТЬ'}</button>
           {pubStatus.msg && <div className={`p-3 rounded-xl text-[10px] text-center font-black border ${pubStatus.success === false ? 'bg-red-50 text-red-500' : 'bg-green-50 text-green-600'}`}>{pubStatus.msg}</div>}
        </div>

        <div className="p-8 flex-1 bg-white flex flex-col">
            <textarea value={editableText} onChange={e => setEditableText(e.target.value)} className="w-full flex-1 text-lg text-black leading-relaxed font-bold outline-none border-none resize-none custom-scrollbar" />
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI, Type } from "@google/genai";
import { DigestData, GeneratedContentPack, NewsItem } from "../types";

// Инициализация API согласно правилам
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getCurrentDate = () => {
  return new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' });
};

/**
 * Поиск новостей с формированием промпта для фотореалистичного коллажа
 */
export const fetchRealNews = async (count: number = 10): Promise<DigestData> => {
  const model = "gemini-3-flash-preview"; 
  const today = getCurrentDate();

  const systemInstruction = `
    ТЫ — ВЕДУЩИЙ РЕДАКТОР "ПЕРВОГО ТУРИСТИЧЕСКОГО ТЕЛЕКАНАЛА". 
    ТЕКУЩАЯ ДАТА: ${today}.

    ЗАДАЧА: Собрать ${count} самых свежих новостей туризма за последние 48 часов.

    ЖЕСТКИЕ ПРАВИЛА ОФОРМЛЕНИЯ ДАЙДЖЕСТА (formattedDigestText):
    1. НУМЕРАЦИЯ: Каждая новость ДОЛЖНА начинаться с ЭМОДЗИ-ЦИФРЫ (1️⃣, 2️⃣, 3️⃣, 4️⃣, 5️⃣, 6️⃣...).
    2. ФОРМАТ: [Эмодзи-цифра] Заголовок новости.
    3. ПОЯСНЕНИЕ: После заголовка — строго 1-2 предложения сути (не больше!).
    4. ИСТОЧНИК: В скобках под новостью (Источник: [URL]).

    ЖЕСТКИЕ ПРАВИЛА БЕГУЩЕЙ СТРОКИ (formattedShortDigest):
    - Каждая новость начинается с тематического ЭМОДЗИ-КАРТИНКИ (например, ✈️, 🏨, 🏝️).
    - Формат: "[Эмодзи] Заголовок: Краткое пояснение до 10 слов".

    ТРЕБОВАНИЕ К КОЛЛАЖУ (collagePrompt):
    - Создай промпт для ФОТОГРАФИИ (СТРОГО НЕ РИСУНОК).
    - На фото ОБЯЗАТЕЛЬНО должна быть четкая надпись: "НОВОСТИ ТУРИЗМА ${today}".
    - Описание: Широкоугольный снимок аэропорта, курорта или достопримечательности, стиль National Geographic, 8k, фотореализм, профессиональный свет.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Собери новости на ${today}. Сделай дайджест с нумерацией 1️⃣, 2️⃣... и составь промпт для фото-коллажа с текстом "НОВОСТИ ТУРИЗМА ${today}".`,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            news: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  summary: { type: Type.STRING },
                  ticker: { type: Type.STRING },
                  date: { type: Type.STRING },
                  sourceUrl: { type: Type.STRING }
                },
                required: ["title", "summary", "ticker", "sourceUrl"]
              }
            },
            formattedDigestText: { type: Type.STRING },
            formattedShortDigest: { type: Type.STRING },
            collagePrompt: { type: Type.STRING }
          },
          required: ["news", "formattedDigestText", "formattedShortDigest", "collagePrompt"]
        }
      }
    });

    const data = JSON.parse(response.text || "{}");
    data.news = data.news.map((n: any, i: number) => ({
      ...n, 
      id: `news-${Date.now()}-${i}`
    }));
    return data;
  } catch (error) {
    console.error("News Fetch Error:", error);
    throw new Error("Ошибка при поиске новостей.");
  }
};

/**
 * Генерация фотореалистичного изображения
 */
export const generateImage = async (prompt: string): Promise<string> => {
  try {
    // Усиливаем промпт для исключения карикатур и рисунков
    const photographyKeywords = "Photorealistic high-resolution photography, shot on full-frame camera, 8k, highly detailed, realistic textures, cinematic lighting, no digital art, no drawing, no cartoon, no painting, no illustration. Professional travel photography style.";
    const finalPrompt = `${prompt}. ${photographyKeywords}`;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: finalPrompt }] },
      config: { 
        imageConfig: { aspectRatio: "16:9" } 
      }
    });

    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (part?.inlineData?.data) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
    return "";
  } catch (error) {
    console.error("Image Generation Error:", error);
    return "";
  }
};

export const generateArticleLongread = async (newsItem: NewsItem): Promise<Omit<GeneratedContentPack, 'generatedImages'>> => {
  const model = "gemini-3-pro-preview";
  const systemInstruction = `ТЫ — РЕДАКТОР-ЖВАНЕЦКИЙ. Пиши статью 3000 зн. Промпты для фото (imagePrompts) должны быть СТРОГО описаниями РЕАЛЬНЫХ ФОТОГРАФИЙ (National Geographic style). Никаких рисунков.`;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Напиши статью и промпты для ФОТО по теме: ${newsItem.title}`,
      config: { 
        systemInstruction, 
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            siteArticle: {
              type: Type.OBJECT,
              properties: {
                headline: { type: Type.STRING },
                sections: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: { heading: { type: Type.STRING }, body: { type: Type.STRING } },
                    required: ["heading", "body"]
                  }
                },
                hashtags: { type: Type.STRING }
              }
            },
            socials: {
              type: Type.OBJECT,
              properties: { tg: { type: Type.STRING }, vk_ok: { type: Type.STRING } }
            },
            imagePrompts: { type: Type.ARRAY, items: { type: Type.STRING } },
            metaDescription: { type: Type.STRING }
          }
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (error) {
    throw new Error("Ошибка генерации лонгрида.");
  }
};

export const generateImagesForArticle = async (prompts: string[]): Promise<string[]> => {
  const images: string[] = [];
  for (const p of prompts.slice(0, 3)) {
    const img = await generateImage(p);
    if (img) images.push(img);
    await new Promise(r => setTimeout(r, 1000)); 
  }
  return images;
};

