import { GoogleGenAI, Type } from "@google/genai";
import { DigestData, GeneratedContentPack, NewsItem } from "../types";

// Инициализация API согласно правилам
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getCurrentDate = () => {
  return new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' });
};

/**
 * Поиск новостей с формированием промпта для фотореалистичного коллажа
 */
export const fetchRealNews = async (count: number = 10): Promise<DigestData> => {
  const model = "gemini-3-flash-preview"; 
  const today = getCurrentDate();

  const systemInstruction = `
    ТЫ — ВЕДУЩИЙ РЕДАКТОР "ПЕРВОГО ТУРИСТИЧЕСКОГО ТЕЛЕКАНАЛА". 
    ТЕКУЩАЯ ДАТА: ${today}.

    ЗАДАЧА: Собрать ${count} самых свежих новостей туризма за последние 48 часов.

    ЖЕСТКИЕ ПРАВИЛА ОФОРМЛЕНИЯ ДАЙДЖЕСТА (formattedDigestText):
    1. НУМЕРАЦИЯ: Каждая новость ДОЛЖНА начинаться с ЭМОДЗИ-ЦИФРЫ (1️⃣, 2️⃣, 3️⃣, 4️⃣...).
    2. ФОРМАТ: "1️⃣ Заголовок новости".
    3. ПОЯСНЕНИЕ: Сразу после заголовка — строго 1-2 предложения сути.
    4. ИСТОЧНИК: В скобках под новостью (Источник: [URL]).

    ЖЕСТКИЕ ПРАВИЛА БЕГУЩЕЙ СТРОКИ (formattedShortDigest):
    - Каждая новость начинается с тематического ЭМОДЗИ-КАРТИНКИ (например, ✈️, 🌴, 🏨).
    - Формат: "[Эмодзи] Заголовок: Краткое пояснение до 7-10 слов".

    ТРЕБОВАНИЕ К КОЛЛАЖУ (collagePrompt):
    - Создай промпт для ФОТОГРАФИИ (СТРОГО НЕ РИСУНОК).
    - На фото ДОЛЖНА БЫТЬ надпись: "НОВОСТИ ТУРИЗМА ${today}".
    - Стиль: Широкоугольный кадр, профессиональная тревел-фотография, 8k, фотореализм.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Собери новости на ${today}. Нумерация 1️⃣, 2️⃣... Пояснения по 1-2 предложения. Промпт для фото-коллажа с надписью "НОВОСТИ ТУРИЗМА ${today}".`,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            news: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  summary: { type: Type.STRING },
                  ticker: { type: Type.STRING },
                  date: { type: Type.STRING },
                  sourceUrl: { type: Type.STRING }
                },
                required: ["title", "summary", "ticker", "sourceUrl"]
              }
            },
            formattedDigestText: { type: Type.STRING },
            formattedShortDigest: { type: Type.STRING },
            collagePrompt: { type: Type.STRING }
          },
          required: ["news", "formattedDigestText", "formattedShortDigest", "collagePrompt"]
        }
      }
    });

    const data = JSON.parse(response.text || "{}");
    data.news = data.news.map((n: any, i: number) => ({
      ...n, 
      id: `news-${Date.now()}-${i}`
    }));
    return data;
  } catch (error: any) {
    console.error("News Fetch Error:", error);
    throw new Error(`Ошибка поиска: ${error.message}`);
  }
};

/**
 * Генерация фотореалистичного изображения с возвратом причины ошибки
 */
export const generateImageWithFeedback = async (prompt: string): Promise<{ data?: string, error?: string }> => {
  try {
    const photographyKeywords = "Extreme photorealism, shot on 35mm lens, f/1.8, high detail, National Geographic style, professional lighting, NO ILLUSTRATION, NO CARTOON, NO PAINTING, NO DRAWING, 8k resolution, authentic textures.";
    const finalPrompt = `${prompt}. ${photographyKeywords}`;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: finalPrompt }] },
      config: { 
        imageConfig: { aspectRatio: "16:9" } 
      }
    });

    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (part?.inlineData?.data) {
      return { data: `data:image/png;base64,${part.inlineData.data}` };
    }

    // Если картинки нет, проверяем причину (finishReason)
    const reason = response.candidates?.[0]?.finishReason;
    const feedback = reason === 'SAFETY' ? "Блокировка безопасности ИИ" : `Ошибка модели: ${reason || 'неизвестно'}`;
    return { error: feedback };
  } catch (error: any) {
    return { error: `Сбой API: ${error.message}` };
  }
};

// Для обратной совместимости
export const generateImage = async (prompt: string): Promise<string> => {
  const res = await generateImageWithFeedback(prompt);
  return res.data || "";
};

export const generateArticleLongread = async (newsItem: NewsItem): Promise<Omit<GeneratedContentPack, 'generatedImages'>> => {
  const model = "gemini-3-pro-preview";
  const systemInstruction = `ТЫ — РЕДАКТОР-ЖВАНЕЦКИЙ. Пиши статью 3000 зн. Промпты для фото (imagePrompts) должны быть СТРОГО описаниями РЕАЛЬНЫХ ФОТОГРАФИЙ (National Geographic style). Никаких рисунков.`;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Напиши статью и промпты для ФОТО по теме: ${newsItem.title}`,
      config: { 
        systemInstruction, 
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            siteArticle: {
              type: Type.OBJECT,
              properties: {
                headline: { type: Type.STRING },
                sections: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: { heading: { type: Type.STRING }, body: { type: Type.STRING } },
                    required: ["heading", "body"]
                  }
                },
                hashtags: { type: Type.STRING }
              }
            },
            socials: {
              type: Type.OBJECT,
              properties: { tg: { type: Type.STRING }, vk_ok: { type: Type.STRING } }
            },
            imagePrompts: { type: Type.ARRAY, items: { type: Type.STRING } },
            metaDescription: { type: Type.STRING }
          }
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (error) {
    throw new Error("Ошибка генерации лонгрида.");
  }
};

export const generateImagesForArticle = async (prompts: string[]): Promise<string[]> => {
  const images: string[] = [];
  for (const p of prompts.slice(0, 3)) {
    const res = await generateImageWithFeedback(p);
    if (res.data) images.push(res.data);
    await new Promise(r => setTimeout(r, 1000)); 
  }
  return images;
};

