               <button onClick={() => setIsAddNewsOpen(true)} className="bg-slate-100 hover:bg-slate-200 px-5 py-2.5 rounded-xl text-[10px] font-black uppercase">➕ Своя тема</button>
           )}
           <button onClick={() => setIsSettingsOpen(true)} className="w-12 h-12 bg-white flex items-center justify-center rounded-xl border transition-all text-lg hover:shadow-md">⚙️</button>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto p-6">
        {appState === AppState.IDLE && (
          <div className="bg-white rounded-[4rem] p-24 shadow-2xl border border-slate-100 text-center mt-12 animate-fade-in">
            <h2 className="text-6xl font-black text-brand-dark mb-8 uppercase italic leading-tight">Контент-центр <br/><span className="text-brand-orange">Телеканала</span></h2>
            <p className="text-slate-400 text-xl mb-12 max-w-2xl mx-auto font-medium italic">Автоматизация сбора свежих новостей и создание уникальных лонгридов в фирменном стиле.</p>
            <button onClick={handleFetchNews} className="bg-brand-dark text-white px-20 py-7 rounded-3xl font-black uppercase tracking-widest hover:bg-brand-orange transition-all shadow-2xl transform hover:scale-105 active:scale-95">Начать работу</button>
          </div>
        )}

        {appState === AppState.SEARCHING && (
          <div className="flex flex-col items-center py-48">
             <div className="w-20 h-20 border-8 border-brand-orange border-t-transparent rounded-full animate-spin mb-10"></div>
             <h3 className="text-3xl font-black text-brand-dark uppercase italic animate-pulse">{statusMessage}</h3>
          </div>
        )}

        {(appState === AppState.SELECTING || appState === AppState.GENERATING_CONTENT || appState === AppState.COMPLETED) && digest && (
          <div className="space-y-12 animate-fade-in">
            {appState === AppState.SELECTING && (
              <div className="flex justify-between items-center bg-white p-10 rounded-[2.5rem] border shadow-2xl sticky top-24 z-40">
                <div>
                    <h2 className="text-3xl font-black text-brand-dark uppercase italic">Выбор тем на сегодня</h2>
                    <p className="text-[11px] font-black text-brand-orange uppercase tracking-widest mt-2">Отметьте {MAX_SELECTION} новости для статей</p>
                </div>
                <button 
                  onClick={handleGenerate} 
                  disabled={selectedNewsIds.length === 0} 
                  className={`px-14 py-5 rounded-2xl font-black uppercase text-sm shadow-2xl transition-all ${selectedNewsIds.length > 0 ? 'bg-brand-orange text-white' : 'bg-slate-100 text-slate-300 cursor-not-allowed'}`}
                >
                  Создать лонгриды ({selectedNewsIds.length})
                </button>
              </div>
            )}

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
                <div className="lg:col-span-4 h-fit">
                  <DigestPostViewer 
                    digest={digest} 
                    pubConfig={pubConfig} 
                    isGeneratingImage={isCollageGenerating} 
                    imageError={collageError}
                  />
                </div>
                <div className="lg:col-span-8 space-y-10 pb-20">
                   {appState === AppState.SELECTING ? (
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                        {digest.news.map(n => (
                          <div 
                            key={n.id} 
                            onClick={() => handleToggleSelection(n.id)}
                            className={`group p-8 rounded-[2.5rem] border-4 transition-all bg-white flex flex-col cursor-pointer relative ${selectedNewsIds.includes(n.id) ? 'border-brand-orange shadow-2xl scale-[1.02]' : 'border-white shadow-xl'}`}
                          >
                             <div className="flex justify-between mb-5 items-center">
                                <span className="text-[10px] font-black uppercase bg-white px-3 py-1.5 rounded-lg text-slate-500 border">{n.location || 'АКТУАЛЬНО'}</span>
                                {selectedNewsIds.includes(n.id) && <span className="text-brand-orange text-xl">✅</span>}
                             </div>
                             <h4 className={`font-black text-xl mb-3 leading-tight ${selectedNewsIds.includes(n.id) ? 'text-brand-orange' : 'text-brand-dark'}`}>{n.title}</h4>
                             <p className="text-slate-500 text-sm leading-relaxed line-clamp-4">{n.summary}</p>
                          </div>
                        ))}
                      </div>
                   ) : (
                      <>
                        {appState === AppState.GENERATING_CONTENT && (
                           <div className="bg-white p-10 rounded-[2.5rem] shadow-xl border-2 border-brand-orange border-dashed text-center animate-pulse">
                              <p className="font-black uppercase text-brand-dark text-lg">{statusMessage}</p>
                           </div>
                        )}
                        {generatedResults.map(res => <ResultViewer key={res.newsId} pack={res} pubConfig={pubConfig} />)}
                      </>
                   )}
                </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { DigestData, PublishingConfig } from '../types';
import { publishToSmmBox } from '../services/publishingService';

interface DigestPostViewerProps {
  digest: DigestData;
  pubConfig: PublishingConfig;
  isGeneratingImage?: boolean;
  imageError?: string; 
}

export const DigestPostViewer: React.FC<DigestPostViewerProps> = ({ digest, pubConfig, isGeneratingImage, imageError }) => {
  const [activeView, setActiveView] = useState<'long' | 'short'>('long');
  const [editableText, setEditableText] = useState('');
  const [publishing, setPublishing] = useState<boolean>(false);
  const [pubStatus, setPubStatus] = useState<{success?: boolean, msg: string}>({msg: ''});
  const [scheduleDate, setScheduleDate] = useState<string>('');
  const [copied, setCopied] = useState(false);

  const getInitialText = (view: 'long' | 'short') => {
    let text = view === 'long' ? digest.formattedDigestText : digest.formattedShortDigest;
    if (view === 'long') {
      text += `\n\n🟠 Информационный вечер Первого туристического\n📆 Каждый день с 17:00 до 20:00 — факты, новости и истории о путешествиях.\n\n➡️ Далее в 19:00 -\n➡️ Затем в 20:00 -`;
    }
    return text;
  };

  useEffect(() => {
    setEditableText(getInitialText(activeView));
  }, [digest, activeView]);

  const handlePublish = async () => {
    if (!pubConfig.smmBoxToken) {
        setPubStatus({success: false, msg: 'Токен SmmBox не настроен!'});
        return;
    }
    setPublishing(true);
    setPubStatus({msg: 'Отправка...'});
    try {
      const res = await publishToSmmBox(pubConfig, editableText.trim(), digest.collageImage ? [digest.collageImage] : [], scheduleDate ? new Date(scheduleDate) : undefined);
      setPubStatus({success: true, msg: 'Успешно опубликовано!'});
    } catch (e: any) {
      setPubStatus({success: false, msg: e.message});
    } finally { setPublishing(false); }
  };

  const copyPrompt = () => {
    navigator.clipboard.writeText(digest.collagePrompt || '');
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="bg-white rounded-[2.5rem] shadow-2xl overflow-hidden border border-slate-100 flex flex-col min-h-[750px] animate-fade-in">
      <div className="bg-white border-b border-slate-50 p-5 flex justify-between items-center">
        <div className="flex gap-2">
            <button onClick={() => setActiveView('long')} className={`text-[10px] px-6 py-2.5 rounded-xl font-black uppercase transition-all ${activeView === 'long' ? 'bg-brand-orange text-white shadow-md' : 'bg-white text-slate-400 border border-slate-50'}`}>Дайджест</button>
            <button onClick={() => setActiveView('short')} className={`text-[10px] px-6 py-2.5 rounded-xl font-black uppercase transition-all ${activeView === 'short' ? 'bg-brand-orange text-white shadow-md' : 'bg-white text-slate-400 border border-slate-50'}`}>Бег. строка</button>
        </div>
      </div>

      <div className="flex-1 flex flex-col bg-white">
        <div className="h-64 w-full bg-white shrink-0 relative overflow-hidden border-b border-slate-50">
            {isGeneratingImage ? (
                <div className="absolute inset-0 flex flex-col items-center justify-center bg-brand-dark text-white gap-3 p-6 text-center">
                    <div className="w-10 h-10 border-4 border-brand-orange border-t-transparent rounded-full animate-spin"></div>
                    <span className="text-[11px] font-black uppercase tracking-widest animate-pulse">Рисуем фото-обложку...</span>
                </div>
            ) : digest.collageImage ? (
                <img src={digest.collageImage} className="w-full h-full object-cover animate-fade-in" alt="Collage" />
            ) : (
                <div className="absolute inset-0 flex flex-col items-center justify-center p-8 text-center bg-white">
                    <span className="text-[11px] font-black uppercase tracking-widest mb-3 text-slate-300">Изображение не готово</span>
                    {imageError && <p className="text-[9px] font-bold text-red-400 uppercase italic mb-4 max-w-xs">{imageError}</p>}

                    <div className="bg-slate-50 p-4 rounded-xl border border-slate-100 w-full">
                        <label className="block text-[8px] font-black text-slate-400 uppercase mb-2">Промпт для ручной генерации:</label>
                        <p className="text-[10px] text-slate-600 italic line-clamp-2 mb-3">{digest.collagePrompt}</p>
                        <button 
                            onClick={copyPrompt}
                            className="text-[9px] font-black text-brand-orange uppercase border border-brand-orange/20 px-4 py-1.5 rounded-lg hover:bg-brand-orange hover:text-white transition-all"
                        >
                            {copied ? 'СКОПИРОВАНО!' : 'КОПИРОВАТЬ ПРОМПТ'}
                        </button>
                    </div>
                </div>
            )}
        </div>

        <div className="p-6 bg-white border-b border-slate-50 space-y-4">
           <div className="flex flex-col gap-1.5">
              <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Дата и время поста</label>
              <input type="datetime-local" value={scheduleDate} onChange={e => setScheduleDate(e.target.value)} className="w-full text-xs p-3.5 rounded-xl border border-slate-100 outline-none bg-white font-black text-brand-dark focus:ring-2 focus:ring-brand-orange transition-all" />
           </div>

           <button onClick={handlePublish} disabled={publishing} className="w-full bg-brand-dark text-white text-[11px] font-black py-4.5 rounded-2xl uppercase tracking-widest hover:bg-brand-orange transition-all disabled:opacity-50 shadow-xl active:scale-95">
             {publishing ? 'ЖДИТЕ...' : 'ОПУБЛИКОВАТЬ В SMMBOX'}
           </button>

           {pubStatus.msg && <div className={`p-4 rounded-xl text-[10px] text-center font-black border-2 animate-fade-in ${pubStatus.success === false ? 'bg-red-50 text-red-500 border-red-100' : 'bg-green-50 text-green-600 border-green-100'}`}>{pubStatus.msg}</div>}
        </div>

        <div className="p-8 flex-1 bg-white flex flex-col">
            <textarea 
              value={editableText} 
              onChange={e => setEditableText(e.target.value)} 
              className="w-full flex-1 text-lg text-black leading-relaxed font-bold outline-none border-none resize-none custom-scrollbar bg-white" 
              placeholder="Текст появится здесь..."
            />
            <div className="mt-6 pt-4 border-t border-slate-50 flex justify-between items-center text-[10px] text-slate-300 font-black italic uppercase">
              <span>Первый Туристический Телеканал</span>
              <span>{editableText.length} символов</span>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { GeneratedContentPack, PublishingConfig, ArticleSection } from '../types';
import { publishToSmmBox, publishToWordPress } from '../services/publishingService';

interface ResultViewerProps {
  pack: GeneratedContentPack;
  pubConfig: PublishingConfig;
}

export const ResultViewer: React.FC<ResultViewerProps> = ({ pack, pubConfig }) => {
  const [activeTab, setActiveTab] = useState<'site' | 'tg' | 'vk_ok' | 'prompts'>('site');
  const [isEditing, setIsEditing] = useState(false);

  const [headline, setHeadline] = useState(pack.siteArticle?.headline || '');
  const [sections, setSections] = useState<ArticleSection[]>(pack.siteArticle?.sections || []);
  const [hashtags, setHashtags] = useState(pack.siteArticle?.hashtags || '');
  const [tgText, setTgText] = useState(pack.socials?.tg || '');
  const [vkOkText, setVkOkText] = useState(pack.socials?.vk_ok || '');
  const [metaDesc, setMetaDesc] = useState(pack.metaDescription || '');

  const [socialSignature, setSocialSignature] = useState(
    `\n\n🟠 Информационный вечер Первого туристического\n📆 Каждый день с 17:00 до 20:00 — факты, новости и истории о путешествиях.\n\n➡️ Далее в 20:00 - `
  );

  const [publishing, setPublishing] = useState<boolean>(false);
  const [pubStatus, setPubStatus] = useState<{ success?: boolean; msg?: string }>({});
  const [scheduleDate, setScheduleDate] = useState<string>('');
  const [copiedPromptIdx, setCopiedPromptIdx] = useState<number | null>(null);

  useEffect(() => {
    setHeadline(pack.siteArticle?.headline || '');
    setSections(pack.siteArticle?.sections || []);
    setHashtags(pack.siteArticle?.hashtags || '');
    setTgText(pack.socials?.tg || '');
    setVkOkText(pack.socials?.vk_ok || '');
    setMetaDesc(pack.metaDescription || '');
  }, [pack]);

  const handleSmmPublish = async (baseText: string) => {
    setPublishing(true);
    setPubStatus({ msg: 'Подготовка поста для SmmBox...' });
    try {
      const dateObj = scheduleDate ? new Date(scheduleDate) : undefined;
      const finalMsg = baseText.trim() + socialSignature;
      const res = await publishToSmmBox(pubConfig, finalMsg, pack.generatedImages, dateObj);
      if (res.success) {
        setPubStatus({ success: true, msg: 'Статья запланирована в SmmBox!' });
      } else {
        throw new Error(res.error?.message || "Ошибка API");
      }
    } catch (e: any) {
      setPubStatus({ success: false, msg: e.message });
    } finally { setPublishing(false); }
  };

  const handleWPPublish = async () => {
    setPublishing(true);
    setPubStatus({ msg: 'Загрузка статьи в WordPress...' });
    try {
      await publishToWordPress(
        pubConfig.wordPress, 
        pubConfig.useProxy, 
        headline, 
        sections, 
        pack.generatedImages, 
        hashtags, 
        metaDesc, 
        scheduleDate,
        (msg) => setPubStatus({ msg })
      );
      setPubStatus({ success: true, msg: 'Статья опубликована на сайте!' });
    } catch (e: any) {
      setPubStatus({ success: false, msg: e.message });
    } finally { setPublishing(false); }
  };

  const copyPrompt = (text: string, idx: number) => {
    navigator.clipboard.writeText(text);
    setCopiedPromptIdx(idx);
    setTimeout(() => setCopiedPromptIdx(null), 2000);
  };

  return (
    <div className="bg-white rounded-[2rem] shadow-2xl overflow-hidden border border-slate-100 flex flex-col h-full animate-fade-in mb-10">
      <div className="bg-brand-dark border-b border-white/5 p-4 flex justify-between items-center">
        <div className="flex gap-2">
          {['site', 'tg', 'vk_ok', 'prompts'].map((t) => (
            <button key={t} onClick={() => setActiveTab(t as any)} className={`px-4 py-2 text-[10px] font-black rounded-xl uppercase transition-all ${activeTab === t ? 'bg-brand-orange text-white shadow-lg' : 'bg-slate-800 text-slate-400 hover:text-white'}`}>
              {t === 'site' ? 'Сайт (WP)' : t === 'tg' ? 'Telegram' : t === 'vk_ok' ? 'VK/OK' : 'Промпты 📝'}
            </button>
          ))}
        </div>
        <button onClick={() => setIsEditing(!isEditing)} className="px-5 py-2 text-[10px] font-black rounded-xl uppercase border border-white/20 text-white hover:bg-white/10 transition-all">
          {isEditing ? 'СОХРАНИТЬ' : 'РЕДАКТИРОВАТЬ'}
        </button>
      </div>

      <div className="p-8 overflow-y-auto flex-1 custom-scrollbar bg-white">
        {pubStatus.msg && (
            <div className={`mb-6 p-4 rounded-xl text-xs font-black text-center border-2 animate-pulse ${pubStatus.success === true ? 'bg-green-50 text-green-700 border-green-100' : pubStatus.success === false ? 'bg-red-50 text-red-700 border-red-100' : 'bg-blue-50 text-blue-700 border-blue-100'}`}>
                {pubStatus.msg}
            </div>
        )}

        <div className="mb-8 flex flex-wrap items-center gap-4 bg-white p-5 rounded-3xl border border-slate-100 shadow-sm">
            <div className="flex-1 min-w-[200px]">
                <label className="block text-[9px] font-black text-slate-400 uppercase mb-2 ml-1">Запланировать на дату</label>
                <input type="datetime-local" value={scheduleDate} onChange={e => setScheduleDate(e.target.value)} className="w-full text-xs p-3 rounded-xl border border-slate-100 outline-none bg-slate-50 font-bold focus:ring-2 focus:ring-brand-orange transition-all" />
            </div>
            <button 
                onClick={() => activeTab === 'site' ? handleWPPublish() : handleSmmPublish(activeTab === 'tg' ? tgText : vkOkText)} 
                disabled={publishing}
                className="bg-brand-orange text-white px-10 py-4 rounded-xl font-black uppercase text-[10px] shadow-xl hover:scale-105 transition-all disabled:opacity-50"
            >
                {publishing ? 'В ПРОЦЕССЕ...' : 'ОПУБЛИКОВАТЬ'}
            </button>
        </div>

        {activeTab === 'site' && (
          <div className="article-font max-w-none">
            {isEditing ? (
              <div className="space-y-6">
                <div>
                  <label className="text-[9px] font-black text-slate-400 uppercase mb-1 block">Заголовок</label>
                  <input value={headline} onChange={e => setHeadline(e.target.value)} className="w-full text-2xl font-black border-b border-slate-100 p-2 outline-none focus:border-brand-orange bg-white text-black" />
                </div>
                <div className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm">
                    <label className="text-[9px] font-black text-brand-orange uppercase block mb-1">SEO Мета-описание</label>
                    <textarea value={metaDesc} onChange={e => setMetaDesc(e.target.value)} className="w-full h-20 p-3 text-sm border rounded-xl mt-1 focus:ring-2 focus:ring-brand-orange outline-none bg-slate-50 text-black" />
                </div>
                {sections.map((s, i) => (
                  <div key={i} className="space-y-3 p-5 bg-white rounded-2xl border border-slate-100 shadow-sm">
                    <input value={s.heading} onChange={e => {
                      const n = [...sections]; n[i].heading = e.target.value; setSections(n);
                    }} className="w-full font-bold border-b border-slate-100 p-1 text-lg bg-transparent text-black" placeholder="Заголовок блока" />
                    <textarea value={s.body} onChange={e => {
                      const n = [...sections]; n[i].body = e.target.value; setSections(n);
                    }} className="w-full h-48 p-3 border rounded-xl bg-slate-50 text-sm text-black" placeholder="Текст секции..." />
                  </div>
                ))}
              </div>
            ) : (
              <div className="bg-white">
                <h1 className="text-4xl font-black text-brand-dark mb-10 italic leading-tight">{headline}</h1>
                {sections.map((s, i) => (
                  <div key={i} className="mb-12">
                    {s.heading && <h2 className="text-2xl font-bold mb-6 uppercase text-brand-orange italic"><strong>{s.heading}</strong></h2>}
                    <div className="text-lg leading-relaxed text-slate-800 space-y-6">
                        {s.body.split('\n').filter(p => p.trim()).map((para, pIdx) => (
                            <p key={pIdx} style={{ textIndent: '1.5rem' }}>{para.trim()}</p>
                        ))}
                    </div>
                    {pack.generatedImages[i] ? (
                        <img src={pack.generatedImages[i]} className="w-full my-10 rounded-[2.5rem] shadow-2xl border-8 border-white bg-slate-100" alt={`Image ${i+1}`} />
                    ) : (
                        <div className="my-10 p-10 border-2 border-dashed border-slate-100 rounded-[2.5rem] bg-slate-50/30 text-center">
                            <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest block mb-4">Фото не загружено</span>
                            <div className="max-w-md mx-auto">
                                <p className="text-[11px] text-slate-500 italic mb-4">"{pack.imagePrompts[i] || 'Промпт не сформирован'}"</p>
                                <button 
                                    onClick={() => copyPrompt(pack.imagePrompts[i] || '', i + 100)}
                                    className="text-[9px] font-black text-brand-orange uppercase border border-brand-orange/20 px-6 py-2 rounded-xl hover:bg-brand-orange hover:text-white transition-all"
                                >
                                    {copiedPromptIdx === i + 100 ? 'СКОПИРОВАНО!' : 'КОПИРОВАТЬ ПРОМПТ'}
                                </button>
                            </div>
                        </div>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {activeTab === 'prompts' && (
            <div className="max-w-2xl mx-auto space-y-8 animate-fade-in">
                <div className="text-center mb-10">
                    <h3 className="text-xl font-black text-brand-dark uppercase italic">Инструкции для нейросети</h3>
                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-2">Используйте эти описания в Midjourney, DALL-E или других генераторах</p>
                </div>

                {pack.imagePrompts.map((p, idx) => (
                    <div key={idx} className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm relative group hover:border-brand-orange/30 transition-all">
                        <div className="flex justify-between items-start mb-4">
                            <span className="bg-brand-orange text-white text-[10px] font-black px-4 py-1.5 rounded-lg uppercase">ФОТО #{idx + 1}</span>
                            <button 
                                onClick={() => copyPrompt(p, idx)}
                                className={`text-[10px] font-black uppercase transition-all ${copiedPromptIdx === idx ? 'text-green-500' : 'text-brand-orange hover:scale-105'}`}
                            >
                                {copiedPromptIdx === idx ? 'СКОПИРОВАНО ✅' : 'КОПИРОВАТЬ 📋'}
                            </button>
                        </div>
                        <p className="text-slate-700 italic leading-relaxed text-lg font-medium">"{p}"</p>
                        <div className="mt-6 pt-4 border-t border-slate-50 text-[9px] font-black text-slate-300 uppercase italic">
                            Style: National Geographic, 8k, Photorealistic
                        </div>
                    </div>
                ))}
            </div>
        )}

        {(activeTab === 'tg' || activeTab === 'vk_ok') && (
            <div className="max-w-2xl mx-auto space-y-6">
                <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase mb-2 block">Текст поста</label>
                    <textarea 
                        value={activeTab === 'tg' ? tgText : vkOkText} 
                        onChange={e => activeTab === 'tg' ? setTgText(e.target.value) : setVkOkText(e.target.value)}
                        className="w-full h-[450px] p-8 bg-white text-black border border-slate-200 rounded-[2rem] font-sans leading-relaxed text-lg shadow-inner outline-none focus:ring-4 focus:ring-brand-orange/10 transition-all custom-scrollbar font-bold"
                    />
                </div>
                <div className="bg-white p-6 rounded-[2rem] border-2 border-dashed border-brand-orange/20">
                    <label className="text-[10px] font-black text-brand-orange uppercase mb-3 block">Подпись телеканала</label>
                    <textarea 
                        value={socialSignature}
                        onChange={(e) => setSocialSignature(e.target.value)}
