import React, { useState, useEffect } from 'react';
import { DigestData, PublishingConfig } from '../types';
import { publishToSmmBox } from '../services/publishingService';

interface DigestPostViewerProps {
  digest: DigestData;
  pubConfig: PublishingConfig;
  isGeneratingImage?: boolean;
  imageError?: string; 
}

export const DigestPostViewer: React.FC<DigestPostViewerProps> = ({ digest, pubConfig, isGeneratingImage, imageError }) => {
  const [activeView, setActiveView] = useState<'long' | 'short'>('long');
  const [editableText, setEditableText] = useState('');
  const [publishing, setPublishing] = useState<boolean>(false);
  const [pubStatus, setPubStatus] = useState<{success?: boolean, msg: string}>({msg: ''});
  const [scheduleDate, setScheduleDate] = useState<string>('');
  const [copied, setCopied] = useState(false);

  const getInitialText = (view: 'long' | 'short') => {
    let text = view === 'long' ? digest.formattedDigestText : digest.formattedShortDigest;
    if (view === 'long') {
      text += `\n\n🟠 Информационный вечер Первого туристического\n📆 Каждый день с 17:00 до 20:00 — факты, новости и истории о путешествиях.\n\n➡️ Далее в 19:00 -\n➡️ Затем в 20:00 -`;
    }
    return text;
  };

  useEffect(() => {
    setEditableText(getInitialText(activeView));
  }, [digest, activeView]);

  const handlePublish = async () => {
    if (!pubConfig.smmBoxToken) {
        setPubStatus({success: false, msg: 'Токен SmmBox не настроен!'});
        return;
    }
    setPublishing(true);
    setPubStatus({msg: 'Отправка...'});
    try {
      const res = await publishToSmmBox(pubConfig, editableText.trim(), digest.collageImage ? [digest.collageImage] : [], scheduleDate ? new Date(scheduleDate) : undefined);
      setPubStatus({success: true, msg: 'Успешно опубликовано!'});
    } catch (e: any) {
      setPubStatus({success: false, msg: e.message});
    } finally { setPublishing(false); }
  };

  const copyPrompt = () => {
    navigator.clipboard.writeText(digest.collagePrompt || '');
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="bg-white rounded-[2.5rem] shadow-2xl overflow-hidden border border-slate-50 flex flex-col min-h-[750px] animate-fade-in">
      {/* Шапка дайджеста — строго белая */}
      <div className="bg-white border-b border-slate-50 p-5 flex justify-between items-center">
        <div className="flex gap-2">
            <button onClick={() => setActiveView('long')} className={`text-[10px] px-6 py-2.5 rounded-xl font-black uppercase transition-all ${activeView === 'long' ? 'bg-brand-orange text-white shadow-md' : 'bg-white text-slate-400 border border-slate-50'}`}>Дайджест</button>
            <button onClick={() => setActiveView('short')} className={`text-[10px] px-6 py-2.5 rounded-xl font-black uppercase transition-all ${activeView === 'short' ? 'bg-brand-orange text-white shadow-md' : 'bg-white text-slate-400 border border-slate-50'}`}>Бег. строка</button>
        </div>
      </div>

      <div className="flex-1 flex flex-col bg-white">
        {/* Картинка или Промпт */}
        <div className="h-64 w-full bg-white shrink-0 relative overflow-hidden border-b border-slate-50">
            {digest.collageImage ? (
                <img src={digest.collageImage} className="w-full h-full object-cover animate-fade-in" alt="Collage" />
            ) : isGeneratingImage ? (
                <div className="absolute inset-0 flex flex-col items-center justify-center bg-brand-dark text-white gap-3 p-6 text-center">
                    <div className="w-10 h-10 border-4 border-brand-orange border-t-transparent rounded-full animate-spin"></div>
                    <span className="text-[11px] font-black uppercase tracking-widest animate-pulse">ИИ рисует обложку...</span>
                    <p className="text-[9px] text-white/50 max-w-xs line-clamp-1 italic">{digest.collagePrompt}</p>
                </div>
            ) : (
                <div className="absolute inset-0 flex flex-col items-center justify-center p-8 text-center bg-white">
                    <span className="text-[11px] font-black uppercase tracking-widest mb-3 text-slate-300">Визуал не создан</span>
                    {imageError && (
                        <p className="text-[8px] font-bold text-red-400 uppercase italic mb-4 max-w-xs leading-tight">
                            {imageError.includes("429") ? "ЛИМИТ ИИ ИСЧЕРПАН. Используйте ручной промпт:" : `Ошибка: ${imageError}`}
                        </p>
                    )}

                    <div className="bg-slate-50 p-4 rounded-xl border border-slate-100 w-full animate-fade-in">
                        <label className="block text-[8px] font-black text-slate-400 uppercase mb-2">Промпт для Midjourney/DALL-E:</label>
                        <p className="text-[10px] text-slate-600 italic line-clamp-3 mb-3 font-medium leading-relaxed">"{digest.collagePrompt}"</p>
                        <button 
                            onClick={copyPrompt}
                            className="w-full text-[9px] font-black text-brand-orange uppercase border-2 border-brand-orange/20 py-2 rounded-lg hover:bg-brand-orange hover:text-white transition-all bg-white"
                        >
                            {copied ? 'СКОПИРОВАНО! ✅' : 'КОПИРОВАТЬ ТЕКСТ 📋'}
                        </button>
                    </div>
                </div>
            )}
        </div>

        {/* Управление — строго белое */}
        <div className="p-6 bg-white border-b border-slate-50 space-y-4">
           <div className="flex flex-col gap-1.5">
              <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Запланировать на дату</label>
              <input type="datetime-local" value={scheduleDate} onChange={e => setScheduleDate(e.target.value)} className="w-full text-xs p-3.5 rounded-xl border border-slate-100 outline-none bg-white font-black text-brand-dark focus:ring-2 focus:ring-brand-orange transition-all" />
           </div>

           <button onClick={handlePublish} disabled={publishing} className="w-full bg-brand-dark text-white text-[11px] font-black py-4.5 rounded-2xl uppercase tracking-widest hover:bg-brand-orange transition-all disabled:opacity-50 shadow-xl active:scale-95">
             {publishing ? 'ОТПРАВКА...' : 'ОПУБЛИКОВАТЬ В SMMBOX'}
           </button>

           {pubStatus.msg && <div className={`p-4 rounded-xl text-[10px] text-center font-black border-2 animate-fade-in ${pubStatus.success === false ? 'bg-red-50 text-red-500 border-red-100' : 'bg-green-50 text-green-600 border-green-100'}`}>{pubStatus.msg}</div>}
        </div>

        {/* Текст — строго белый */}
        <div className="p-8 flex-1 bg-white flex flex-col">
            <textarea 
              value={editableText} 
              onChange={e => setEditableText(e.target.value)} 
              className="w-full flex-1 text-lg text-black leading-relaxed font-bold outline-none border-none resize-none custom-scrollbar bg-white" 
              placeholder="Текст дайджеста..."
            />
            <div className="mt-6 pt-4 border-t border-slate-50 flex justify-between items-center text-[10px] text-slate-300 font-black italic uppercase">
              <span>Первый Туристический</span>
              <span>{editableText.length} символов</span>
            </div>
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI, Type } from "@google/genai";
import { DigestData, GeneratedContentPack, NewsItem } from "../types";

// Инициализация API согласно правилам
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getCurrentDate = () => {
  return new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' });
};

/**
 * Поиск новостей с формированием промпта для фотореалистичного коллажа
 */
export const fetchRealNews = async (count: number = 10): Promise<DigestData> => {
  const model = "gemini-3-flash-preview"; 
  const today = getCurrentDate();

  const systemInstruction = `
    ТЫ — ВЕДУЩИЙ РЕДАКТОР "ПЕРВОГО ТУРИСТИЧЕСКОГО ТЕЛЕКАНАЛА". 
    ТЕКУЩАЯ ДАТА: ${today}.

    ЗАДАЧА: Собрать ${count} самых свежих новостей туризма за последние 48 часов.

    ЖЕСТКИЕ ПРАВИЛА ОФОРМЛЕНИЯ ДАЙДЖЕСТА (formattedDigestText):
    1. НУМЕРАЦИЯ: Каждая новость ДОЛЖНА начинаться с ЭМОДЗИ-ЦИФРЫ (1️⃣, 2️⃣...).
    2. ФОРМАТ: "1️⃣ Заголовок новости".
    3. ПОЯСНЕНИЕ: Сразу после заголовка — строго 1-2 предложения сути.
    4. ИСТОЧНИК: В скобках под новостью (Источник: [URL]).

    ТРЕБОВАНИЕ К КОЛЛАЖУ (collagePrompt):
    - Промпт для ФОТОГРАФИИ (National Geographic style).
    - На фото надпись: "НОВОСТИ ТУРИЗМА ${today}".
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Собери новости на ${today}. Нумерация 1️⃣, 2️⃣... Промпт для фото-коллажа с надписью "НОВОСТИ ТУРИЗМА ${today}".`,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            news: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  summary: { type: Type.STRING },
                  ticker: { type: Type.STRING },
                  date: { type: Type.STRING },
                  sourceUrl: { type: Type.STRING }
                },
                required: ["title", "summary", "ticker", "sourceUrl"]
              }
            },
            formattedDigestText: { type: Type.STRING },
            formattedShortDigest: { type: Type.STRING },
            collagePrompt: { type: Type.STRING }
          },
          required: ["news", "formattedDigestText", "formattedShortDigest", "collagePrompt"]
        }
      }
    });

    const data = JSON.parse(response.text || "{}");
    data.news = data.news.map((n: any, i: number) => ({
      ...n, 
      id: `news-${Date.now()}-${i}`
    }));
    return data;
  } catch (error: any) {
    console.error("News Fetch Error:", error);
