                                <span className={selectedNewsIds.includes(n.id) ? 'text-brand-orange' : ''}>{selectedNewsIds.includes(n.id) ? 'ВЫБРАНО ДЛЯ ЛОНГРИДА' : 'НАЖМИТЕ ДЛЯ ВЫБОРА'}</span>
