export const generateArticleLongread = async (newsItem: NewsItem): Promise<Omit<GeneratedContentPack, 'generatedImages'>> => {
  const model = "gemini-3-pro-preview";

  const systemInstruction = `
    ТЫ — ГЛАВНЫЙ АВТОР "ПЕРВОГО ТУРИСТИЧЕСКОГО". 
    ТВОЙ СТИЛЬ: Острая ирония, сарказм, парадоксальные выводы, короткие рубленые фразы. 
    ЗАПРЕТ: КАТЕГОРИЧЕСКИ НЕ УПОМИНАЙ имена Жванецкого, Хмелевской или других авторов. Просто пиши в их духе.

    ЖЕСТКОЕ ТРЕБОВАНИЕ: Никакой "воды". Используй ВСЕ цифры, цены, маршруты, названия компаний и точные даты из предоставленной новости. 
    Объем: Минимум 3000 знаков. Это должен быть обстоятельный, ироничный разбор ситуации.

    СТРУКТУРА СТАТЬИ:
    Headline: Саркастичный заголовок.
    Sections: Минимум 5-6 секций. В каждой — факты + ироничный комментарий.
    Hashtags: СЛОВА ЧЕРЕЗ ЗАПЯТУЮ, БЕЗ СИМВОЛА #.

    СОЦСЕТИ (socials):
    Полноценный микро-рассказ с цифрами и сутью новости. Читатель должен понять всё, не переходя по ссылке. 
    Hashtags в соцсетях: ОБЯЗАТЕЛЬНО С СИМВОЛОМ #.

    ВИЗУАЛИЗАЦИЯ (imagePrompts): Ровно 3 промпта. 
    Стиль: Strictly hyper-realistic photography, 8k, cinematic lighting.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Напиши большой лонгрид по новости: ${newsItem.title}. Факты: ${newsItem.summary}.`,
      config: { 
        systemInstruction, 
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            siteArticle: {
              type: Type.OBJECT,
              properties: {
                headline: { type: Type.STRING },
                sections: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: { heading: { type: Type.STRING }, body: { type: Type.STRING } },
                    required: ["heading", "body"]
                  }
                },
                hashtags: { type: Type.STRING }
              }
            },
            socials: {
              type: Type.OBJECT,
              properties: { tg: { type: Type.STRING }, vk_ok: { type: Type.STRING } }
            },
            imagePrompts: { type: Type.ARRAY, items: { type: Type.STRING } },
            metaDescription: { type: Type.STRING }
          },
          required: ["siteArticle", "socials", "imagePrompts", "metaDescription"]
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (error) {
    throw new Error("Ошибка генерации текста.");
  }
};

export const generateSingleImage = async (prompt: string): Promise<string> => {
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: { parts: [{ text: `Photography: ${prompt}. Cinematic lighting, 8k, photorealistic.` }] },
    config: { imageConfig: { aspectRatio: "16:9" } }
  });
  const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
  if (!part?.inlineData?.data) throw new Error("Ошибка изображения");
  return `data:image/png;base64,${part.inlineData.data}`;
};

import React, { useState, useEffect } from 'react';
import { fetchRealNews, generateArticleLongread, generateSingleImage } from './services/geminiService';
import { AppState, DigestData, GeneratedContentPack, PublishingConfig, NewsItem } from './types';
import { ResultViewer } from './components/ResultViewer';
import { DigestPostViewer } from './components/DigestPostViewer';
import { SettingsModal } from './components/SettingsModal';
import { AddNewsModal } from './components/AddNewsModal';
import { MAX_SELECTION } from './constants';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [digest, setDigest] = useState<DigestData | null>(null);
  const [selectedNewsIds, setSelectedNewsIds] = useState<string[]>([]);
  const [generatedResults, setGeneratedResults] = useState<GeneratedContentPack[]>([]);
  const [statusMessage, setStatusMessage] = useState<string>('');

  const [isCollageGenerating, setIsCollageGenerating] = useState(false);
  const [collageError, setCollageError] = useState<string>('');

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isAddNewsOpen, setIsAddNewsOpen] = useState(false);

  const [pubConfig, setPubConfig] = useState<PublishingConfig>({
    smmBoxToken: '', 
    targetGroupName: 'Первый туристический',
    useProxy: false,
    wordPress: { url: '', username: '', applicationPassword: '' }
  });

  useEffect(() => {
    const saved = localStorage.getItem('tourgenius_settings');
    if (saved) { 
      try { 
        setPubConfig(prev => ({...prev, ...JSON.parse(saved)})); 
      } catch(e) {} 
    }
  }, []);

  const handleFetchNews = async () => {
    setAppState(AppState.SEARCHING);
    setStatusMessage("Ищем свежие новости (строго 48ч)...");
    setSelectedNewsIds([]);
    try {
      const data = await fetchRealNews(12);
      setDigest(data);
      setAppState(AppState.SELECTING);

      if (data.collagePrompt) {
        setIsCollageGenerating(true);
        generateSingleImage(data.collagePrompt)
          .then(imageUrl => {
            setDigest(prev => prev ? ({ ...prev, collageImage: imageUrl }) : null);
            setIsCollageGenerating(false);
          })
          .catch(() => setIsCollageGenerating(false));
      }
    } catch (e: any) { 
        setAppState(AppState.IDLE); 
        alert(e.message); 
    }
  };

  const handleToggleSelection = (id: string) => {
    setSelectedNewsIds(prev => {
      if (prev.includes(id)) return prev.filter(i => i !== id);
      if (prev.length < MAX_SELECTION) return [...prev, id];
      return prev;
    });
  };

  const handleGenerate = async () => {
    if (selectedNewsIds.length === 0) return;

    setAppState(AppState.GENERATING_CONTENT);
    setGeneratedResults([]);

    const itemsToGenerate = digest?.news.filter(n => selectedNewsIds.includes(n.id)) || [];

    for (let i = 0; i < itemsToGenerate.length; i++) {
      const currentNews = itemsToGenerate[i];
      try {
        setStatusMessage(`[${i+1}/${itemsToGenerate.length}] Пишем ироничный лонгрид: ${currentNews.title}...`);
        const pack = await generateArticleLongread(currentNews);

        setStatusMessage(`[${i+1}/${itemsToGenerate.length}] Генерируем 3 фото-иллюстрации...`);
        const imgs: string[] = [];
        for (const prompt of pack.imagePrompts.slice(0, 3)) {
          try {
            const img = await generateSingleImage(prompt);
            imgs.push(img);
          } catch (e) {
            console.error("Image generation failed", e);
          }
        }

        setGeneratedResults(prev => [...prev, { ...pack, newsId: currentNews.id, generatedImages: imgs }]);
      } catch (e: any) { 
        console.error(e);
      }
    }
    setAppState(AppState.COMPLETED);
  };

  const handleAddManualNews = (news: { title: string; summary: string; location: string; sourceUrl: string }) => {
    const newItem: NewsItem = {
        id: `manual-${Date.now()}`,
        title: news.title,
        summary: news.summary,
        location: news.location,
        ticker: news.title,
        date: new Date().toLocaleDateString('ru-RU'),
        sourceUrl: news.sourceUrl || '',
        sourceName: 'Ручной ввод'
    };

    if (!digest) {
        setDigest({
            news: [newItem],
            formattedDigestText: `📌 ${newItem.title} — ${newItem.summary.slice(0, 50)}...`,
            formattedShortDigest: `📌 ${newItem.title}`,
            collagePrompt: `Photography: ${newItem.title}`
        });
        setAppState(AppState.SELECTING);
    } else {
        setDigest({ ...digest, news: [newItem, ...digest.news] });
    }
  };

  return (
    <div className="min-h-screen bg-[#f8f9fa] pb-20">
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} config={pubConfig} onSave={setPubConfig} />
      <AddNewsModal isOpen={isAddNewsOpen} onClose={() => setIsAddNewsOpen(false)} onAdd={handleAddManualNews} />

      <nav className="bg-white h-20 flex items-center px-8 border-b border-slate-100 sticky top-0 z-50 shadow-sm">
        <div className="flex flex-col">
          <h1 className="text-brand-dark font-black tracking-tighter text-3xl italic leading-none">TOUR<span className="text-brand-orange">GENIUS</span></h1>
          <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest italic">Контент-платформа Телеканала</span>
        </div>
        <div className="ml-auto flex items-center gap-4">
           {(appState === AppState.SELECTING || appState === AppState.IDLE) && (
               <button onClick={() => setIsAddNewsOpen(true)} className="bg-brand-orange text-white px-5 py-2.5 rounded-xl text-[10px] font-black uppercase shadow-lg hover:scale-105 transition-all">➕ Своя тема</button>
           )}
           <button onClick={() => setIsSettingsOpen(true)} className="w-12 h-12 bg-white flex items-center justify-center rounded-xl border border-slate-100 transition-all text-lg hover:shadow-md hover:border-brand-orange/20">⚙️</button>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto p-6">
        {appState === AppState.IDLE && (
          <div className="bg-white rounded-[4rem] p-24 shadow-2xl border border-slate-50 text-center mt-12 animate-fade-in">
            <h2 className="text-6xl font-black text-brand-dark mb-8 uppercase italic leading-tight">Первый <br/><span className="text-brand-orange">Туристический</span></h2>
            <p className="text-slate-400 text-xl mb-12 max-w-2xl mx-auto font-medium italic">Автоматизированная редакция: поиск актуальных событий и создание едкой аналитики.</p>
            <button onClick={handleFetchNews} className="bg-brand-dark text-white px-20 py-7 rounded-3xl font-black uppercase tracking-widest hover:bg-brand-orange transition-all shadow-2xl transform hover:scale-105">Начать поиск новостей</button>
          </div>
        )}

        {appState === AppState.SEARCHING && (
          <div className="flex flex-col items-center py-48">
             <div className="w-20 h-20 border-8 border-brand-orange border-t-transparent rounded-full animate-spin mb-10"></div>
             <h3 className="text-3xl font-black text-brand-dark uppercase italic animate-pulse">{statusMessage}</h3>
          </div>
        )}

        {(appState === AppState.SELECTING || appState === AppState.GENERATING_CONTENT || appState === AppState.COMPLETED) && digest && (
          <div className="space-y-12 animate-fade-in">
            {appState === AppState.SELECTING && (
              <div className="flex justify-between items-center bg-white p-10 rounded-[2.5rem] border border-slate-50 shadow-2xl sticky top-24 z-40">
                <div>
                    <h2 className="text-3xl font-black text-brand-dark uppercase italic">Выбор тем на сегодня</h2>
                    <p className="text-[11px] font-black text-brand-orange uppercase mt-2">Выбрано: {selectedNewsIds.length} из {MAX_SELECTION}</p>
                </div>
                <button 
                  onClick={handleGenerate} 
                  disabled={selectedNewsIds.length === 0} 
                  className={`px-14 py-5 rounded-2xl font-black uppercase text-sm shadow-2xl transition-all ${selectedNewsIds.length > 0 ? 'bg-brand-orange text-white' : 'bg-slate-50 text-slate-300 cursor-not-allowed border'}`}
                >
                  Создать лонгриды ({selectedNewsIds.length})
                </button>
              </div>
            )}

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
                <div className="lg:col-span-4 h-fit">
                  <DigestPostViewer 
                    digest={digest} 
                    pubConfig={pubConfig} 
                    isGeneratingImage={isCollageGenerating} 
                    imageError={collageError}
                  />
                </div>
                <div className="lg:col-span-8 space-y-10 pb-20">
                   {appState === AppState.SELECTING ? (
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                        {digest.news.map(n => (
                          <div 
                            key={n.id} 
                            onClick={() => handleToggleSelection(n.id)}
                            className={`group p-8 rounded-[2.5rem] border-4 transition-all bg-white flex flex-col cursor-pointer relative ${selectedNewsIds.includes(n.id) ? 'border-brand-orange shadow-2xl scale-[1.02]' : 'border-slate-50 shadow-lg'}`}
                          >
                             <div className="flex justify-between items-center mb-4">
                                <span className={`text-[10px] font-black uppercase px-2 py-1 rounded-lg border ${selectedNewsIds.includes(n.id) ? 'bg-brand-orange text-white border-brand-orange' : 'bg-slate-50 text-slate-500'}`}>{n.sourceName}</span>
                                <span className="text-[10px] font-black uppercase text-brand-orange">📅 {n.date}</span>
                             </div>
                             <h4 className={`font-black text-xl mb-3 leading-tight ${selectedNewsIds.includes(n.id) ? 'text-brand-orange' : 'text-brand-dark'}`}>{n.title}</h4>
                             <p className="text-slate-500 text-sm leading-relaxed line-clamp-4 mb-6">{n.summary}</p>
                             <div className="mt-auto pt-6 border-t border-slate-50 flex justify-between items-center">
                                {n.sourceUrl && <a href={n.sourceUrl} target="_blank" rel="noopener noreferrer" onClick={e => e.stopPropagation()} className="text-[10px] font-black text-slate-400 uppercase hover:text-brand-orange">🔗 Источник</a>}
                                {selectedNewsIds.includes(n.id) && <span className="text-brand-orange font-black text-xs uppercase">В плане ✅</span>}
                             </div>
                          </div>
                        ))}
                      </div>
                   ) : (
                      <>
                        {appState === AppState.GENERATING_CONTENT && (
                           <div className="bg-white p-10 rounded-[2.5rem] shadow-xl border-2 border-brand-orange border-dashed text-center animate-pulse">
                              <p className="font-black uppercase text-brand-dark text-lg">{statusMessage}</p>
                           </div>
                        )}
                        {generatedResults.map(res => <ResultViewer key={res.newsId} pack={res} pubConfig={pubConfig} />)}
                      </>
                   )}
                </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { DigestData, GeneratedContentPack, NewsItem } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getDateRange = () => {
  const now = new Date(); 
  const cutoff = new Date(now.getTime() - 48 * 3600000);
  const formatDate = (d: Date) => d.toISOString().split('T')[0];

  return {
    after: formatDate(cutoff),
    before: formatDate(now),
    todayStr: now.toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' })
  };
};

/**
 * Поиск реальных новостей за последние 48 часов
 */
export const fetchRealNews = async (count: number = 12): Promise<DigestData> => {
  const { todayStr } = getDateRange();
  const searchLimitDate = new Date(Date.now() - 48 * 3600000).toLocaleDateString('ru-RU');

  const systemInstruction = `
    ТЫ — ВЕДУЩИЙ НОВОСТНОЙ АНАЛИТИК ТУРИЗМА. СЕГОДНЯ ${todayStr}.

    ЗАДАЧА: Найти новости, опубликованные СТРОГО за последние 48 часов (после ${searchLimitDate}). 
    КАТЕГОРИЧЕСКИ ИГНОРИРУЙ НОВОСТИ 2024 ГОДА И СТАРШЕ. Проверяй даты в текстах источников.

    ЖЕСТКИЕ ПРАВИЛА ФОРМАТИРОВАНИЯ:
    1. formattedDigestText (Дайджест для поста): 
       - Формат: "[ПОДХОДЯЩИЙ ЭМОДЗИ] Заголовок — Краткое пояснение сути".
       - БЕЗ упоминания ссылок, URL или слов "Источник:". Ссылки переноси только в объект news.
       - Перед каждой новостью ОБЯЗАТЕЛЬНО тематический эмодзи.

    2. formattedShortDigest (Бегущая строка): 
       - Формат: "[ЭМОДЗИ] Новость: Краткое пояснение". 
       - Лаконично, в одну строку через разделители.

    3. ТРЕБОВАНИЕ К КОЛЛАЖУ (collagePrompt): 
       - Промпт для фотореалистичного изображения (National Geographic style) с надписью "ТУРИЗМ: ГЛАВНОЕ ${todayStr}".
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview", 
      contents: `Найди новости туризма за последние 48 часов (с ${searchLimitDate}). Сформируй дайджест.`,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            news: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  summary: { type: Type.STRING },
                  sourceName: { type: Type.STRING },
                  sourceUrl: { type: Type.STRING },
                  date: { type: Type.STRING },
                  location: { type: Type.STRING }
                },
                required: ["title", "summary", "sourceName", "sourceUrl", "date"]
              }
            },
            formattedDigestText: { type: Type.STRING },
            formattedShortDigest: { type: Type.STRING },
            collagePrompt: { type: Type.STRING }
          },
          required: ["news", "formattedDigestText", "formattedShortDigest", "collagePrompt"]
        }
      }
    });

    const data = JSON.parse(response.text || "{}");
    return {
      ...data,
      news: (data.news || []).map((n: any, i: number) => ({ 
        ...n, 
        id: `news-${Date.now()}-${i}`,
        ticker: n.title 
      }))
    };
  } catch (error: any) {
    throw new Error(`Ошибка поиска новостей: ${error.message}`);
  }
};

