import { GoogleGenAI, Type } from "@google/genai";
import { DigestData, GeneratedContentPack, NewsItem } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getDateRange = () => {
  const now = new Date(); 
  const cutoff = new Date(now.getTime() - 48 * 3600000);
  const formatDate = (d: Date) => d.toISOString().split('T')[0];

  return {
    after: formatDate(cutoff),
    before: formatDate(now),
    todayStr: now.toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' })
  };
};

/**
 * Поиск реальных новостей за последние 48 часов с фокусом на РФ источники
 */
export const fetchRealNews = async (count: number = 12): Promise<DigestData> => {
  const { todayStr } = getDateRange();
  const searchLimitDate = new Date(Date.now() - 48 * 3600000).toLocaleDateString('ru-RU');

  const systemInstruction = `
    ТЫ — ВЕДУЩИЙ НОВОСТНОЙ АНАЛИТИК РОССИЙСКОГО ТУРИЗМА. СЕГОДНЯ ${todayStr}.

    ЗАДАЧА: Найти самые важные новости, опубликованные СТРОГО за последние 48 часов (после ${searchLimitDate}).

    ПРИОРИТЕТНЫЕ ИСТОЧНИКИ (Ищи информацию в первую очередь здесь):
    - ТАСС (tass.ru), РИА Новости (ria.ru)
    - АТОР (atorus.ru)
    - Турдом (tourdom.ru)
    - Турпром (tourprom.ru)
    - Туристер (tourister.ru)

    КЛЮЧЕВЫЕ ТЕМЫ (Фокус на интересах туристов из РФ):
    - Российские авиакомпании (Аэрофлот, S7, Red Wings, Победа).
    - РЖД (новые поезда, расписание, билеты).
    - Визы, въездные требования, проблемы за рубежом.
    - Внутренний туризм (Сочи, Алтай, Крым, Питер).

    КАТЕГОРИЧЕСКИ ИГНОРИРУЙ НОВОСТИ 2024 ГОДА И СТАРШЕ. Проверяй даты в текстах источников.

    ЖЕСТКИЕ ПРАВИЛА ФОРМАТИРОВАНИЯ:
    1. formattedDigestText (Дайджест для поста): 
       - Формат: "[ПОДХОДЯЩИЙ ЭМОДЗИ] Заголовок — Краткое пояснение сути".
       - БЕЗ упоминания ссылок, URL или слов "Источник:". Ссылки переноси только в объект news.
       - Перед каждой новостью ОБЯЗАТЕЛЬНО тематический эмодзи.

    2. formattedShortDigest (Бегущая строка): 
       - Формат: "[ЭМОДЗИ] Новость: Краткое пояснение". 
       - Лаконично, в одну строку через разделители.

    3. ТРЕБОВАНИЕ К КОЛЛАЖУ (collagePrompt): 
       - Промпт для фотореалистичного изображения (National Geographic style) с надписью "ТУРИЗМ: ГЛАВНОЕ ${todayStr}".
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview", 
      contents: `Найди срочные новости туризма для россиян за последние 48 часов (с ${searchLimitDate}). 
      Проверь сайты: ТАСС, РИА, atorus.ru, tourdom.ru, tourprom.ru, tourister.ru.
      Темы: Авиабилеты, РЖД, законодательство, происшествия. Сформируй дайджест.`,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            news: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  summary: { type: Type.STRING },
                  sourceName: { type: Type.STRING },
                  sourceUrl: { type: Type.STRING },
                  date: { type: Type.STRING },
                  location: { type: Type.STRING }
                },
                required: ["title", "summary", "sourceName", "sourceUrl", "date"]
              }
            },
            formattedDigestText: { type: Type.STRING },
            formattedShortDigest: { type: Type.STRING },
            collagePrompt: { type: Type.STRING }
          },
          required: ["news", "formattedDigestText", "formattedShortDigest", "collagePrompt"]
        }
      }
    });

    const data = JSON.parse(response.text || "{}");
    return {
      ...data,
      news: (data.news || []).map((n: any, i: number) => ({ 
        ...n, 
        id: `news-${Date.now()}-${i}`,
        ticker: n.title 
      }))
    };
  } catch (error: any) {
    throw new Error(`Ошибка поиска новостей: ${error.message}`);
  }
};

/**
 * Генерация ироничной статьи с жесткой фактурой
 */
export const generateArticleLongread = async (newsItem: NewsItem): Promise<Omit<GeneratedContentPack, 'generatedImages'>> => {
  const model = "gemini-3-pro-preview";

  const systemInstruction = `
    ТЫ — ГЛАВНЫЙ РЕДАКТОР "ПЕРВОГО ТУРИСТИЧЕСКОГО". 
    ТВОЙ СТИЛЬ: Острый сарказм, ирония, парадоксы. Короткие фразы. 
    ЗАПРЕТ: НЕ упоминай имена авторов (Жванецкий и др.). Пиши просто в их духе.

    ЖЕСТКОЕ ТРЕБОВАНИЕ: СТАТЬЯ ДОЛЖНА БЫТЬ ПОЛНА ФАКТОВ. 
    Используй ВСЕ цифры, цены, точные маршруты, названия компаний и даты из новости: ${newsItem.title} - ${newsItem.summary}. 
    Если в новости есть цены в валюте или конкретные даты — они ОБЯЗАНЫ быть в тексте.

    СТРУКТУРА:
    - Headline: Едкий заголовок.
    - Sections: Минимум 5 разделов (Заголовок + Текст). 
    - Hashtags: Слова без символа #.

    СОЦСЕТИ:
    - Пост должен быть информативным, с цифрами, чтобы человек все узнал из поста.
    - Хэштеги в соцсетях: ОБЯЗАТЕЛЬНО С #.

    ВИЗУАЛИЗАЦИЯ: Сгенерируй ровно 3 детальных промпта для фотореалистичных кадров (Photography, 8k).
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Напиши аналитический ироничный лонгрид по новости: ${newsItem.title}. Фактура: ${newsItem.summary}`,
      config: { 
        systemInstruction, 
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            siteArticle: {
              type: Type.OBJECT,
              properties: {
                headline: { type: Type.STRING },
                sections: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: { heading: { type: Type.STRING }, body: { type: Type.STRING } },
                    required: ["heading", "body"]
                  }
                },
                hashtags: { type: Type.STRING }
              }
            },
            socials: {
              type: Type.OBJECT,
              properties: { tg: { type: Type.STRING }, vk_ok: { type: Type.STRING } }
            },
            imagePrompts: { type: Type.ARRAY, items: { type: Type.STRING } },
            metaDescription: { type: Type.STRING }
          },
          required: ["siteArticle", "socials", "imagePrompts", "metaDescription"]
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (error: any) {
    throw new Error(`Ошибка генерации статьи: ${error.message}`);
  }
};

export const generateSingleImage = async (prompt: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: `High-end photography: ${prompt}. Cinematic lighting, extreme detail, 8k resolution.` }] },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (!part?.inlineData?.data) throw new Error("Image data missing");
    return `data:image/png;base64,${part.inlineData.data}`;
  } catch (e) {
    console.error("Image generation error", e);
    throw e;
  }
};

