import { PublishingConfig, WordPressConfig } from "../types";

const SMMBOX_BASE_URL = "https://smmbox.com/api/v1";

const formatDateForWP = (dateStr: string) => {
    if (!dateStr) return null;
    return new Date(dateStr).toISOString().split('.')[0]; 
};

const wrapUrl = (url: string, useProxy: boolean) => {
    return useProxy ? `https://corsproxy.io/?${encodeURIComponent(url)}` : url;
};

const fetchWithTimeout = async (url: string, options: RequestInit = {}, useProxy: boolean = false) => {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 30000); // 30 секунд таймаут

    const doFetch = async (isProxy: boolean) => {
        const targetUrl = isProxy ? wrapUrl(url, true) : url;
        // Для SmmBox/WP важно сохранять заголовки
        return fetch(targetUrl, { ...options, signal: controller.signal });
    };

    try {
        let response = await doFetch(useProxy);

        // Обработка блокировок прокси (corsproxy.io часто возвращает 403 на бесплатном тарифе для POST или заголовков)
        if (useProxy && response.status === 403) {
            const clone = response.clone();
            const text = await clone.text();
            // Проверяем, что ошибка именно от прокси
            if (text.includes("corsproxy.io") || text.includes("content type is not allowed") || text.includes("Upgrade")) {
                console.warn("CORS Proxy blocked request. Retrying directly...", text);
                response = await doFetch(false);
            }
        }

        clearTimeout(timeoutId);

        if (!response.ok) {
            const errorText = await response.text();
            throw new Error(`API Error (${response.status}): ${errorText || 'Unknown'}`);
        }
        return response;
    } catch (error: any) {
        clearTimeout(timeoutId);
        if (error.name === 'AbortError') {
            throw new Error('Превышено время ожидания (30 сек). Проверьте интернет.');
        }
        if (error.message === 'Failed to fetch') {
            if (useProxy) {
                 // Если прокси недоступен, пробуем напрямую (на всякий случай)
                 try {
                     const directRes = await doFetch(false);
                     if (directRes.ok) return directRes;
                 } catch(e) {} // Игнорируем ошибку прямого запроса, возвращаем исходную
            }
            throw new Error('Ошибка сети (Failed to fetch). Если вы используете прокси, попробуйте его отключить. Если прямой запрос - возможно проблема с CORS.');
        }
        throw error;
    }
};

export const fetchSmmBoxGroups = async (config: PublishingConfig) => {
    const url = `${SMMBOX_BASE_URL}/groups`;
    // Пытаемся использовать настройку прокси, но fetchWithTimeout сам откатится, если прокси заблокирует
    const response = await fetchWithTimeout(url, {
        method: 'GET',
        headers: { 'Authorization': `Bearer ${config.smmBoxToken}` }
    }, config.useProxy);
    const data = await response.json();
    return data.response || [];
};

export const testWordPressConnection = async (config: WordPressConfig, useProxy: boolean) => {
    if (!config.url || !config.username || !config.applicationPassword) {
        throw new Error("Заполните все поля WordPress");
    }
    const auth = btoa(`${config.username}:${config.applicationPassword}`);
    const url = `${config.url.replace(/\/$/, '')}/wp-json/wp/v2/users/me`;

    const response = await fetchWithTimeout(url, {
        method: 'GET',
        headers: { 
            'Authorization': `Basic ${auth}`,
            'Content-Type': 'application/json'
        }
    }, useProxy);

    return await response.json();
};

export const publishToSmmBox = async (config: PublishingConfig, text: string, imagesBase64: string[] = [], publishDate?: Date) => {
    if (!config.smmBoxToken) throw new Error("Токен SmmBox не настроен");

    const allGroups = await fetchSmmBoxGroups(config);
    const groups = allGroups.filter((g: any) => g.name.toLowerCase().includes(config.targetGroupName.toLowerCase()));
    if (groups.length === 0) throw new Error(`Группа "${config.targetGroupName}" не найдена в SmmBox.`);

    const attachments: any[] = [{ type: 'text', text }];
    imagesBase64.slice(0, 3).forEach(img => {
        if (img?.startsWith('data:')) attachments.push({ type: 'photo', original: img });
    });

    const url = `${SMMBOX_BASE_URL}/posts/postpone`;
    const results = [];

    for (const group of groups) {
        const postPayload = {
            group: { id: group.id, social: group.social, type: group.type },
            attachments: attachments,
            options: ['from_group'],
            date: publishDate ? Math.floor(publishDate.getTime() / 1000) : Math.floor(Date.now() / 1000) + 60
        };

        const body = {
            posts: [ postPayload ]
        };

        const response = await fetchWithTimeout(url, {
            method: 'POST',
            headers: { 
                'Content-Type': 'application/json', 
                'Authorization': `Bearer ${config.smmBoxToken}` 
            },
            body: JSON.stringify(body)
        }, config.useProxy);
        results.push(await response.json());
    }
    return results;
};

export const publishToWordPress = async (
    config: WordPressConfig, 
    useProxy: boolean,
    title: string, 
    sections: {heading: string, body: string}[], 
    imagesBase64: string[], 
    tags: string,
    metaDescription: string,
    publishDateStr?: string,
    onProgress?: (msg: string) => void
) => {
    const auth = btoa(`${config.username}:${config.applicationPassword}`);

    const uploadMedia = async (base64: string) => {
        const res = await fetch(base64);
        const blob = await res.blob();
        const fd = new FormData();
        fd.append('file', blob, `tour-img-${Date.now()}.png`);

        const r = await fetchWithTimeout(`${config.url.replace(/\/$/, '')}/wp-json/wp/v2/media`, {
            method: 'POST',
            headers: { 'Authorization': `Basic ${auth}` },
            body: fd
        }, useProxy);
        return await r.json();
    };

    const mediaUrls: string[] = [];
    for (const img of imagesBase64.slice(0, 3)) {
        try {
            const m = await uploadMedia(img);
            mediaUrls.push(m.source_url);
        } catch (e) { console.warn("Media upload failed", e); }
    }

    let content = '';
    sections.forEach((s, idx) => {
        if (s.heading) content += `<h2 class="wp-block-heading"><strong>${s.heading}</strong></h2>`;
        content += `<p>${s.body}</p>`;
        if (mediaUrls[idx]) content += `<figure class="wp-block-image size-large"><img src="${mediaUrls[idx]}" alt="${title}" /></figure>`;
    });

    if (tags) {
        content += `<hr /><p><strong>Теги:</strong> ${tags.replace(/#/g, '')}</p>`;
    }

    const wpDate = formatDateForWP(publishDateStr || "");
    const body: any = { 
        title, 
        content, 
        status: wpDate ? 'future' : 'publish', 
        excerpt: metaDescription 
    };
    if (wpDate) body.date = wpDate;

    const r = await fetchWithTimeout(`${config.url.replace(/\/$/, '')}/wp-json/wp/v2/posts`, {
        method: 'POST',
        headers: { 'Authorization': `Basic ${auth}`, 'Content-Type': 'application/json' },
        body: JSON.stringify(body)
    }, useProxy);
    return await r.json();
};

import { PublishingConfig, WordPressConfig } from "../types";

const SMMBOX_BASE_URL = "https://smmbox.com/api/v1";

const formatDateForWP = (dateStr: string) => {
    if (!dateStr) return null;
    return new Date(dateStr).toISOString().split('.')[0]; 
};

// Список прокси-сервисов в порядке приоритета
const getProxyCandidates = (targetUrl: string, useProxy: boolean) => {
    if (!useProxy) return [targetUrl];

    const encoded = encodeURIComponent(targetUrl);
    return [
        // 1. ThingProxy - обычно хорошо переваривает заголовки и POST
        `https://thingproxy.freeboard.io/fetch/${targetUrl}`,
        // 2. CodeTabs - всеядный, но иногда медленный
        `https://api.codetabs.com/v1/proxy?quest=${encoded}`,
        // 3. CorsProxy.io - быстрый, но на бесплатном тарифе не любит Content-Type: application/json
        `https://corsproxy.io/?${encoded}`,
        // 4. Прямой запрос (fallback)
        targetUrl
    ];
};

const fetchWithRobustProxy = async (url: string, options: RequestInit = {}, useProxy: boolean = false) => {
    const candidates = getProxyCandidates(url, useProxy);

    let lastError: any = null;
    let lastResponse: Response | null = null;

    for (const fetchUrl of candidates) {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 20000); // 20 сек на каждый прокси

        try {
            console.log(`Trying request to: ${fetchUrl}`);
            const response = await fetch(fetchUrl, { ...options, signal: controller.signal });
            clearTimeout(timeoutId);

            // Если запрос успешен (200-299) - возвращаем сразу
            if (response.ok) return response;

            // Если ошибка, проверяем, не прокси ли это капризничает
            // 403/429/500 часто бывают от прокси
            if (response.status === 403 || response.status === 429 || response.status >= 500) {
                try {
                    const text = await response.clone().text();
                    const lowerText = text.toLowerCase();
                    const isProxyError = lowerText.includes('cors') || 
                                         lowerText.includes('proxy') || 
                                         lowerText.includes('limit') || 
                                         lowerText.includes('denied') ||
                                         lowerText.includes('content type is not allowed'); // Специфично для corsproxy.io

                    if (isProxyError) {
                        console.warn(`Proxy ${fetchUrl} failed with proxy error: ${text}`);
                        lastResponse = response;
                        continue; // Пробуем следующий прокси
                    }
                } catch (e) {}

                // Если это ошибка целевого API (например, неверный токен SmmBox - 400/401), возвращаем её, нет смысла менять прокси
                return response;
            }

            // Для остальных ошибок (например 404) тоже возвращаем ответ
            return response;

        } catch (error: any) {
            clearTimeout(timeoutId);
            // Если AbortError или Failed to fetch (сеть/CORS) - пробуем следующий
            console.warn(`Failed to fetch via ${fetchUrl}:`, error.message);
            lastError = error;
            continue;
        }
    }

    if (lastResponse) return lastResponse;
    throw lastError || new Error('Не удалось выполнить запрос ни через один прокси. Проверьте интернет или настройки.');
};

export const fetchSmmBoxGroups = async (config: PublishingConfig) => {
    const url = `${SMMBOX_BASE_URL}/groups`;
    const response = await fetchWithRobustProxy(url, {
        method: 'GET',
        headers: { 'Authorization': `Bearer ${config.smmBoxToken}` }
    }, config.useProxy);

    const data = await response.json();
    // SmmBox иногда возвращает 200 OK, но внутри JSON есть поле error
    if (data.error) throw new Error(`SmmBox API Error: ${JSON.stringify(data.error)}`);
    return data.response || [];
};

