    const allGroups = await fetchSmmBoxGroups(config);
    const groups = allGroups.filter((g: any) => g.name.toLowerCase().includes(config.targetGroupName.toLowerCase()));
    if (groups.length === 0) throw new Error(`Группа "${config.targetGroupName}" не найдена в SmmBox. Доступные: ${allGroups.map((g: any) => g.name).join(', ')}`);

    // 2. Формируем вложения
    const attachments: any[] = [{ type: 'text', text }];
    imagesBase64.slice(0, 3).forEach(img => {
        if (img?.startsWith('data:')) attachments.push({ type: 'photo', original: img });
    });

    const url = `${SMMBOX_BASE_URL}/posts/postpone`;
    const results = [];

    // 3. Отправляем в каждую найденную группу
    for (const group of groups) {
        const postPayload = {
            group: { id: group.id, social: group.social, type: group.type },
            attachments: attachments,
            options: ['from_group'],
            date: publishDate ? Math.floor(publishDate.getTime() / 1000) : Math.floor(Date.now() / 1000) + 180 // +3 мин минимум
        };

        const body = { posts: [ postPayload ] };

        const response = await fetchWithRobustProxy(url, {
            method: 'POST',
            headers: { 
                'Content-Type': 'application/json', 
                'Authorization': `Bearer ${config.smmBoxToken}` 
            },
            body: JSON.stringify(body)
        }, config.useProxy);

        const data = await response.json();
        if (data.error) throw new Error(`SmmBox Post Error: ${JSON.stringify(data.error)}`);
        results.push(data);
    }
    return results;
};

