// Список прокси-сервисов. 
// ВАЖНО: CorsProxy.io ставим в конец, так как он блокирует POST JSON на бесплатном тарифе.
// ThingProxy обычно стабильнее для API запросов.
const getProxyCandidates = (targetUrl: string, useProxy: boolean) => {
    if (!useProxy) return [targetUrl];

    const encoded = encodeURIComponent(targetUrl);
    return [
        // 1. ThingProxy - лучше всего работает с заголовками и POST
        `https://thingproxy.freeboard.io/fetch/${targetUrl}`,
        // 2. Прямой запрос (если у пользователя стоит расширение CORS Allow или отключена защита в браузере)
        targetUrl,
        // 3. CorsProxy.io - запасной вариант (часто выдает 403 на POST)
        `https://corsproxy.io/?${encoded}`,
        // 4. CodeTabs - как последний шанс
        `https://api.codetabs.com/v1/proxy?quest=${encoded}`,
    ];
};

const fetchWithRobustProxy = async (url: string, options: RequestInit = {}, useProxy: boolean = false) => {
    const candidates = getProxyCandidates(url, useProxy);

    let lastError: any = null;

    for (const fetchUrl of candidates) {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 25000); // 25 сек

        try {
            console.log(`Trying request via: ${fetchUrl}`);
            const response = await fetch(fetchUrl, { ...options, signal: controller.signal });
            clearTimeout(timeoutId);

            // КРИТИЧЕСКИ ВАЖНО: Читаем текст ответа, чтобы проверить, не вернул ли прокси ошибку в виде текста 
            // даже при статусе 200 (некоторые прокси так делают).
            // Клонируем, чтобы не испортить основной response
            const textBody = await response.clone().text();
            const lowerBody = textBody.toLowerCase();

            // Список фраз, которые говорят о том, что ПРОКСИ отказал в обслуживании
            const isProxyBlock = 
                lowerBody.includes("this content type is not allowed") ||
                lowerBody.includes("corsproxy.io") ||
                lowerBody.includes("proxy error") ||
                lowerBody.includes("missing required request header");

            if (isProxyBlock || response.status === 403 || response.status === 429) {
                console.warn(`Proxy rejected request (${fetchUrl}): ${textBody.substring(0, 100)}...`);
                // Не выбрасываем ошибку, а просто идем к следующему кандидату (continue)
                continue;
            }

            // Если это не блокировка прокси, но статус не OK (например 401 от самого SmmBox), возвращаем как есть
            return response;

        } catch (error: any) {
            clearTimeout(timeoutId);
            console.warn(`Connection failed to ${fetchUrl}:`, error.message);
            lastError = error;
            // Пробуем следующий
            continue;
        }
    }

    throw lastError || new Error('Не удалось подключиться ни через один прокси. Попробуйте установить расширение "Allow CORS" в браузер и отключить прокси в настройках.');
};

