const formatDateForWP = (dateStr: string) => {
    if (!dateStr) return null;
    return new Date(dateStr).toISOString().split('.')[0]; 
};

// Список прокси-сервисов. 
// Убрали corsproxy.io, так как он блокирует application/json на бесплатном тарифе.
const getProxyCandidates = (targetUrl: string, useProxy: boolean) => {
    if (!useProxy) return [targetUrl];

    const encoded = encodeURIComponent(targetUrl);
    return [
        // 1. ThingProxy - стабильный для API
        `https://thingproxy.freeboard.io/fetch/${targetUrl}`,
        // 2. CodeTabs - альтернатива
        `https://api.codetabs.com/v1/proxy?quest=${encoded}`,
        // 3. Прямой запрос (fallback)
        targetUrl
    ];
};

const fetchWithRobustProxy = async (url: string, options: RequestInit = {}, useProxy: boolean = false) => {
    const candidates = getProxyCandidates(url, useProxy);

    let lastError: any = null;

    for (const fetchUrl of candidates) {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 25000); // 25 сек

        try {
            console.log(`Connecting to: ${fetchUrl}`);
            const response = await fetch(fetchUrl, { ...options, signal: controller.signal });
            clearTimeout(timeoutId);

            // Если статус успешен - возвращаем
            if (response.ok) return response;

            // Если статус 401 - это ошибка авторизации целевого сервиса, прокси отработал нормально
            if (response.status === 401) return response;

            // Если ошибка сервера (5xx) или запрет (403/429) и это был прокси-запрос - пробуем следующий
            // (Так как это может быть бан самого прокси)
            const isDirect = fetchUrl === url;
            if (!isDirect && (response.status === 403 || response.status === 429 || response.status >= 500)) {
                console.warn(`Proxy ${fetchUrl} returned ${response.status}. Trying next...`);
                continue;
            }

            // В остальных случаях (например 400 Bad Request) возвращаем ответ сервиса
            return response;

        } catch (error: any) {
            clearTimeout(timeoutId);
            console.warn(`Failed to fetch via ${fetchUrl}:`, error.message);
            lastError = error;
            // Пробуем следующий
            continue;
        }
    }

    throw lastError || new Error('Ошибка сети. Не удалось подключиться через прокси. Попробуйте отключить прокси в настройках.');
};

