import { PublishingConfig, WordPressConfig } from "../types";

const SMMBOX_BASE_URL = "https://smmbox.com/api/v1";

const formatDateForWP = (dateStr: string) => {
    if (!dateStr) return null;
    return new Date(dateStr).toISOString().split('.')[0]; 
};

// Список прокси-сервисов с учетом метода запроса
const getProxyCandidates = (targetUrl: string, useProxy: boolean, method: string) => {
    if (!useProxy) return [targetUrl];

    const encoded = encodeURIComponent(targetUrl);
    const candidates = [];

    // 1. ThingProxy - универсальный, передает заголовки
    candidates.push(`https://thingproxy.freeboard.io/fetch/${targetUrl}`);

    // 2. CorsProxy.io - быстрый, но бесплатная версия блокирует JSON в POST body.
    // Для GET запросов (проверка связи) он работает отлично.
    if (method === 'GET') {
        candidates.push(`https://corsproxy.io/?${encoded}`);
    }

    // 3. CodeTabs - запасной вариант
    candidates.push(`https://api.codetabs.com/v1/proxy?quest=${encoded}`);

    // 4. Прямой запрос - на случай если у пользователя есть расширение или VPN
    candidates.push(targetUrl);

    return candidates;
};

const fetchWithRobustProxy = async (url: string, options: RequestInit = {}, useProxy: boolean = false) => {
    const method = options.method || 'GET';
    const candidates = getProxyCandidates(url, useProxy, method);

    let lastError: any = null;
    let successResponse: Response | null = null;

    for (const fetchUrl of candidates) {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 20000); // 20 сек

        try {
            console.log(`Trying ${method} via: ${fetchUrl}`);
            const response = await fetch(fetchUrl, { ...options, signal: controller.signal });
            clearTimeout(timeoutId);

            // Обработка 401/400 от целевого сервиса - это УСПЕХ проксирования, но ошибка авторизации
            if (response.status === 401 || response.status === 400) {
                return response;
            }

            // Обработка ошибок прокси (403/429/500 часто от самого прокси)
            const isProxy = fetchUrl !== url;
            if (isProxy && !response.ok) {
                // Проверяем тело ответа на типичные ошибки прокси
                const text = await response.clone().text().catch(() => "");
                const lower = text.toLowerCase();
                const isProxyError = 
                    lower.includes("cors") || 
                    lower.includes("proxy") || 
                    lower.includes("limit") ||
                    lower.includes("content type");

                if (isProxyError || response.status === 403 || response.status === 429 || response.status >= 500) {
                    console.warn(`Proxy ${fetchUrl} failed: ${response.status} ${text.substring(0, 50)}`);
                    continue; // Пробуем следующий
                }
            }

            // Если ответ OK или это не явная ошибка прокси - возвращаем
            if (response.ok) {
                return response;
            }

            // Сохраняем ответ на случай если все прокси откажут, но этот был "наименее плохим"
            successResponse = response;

        } catch (error: any) {
            clearTimeout(timeoutId);
            console.warn(`Failed to fetch via ${fetchUrl}:`, error.message);
            lastError = error;
            continue;
        }
    }

    if (successResponse) return successResponse;

    throw lastError || new Error(`Не удалось выполнить ${method} запрос. Проверьте VPN/Прокси.`);
};

