  const handleTestSmm = async () => {
    setTestStatus({ loading: true, msg: 'Проверка подключения SmmBox...' });
    try {
        const tempConfig = { ...formData, smmBoxToken: formData.smmBoxToken.trim() };
        const groups = await fetchSmmBoxGroups(tempConfig);
