import { PublishingConfig, WordPressConfig, ProxyProvider } from "../types";

const SMMBOX_BASE_URL = "https://smmbox.com/api/v1";

const formatDateForWP = (dateStr: string) => {
    if (!dateStr) return null;
    return new Date(dateStr).toISOString().split('.')[0]; 
};

// Простая функция запроса через конкретный прокси
const fetchWithRobustProxy = async (url: string, options: RequestInit = {}, config: PublishingConfig) => {
    // 1. Прямое соединение (если выбрано пользователем)
    // Требует плагин "Allow CORS" в браузере
    if (!config.useProxy || config.proxyProvider === 'direct') {
        console.log(`[Direct] Fetching: ${url}`);
        return fetch(url, options);
    }

    // 2. Выбор прокси. По умолчанию - thingproxy (как было в январе)
    const provider = config.proxyProvider || 'thingproxy';
    const encoded = encodeURIComponent(url);
    let proxyUrl = '';

    switch (provider) {
        case 'codetabs':
            proxyUrl = `https://api.codetabs.com/v1/proxy?quest=${encoded}`;
            break;
        case 'corsproxy':
            proxyUrl = `https://corsproxy.io/?${encoded}`;
            break;
        case 'thingproxy':
        default:
            // Самый стабильный вариант для JSON API
            proxyUrl = `https://thingproxy.freeboard.io/fetch/${url}`;
            break;
    }

    // Обработка случая "auto" для обратной совместимости
    if (provider === 'auto') {
        proxyUrl = `https://thingproxy.freeboard.io/fetch/${url}`;
    }

    console.log(`[Proxy: ${provider}] ${proxyUrl}`);

    try {
        const response = await fetch(proxyUrl, options);

        // Если сам прокси вернул ошибку (например, перегружен)
        if (!response.ok) {
            // Пытаемся понять, ответил целевой сервер или прокси
            const contentType = response.headers.get("content-type");
            if (contentType && contentType.includes("text/html")) {
                // Скорее всего ошибка прокси (они часто отдают HTML страницы ошибок)
                throw new Error(`Прокси-сервер (${provider}) вернул ошибку ${response.status}. Попробуйте сменить сервер в настройках.`);
            }
        }

        return response;
    } catch (error: any) {
        console.error("Proxy Fetch Error:", error);
        if (error.message === 'Failed to fetch') {
            throw new Error(`Ошибка соединения (Failed to fetch). Прокси ${provider} недоступен. Попробуйте выбрать "CodeTabs" или установите плагин CORS и выберите "Прямое соединение".`);
        }
        throw error;
    }
};

export const fetchSmmBoxGroups = async (config: PublishingConfig) => {
    const url = `${SMMBOX_BASE_URL}/groups`;
    const response = await fetchWithRobustProxy(url, {
        method: 'GET',
        headers: { 'Authorization': `Bearer ${config.smmBoxToken}` }
    }, config);

    let data;
    const text = await response.text();
    try {
        data = JSON.parse(text);
    } catch (e) {
        // Если пришел не JSON, значит прокси вернул мусор или страницу ошибки
        throw new Error(`Ошибка ответа (не JSON). Возможно, прокси перегружен. Текст: ${text.substring(0, 50)}...`);
    }

    if (!response.ok) {
        throw new Error(`SmmBox Error (${response.status}): ${data.error?.message || JSON.stringify(data)}`);
    }

    if (data.error) throw new Error(`SmmBox API Error: ${data.error.message || JSON.stringify(data.error)}`);
    return data.response || [];
};

export const testWordPressConnection = async (wpConfig: WordPressConfig, useProxy: boolean, fullConfig: PublishingConfig) => {
    if (!wpConfig.url || !wpConfig.username || !wpConfig.applicationPassword) {
        throw new Error("Заполните все поля WordPress");
    }
    const auth = btoa(`${wpConfig.username}:${wpConfig.applicationPassword}`);
    const url = `${wpConfig.url.replace(/\/$/, '')}/wp-json/wp/v2/users/me`;

    const response = await fetchWithRobustProxy(url, {
        method: 'GET',
        headers: { 
            'Authorization': `Basic ${auth}`,
            'Content-Type': 'application/json'
        }
    }, fullConfig);

    if (!response.ok) {
         const text = await response.text();
         throw new Error(`WordPress Error (${response.status}): ${text.substring(0, 100)}`);
    }
    return await response.json();
};

export const publishToSmmBox = async (config: PublishingConfig, text: string, imagesBase64: string[] = [], publishDate?: Date) => {
    if (!config.smmBoxToken) throw new Error("Токен SmmBox не настроен");

    // Получаем группы
    const allGroups = await fetchSmmBoxGroups(config);

    // Фильтруем. SmmBox хранит ВК, ОК и ТГ внутри "проектов" или "групп". 
    // targetGroupName - это имя, которое пользователь дал группе ВНУТРИ SmmBox.
    const groups = allGroups.filter((g: any) => g.name.toLowerCase().includes(config.targetGroupName.toLowerCase()));

    if (groups.length === 0) {
        const available = allGroups.map((g: any) => g.name).join(', ');
        throw new Error(`Не найдено групп в SmmBox с именем "${config.targetGroupName}". Доступные группы: ${available || 'нет'}`);
    }

    const attachments: any[] = [{ type: 'text', text }];
    imagesBase64.slice(0, 3).forEach(img => {
        if (img?.startsWith('data:')) attachments.push({ type: 'photo', original: img });
    });

    const url = `${SMMBOX_BASE_URL}/posts/postpone`;
    const results = [];

    for (const group of groups) {
        const postPayload = {
            group: { id: group.id, social: group.social, type: group.type },
            attachments: attachments,
            options: ['from_group'],
            date: publishDate ? Math.floor(publishDate.getTime() / 1000) : Math.floor(Date.now() / 1000) + 180 
        };

        const body = { posts: [ postPayload ] };

        const response = await fetchWithRobustProxy(url, {
            method: 'POST',
            headers: { 
                'Content-Type': 'application/json', 
                'Authorization': `Bearer ${config.smmBoxToken}` 
            },
            body: JSON.stringify(body)
        }, config);

        const textResp = await response.text();
        let data;
        try {
            data = JSON.parse(textResp);
        } catch (e) {
            throw new Error(`SmmBox Invalid JSON: ${textResp.substring(0, 100)}`);
        }

        if (!response.ok) throw new Error(`SmmBox Error (${response.status}): ${data.error?.message || JSON.stringify(data)}`);
        if (data.error) throw new Error(`SmmBox Post Error: ${data.error.message || JSON.stringify(data.error)}`);
        results.push(data);
    }
    return results;
};

export const publishToWordPress = async (
    config: WordPressConfig, 
    useProxy: boolean,
    fullConfig: PublishingConfig,
    title: string, 
    sections: {heading: string, body: string}[], 
    imagesBase64: string[], 
    tags: string,
    metaDescription: string,
    publishDateStr?: string,
    onProgress?: (msg: string) => void
) => {
    const auth = btoa(`${config.username}:${config.applicationPassword}`);

    const uploadMedia = async (base64: string) => {
        const res = await fetch(base64);
        const blob = await res.blob();
        const fd = new FormData();
        fd.append('file', blob, `tour-img-${Date.now()}.png`);

        const r = await fetchWithRobustProxy(`${config.url.replace(/\/$/, '')}/wp-json/wp/v2/media`, {
            method: 'POST',
            headers: { 'Authorization': `Basic ${auth}` },
            body: fd
        }, fullConfig);

        if (!r.ok) throw new Error(`Image Upload Error: ${r.status}`);
        return await r.json();
    };

    const mediaUrls: string[] = [];
    for (const img of imagesBase64.slice(0, 3)) {
        try {
            if (onProgress) onProgress('Загрузка изображений...');
            const m = await uploadMedia(img);
            mediaUrls.push(m.source_url);
        } catch (e) { console.warn("Media upload failed", e); }
    }

    let content = '';
    sections.forEach((s, idx) => {
        if (s.heading) content += `<h2 class="wp-block-heading"><strong>${s.heading}</strong></h2>`;
        content += `<p>${s.body}</p>`;
        if (mediaUrls[idx]) content += `<figure class="wp-block-image size-large"><img src="${mediaUrls[idx]}" alt="${title}" /></figure>`;
    });

    if (tags) {
        content += `<hr /><p><strong>Теги:</strong> ${tags.replace(/#/g, '')}</p>`;
    }

    const wpDate = formatDateForWP(publishDateStr || "");
    const body: any = { 
        title, 
        content, 
        status: wpDate ? 'future' : 'publish', 
        excerpt: metaDescription 
    };
    if (wpDate) body.date = wpDate;

    if (onProgress) onProgress('Публикация статьи...');
    const r = await fetchWithRobustProxy(`${config.url.replace(/\/$/, '')}/wp-json/wp/v2/posts`, {
        method: 'POST',
        headers: { 'Authorization': `Basic ${auth}`, 'Content-Type': 'application/json' },
        body: JSON.stringify(body)
    }, fullConfig);

    if (!r.ok) {
        const err = await r.text();
        throw new Error(`WP Post Error (${r.status}): ${err}`);
    }
    return await r.json();
};

